            sections[cur]=[]
            k+=1; continue
        if cur is not None:
            sections[cur].append(l)
        k+=1
    return dict(cmd=cmd, about=about_s, usage=usage, sections=sections)

def unwrap(lines):
    # lines: list; join within paragraphs (non-blank runs), respecting indentation prefix
    out=[]
    i=0
    while i < len(lines):
        if lines[i].strip()=='':
            out.append('')
            i+=1
            continue
