{"command": "cat > /tmp/gen/parse.py <<'PYEOF'
import os, re, json, sys

HDIR='/tmp/h'
cmds = ['diff','files','id','log','name','show','edit','fold','new','refresh','rename','spill','sync','email','export','next','patches','prev','series','top','branch','clean','commit','delete','float','goto','hide','import','init','pick','pop','pull','push','rebase','redo','repair','reset','sink','squash','uncommit','undo','unhide','completion','version','help']

def read(p):
    return open(p).read()

def avail_for_about(): return 88
def avail_for_arghelp(): return 78

def unwrap_block(lines, avail):
    """lines: raw lines (with indent). unwrap greedy word-join within paragraphs."""
    out=[]
    i=0
    while i < len(lines):
        if lines[i].strip()=='':
            out.append(''); i+=1; continue
        indent = lines[i][:len(lines[i])-len(lines[i].lstrip())]
        txt = lines[i][len(indent):]
        buf=[txt]; i+=1
        while i<len(lines) and lines[i].strip()!='':
            b=lines[i][len(indent):]
            if len(buf[-1])+1+len(b.rstrip()) <= avail:
                buf[-1]=buf[-1]+' '+b
            else:
                buf.append(b)
            i+=1
        out.append(indent+'\n'.join(buf))
    return '\n'.join(out)

def parse_sections(lines, k):
    """from index k, parse sections. returns dict heading -> list of raw lines"""
    secs={}
    cur=None
    n=len(lines)
    while k < n:
        l=lines[k]
        if l=='':
            k+=1; continue
        if not l.startswith(' '):
            if l.endswith(':'):
                cur=l[:-1]; secs[cur]=[]; k+=1; continue
            else:
                break
        if cur is not None: secs[cur].append(l)
        k+=1
    return secs, k

def parse_args_from_long(lines):
    """parse a section's raw lines into list of arg dicts"""
    args=[]
    i=0
    while i < len(lines):
        l=lines[i]
        if l.strip()=='' : i+=1; continue
        spec=l[2:]
        i+=1
        helplines=[]
        while i<len(lines) and (lines[i].startswith('          ') or lines[i].strip()==''):
            helplines.append(lines[i][10:])
            i+=1
        while helplines and helplines[-1].strip()=='': helplines.pop()
        help_text = unwrap_block(helplines, 78)
        args.append(dict(spec=spec, longhelp=help_text))
    return args

def parse_short_args(lines):
    args=[]
    for l in lines:
        if l.strip()=='' : continue
        body=l[2:]
        m=re.match(r'^(\S+(?:,\s+\S+|\s+\S+)*)\s\s+(.*)$', body)
        if m:
            args.append(dict(spec=m.group(1), help=m.group(2).rstrip()))
        else:
            args.append(dict(spec=body, help=''))
    return args

def parse_cmd(cmd):
    longtxt = read(os.path.join(HDIR, cmd+'.txt'))
    shorttxt = read(os.path.join(HDIR, 'short-'+cmd+'.txt'))
    L=longtxt.split('\n')
    S=shorttxt.split('\n')
    ui = next(i for i,l in enumerate(L) if l.startswith('Usage: '))
    about_lines = L[:ui]
    while about_lines and about_lines[-1].strip()=='': about_lines.pop()
    longabout = unwrap_block(about_lines, 88)
    usage=[L[ui][7:]]
    j=ui+1
    while j < len(L) and L[j].startswith('       stg '):
        usage.append(L[j][7:]); j+=1
    secs, endk = parse_sections(L, j)
    si = next(i for i,l in enumerate(S) if l.startswith('Usage: '))
    shortabout = unwrap_block(S[:si], 88).strip('\n')
    if '\n' in shortabout: 
        shortabout = shortabout.split('\n')[0]
    # short usage should equal long usage
    ssecs, _ = parse_sections(S, si+1)
    out=dict(cmd=cmd, about=shortabout, longabout=longabout, usage=usage, sections={})
    for h, lines in secs.items():
        longargs = parse_args_from_long(lines)
        shortlines = ssecs.get(h, [])
        shortargs = parse_short_args(shortlines)
        smap = {}
        for sa in shortargs:
            # normalize spec
            smap[re.sub(r'\s+','',sa['spec'])] = sa['help']
        for a in longargs:
            key = re.sub(r'\s+','',a['spec'])
            a['help']=smap.get(key,'')
        out['sections'][h]=longargs
    return out

res={}
for c in cmds:
    try:
        res[c]=parse_cmd(c)
    except Exception as e:
        print("ERR", c, e)
json.dump(res, open('/tmp/gen/spec.json','w'), indent=1)
print("parsed", len(res), "commands")
for c,d in res.items():
    print(c, "about:", repr(d['about'][:60]), "| sections:", list(d['sections'].keys()))
