cat > vendor-shim/terminal_size/src/lib.rs <<'EOF'
//! Minimal reimplementation of the `terminal_size` crate API used by clap.
pub struct Width(pub u16);
pub struct Height(pub u16);

#[derive(Clone, Copy, Debug)]
pub struct TerminalSize {
    pub width: Width,
    pub height: Height,
}

#[repr(C)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

const TIOCGWINSZ: libc::c_ulong = 0x5413;

/// Report the size of the terminal associated with stdout.
pub fn terminal_size() -> Option<(Width, Height)> {
    use std::os::unix::io::AsRawFd;
    let fd = std::io::stdout().as_raw_fd();
    if fd < 0 {
        return None;
    }
    let mut ws = WinSize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
    let rc = unsafe { libc::ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) };
    if rc == 0 && ws.ws_col > 0 {
        Some((Width(ws.ws_col), Height(ws.ws_row)))
    } else {
        None
    }
}
EOF
