    s = specstr.strip()
    # normalize aligned spacing between short and long
    m2 = re.match(r'^-([a-zA-Z0-9])\s{2,}--([a-zA-Z0-9-]+)(.*)$', s)
    if m2:
        s = '-'+m2.group(1)+', --'+m2.group(2)+m2.group(3)
    # positional
    m = re.match(r'^(?:\[(?P<n1>[^>\]\[]+)\]|<(?P<n2>[^>\]\[]+)>)?(?P<v>\.\.\.)?$', s)
    if m:
        name = m.group('n1') or m.group('n2')
        variadic = bool(m.group('v'))
        required = s.startswith('<')
        return dict(pos=name, variadic=variadic, required=required)
    # option forms
    m = re.match(r'^-([a-zA-Z0-9]),\s+--([^\s=<\[]+)(.*)$', s)
    if m:
        return dict(short=m.group(1), long=m.group(2), rest=m.group(3))
    m = re.match(r'^--([^\s=<\[]+)(.*)$', s)
    if m:
        return dict(short=None, long=m.group(1), rest=m.group(2))
    m = re.match(r'^-([a-zA-Z0-9])\s*(.*)$', s)
    if m:
        return dict(short=m.group(1), long=None, rest=' '+m.group(2))
    raise Exception("spec? "+repr(s))

def rust_str(t):
    return json.dumps(t)

def gen_arg(a, heading=None):
    s = a['spec']
    p = parse_spec(s)
    if 'pos' in p:
        name = p['pos']
        code = f'Arg::new({rust_str(name)})'
        code += '.num_args(0..)' if p['variadic'] else '.num_args(1)'
        if p['required']:
            code += '.required(true)'
        elif p['variadic']:
            code += f'.value_name({rust_str(name)})'
        code += '.allow_hyphen_values(true)'
        if a['help']: code += f'.help({rust_str(a["help"])})'
        if a['longhelp']: code += f'.long_help({rust_str(a["longhelp"])})'
        return code
    lh = a['longhelp']
    if p['long']:
        idname = p['long']
        code = f'Arg::new({rust_str(p["long"])})'
        if p['short']: code += f'.short({chr(39)}{p["short"]}{chr(39)})'
        code += f'.long({rust_str(p["long"])})'
    else:
        code = f'Arg::new({rust_str(p["short"])})'
        code += f'.short({chr(39)}{p["short"]}{chr(39)})'
        idname = p['short']
    rest = p['rest']
    variadic = rest.strip().endswith('...')
    rest = rest.strip()
    rest = rest[:-3] if variadic else rest
    m = re.match(r'^(\[=)?<([^>\]]+)>', rest)
    if m and m.group(1):
        code += f'.num_args(0..=1).require_equals(true).value_name({rust_str(m.group(2))})'
    elif m:
        code += (f'.num_args(1..).value_name({rust_str(m.group(2))})' if variadic else f'.num_args(1).value_name({rust_str(m.group(2))})')
    else:
        if rest != '': raise Exception("rest? "+repr(rest))
    if re.search(r'multiple times', lh):
        code += '.action(ArgAction::Append)'
    if heading: code += f'.help_heading({rust_str(heading)})'
    if a['help']: code += f'.help({rust_str(a["help"])})'
    if lh: code += f'.long_help({rust_str(lh)})'
    return code

COLOR_SHORT = "When to colorize output: auto, always, ansi, never"

out=[]
out.append("// Auto-generated CLI definitions derived from the observed `--help` output.")
out.append("use clap::{Command, Arg, ArgAction};")
out.append("")
for c, d in spec.items():
    if c=='help': continue
    fn = 'cmd_'+c.replace('-','_')
    out.append(f'pub fn {fn}() -> Command {{')
    out.append(f'    Command::new({rust_str(c)})')
    out.append(f'        .about({rust_str(d["about"])})')
    out.append(f'        .long_about({rust_str(d["longabout"])})')
    if len(d['usage'])>1:
        usage = "\n       ".join(d["usage"])
        out.append(f'        .override_usage({rust_str(usage)})')
    for h, args in d['sections'].items():
        heading = None if h in ('Options','Arguments') else h
        if (c,h) in SKIP_SECTIONS: continue
        for a in args:
            sp = a['spec'].strip()
            if sp == '-h, --help': continue
            if sp == '--color <when>':
                a = dict(a); a['help'] = COLOR_SHORT
            try:
                code = gen_arg(a, heading)
            except Exception as e:
                print("ERR", c, h, a['spec'], e); continue
            out.append(f'        .arg({code})')
    out.append('}')
    out.append('')
open('/workspace/src/cli.rs','w').write('\n'.join(out))
print("wrote", len(out), "lines")
PYEOF
cd /tmp/gen && python3 gen.py && cd /workspace && cargo build --offline 2>&1 | grep -E "^error" -A 4 | head -20"}

