use std::io::IsTerminal;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ColorWhen {
    Auto,
    Always,
    Ansi,
    Never,
}

pub struct Colorizer {
    pub enabled: bool,
}

impl ColorWhen {
    pub fn parse(s: &str) -> Option<ColorWhen> {
        match s {
            "auto" => Some(ColorWhen::Auto),
            "always" => Some(ColorWhen::Always),
            "ansi" => Some(ColorWhen::Ansi),
            "never" => Some(ColorWhen::Never),
            _ => None,
        }
    }
}

impl Colorizer {
    pub fn new(when: Option<ColorWhen>) -> Colorizer {
        let enabled = match when {
            Some(ColorWhen::Always) => true,
            Some(ColorWhen::Never) => false,
            Some(ColorWhen::Ansi) => true,
            Some(ColorWhen::Auto) | None => {
                if std::env::var_os("NO_COLOR").is_some() {
                    false
                } else {
                    std::io::stdout().is_terminal()
                }
            }
        };
        Colorizer { enabled }
    }

    /// Wrap text in the given ANSI color, when colorizing is enabled.
    pub fn color(&self, code: &str, text: &str) -> String {
        if self.enabled {
            format!("\x1b[{}m{}\x1b[0m", code, text)
        } else {
            text.to_string()
        }
    }

    pub fn bold(&self, text: &str) -> String {
        self.color("1", text)
    }
}
EOF
sed -i 's/PartialEq, Eq,/PartialEq,/' src/color.rs
echo ok"}

