            prefix = relative_path(&cwd, &orig);
        }
        std::env::set_current_dir(&cwd).ok();
        let repo = open_repo(&cwd)?;
        let gitdir = repo
            .path()
            .canonicalize()
            .unwrap_or_else(|_| repo.path().to_path_buf())
            .to_path_buf();
        let workdir = match repo.workdir() {
            Some(w) => w.canonicalize().unwrap_or_else(|_| w.to_path_buf()),
            None => bail!("not a git repository"),
        };
        Ok(Ctx {
            repo,
            gitdir,
            workdir,
            prefix,
            color: Colorizer::new(Some(color)),
            args_cwd: cwd,
        })
    }

    /// Run a git subprocess with GIT_DIR / GIT_WORK_TREE set.
    pub fn git_run(&self, args: &[String], capture: bool) -> Result<std::process::Output> {
        use std::process::Command;
        let mut cmd = Command::new("git");
        cmd.args(args);
        cmd.env("GIT_DIR", self.gitdir.display().to_string());
        cmd.env("GIT_WORK_TREE", self.workdir.display().to_string());
        if capture {
            let out = cmd.output().map_err(|e| anyhow!("`git`: {e}"))?;
            if !out.status.success() {
                return Err(subprocess_error("git", args, &out));
            }
            Ok(out)
        } else {
            let status = cmd.status().map_err(|e| anyhow!("`git`: {e}"))?;
            Ok(std::process::Output {
                status,
                stdout: Vec::new(),
                stderr: Vec::new(),
            })
        }
    }

    pub fn git_stdout(&self, args: &[String]) -> Result<String> {
        let out = self.git_run(args, true)?;
        Ok(String::from_utf_lossy(&out.stdout).into_owned())
    }

    pub fn branch(&self) -> Result<String> {
        let head = self.repo.head()?;
        match head.shorthand() {
            Some(s) => Ok(s.to_string()),
            None => bail!("not on a branch"),
        }
    }
}

pub fn relative_path(from: &Path, to: &Path) -> String {
    use std::path::Component;
    let mut from = from.canonicalize().unwrap_or_else(|_| from.to_path_buf());
    let mut to = to.canonicalize().unwrap_or_else(|_| to.to_path_buf());
    let mut n = 0;
    loop {
        if from == to {
            break;
        }
        match (from.components().next(), to.components().next()) {
            (Some(af), Some(at)) if af == at => {
                from = from.components().skip(1).collect();
                to = to.components().skip(1).collect();
            }
            _ => {
                n += 1;
                from = match from.parent() {
                    Some(p) => p.to_path_buf(),
                    None => break,
                };
            }
        }
    }
    let mut s = String::new();
    for _ in 0..n {
        s.push_str("../");
    }
    s.push_str(&to.to_string_lossy());
    if s.is_empty() {
        s.push_str(".");
    }
    s
}

pub fn subprocess_error(cmd: &str, args: &[String], out: &std::process::Output) -> anyhow::Error {
    let mut s = String::new();
    s.push_str(&format!("`{}{}`: ", cmd, format_args(args)));
    let msg = String::from_utf_lossy(&out.stderr);
    let msg = msg.trim_end();
    s.push_str(msg);
    if !msg.is_empty() {
        s.push(';');
    }
    s.push_str("\ncommand aborted (all changes rolled back)");
    anyhow!(s)
}

pub fn format_args(args: &[String]) -> String {
    let mut s = String::new();
    for (i, a) in args.iter().enumerate() {
        if i > 0 {
            s.push(' ');
        }
        s.push_str(a);
    }
    s
}

pub fn oid_str(o: &Oid) -> String {
    format!("{:?}", o)
}
EOF
echo ok"}

