use git2::{Commit, Oid, ObjectType, Tree};
use std::collections::{BTreeMap, BTreeSet};

use crate::ctx::Ctx;

pub const STACK_VERSION: u32 = 5;

#[derive(Debug, Clone, Default)]
pub struct PatchMeta {
    pub bottom: Oid,
    pub top: Oid,
    pub author: String,
    pub date: String,
