                    continue;
                }
            }
            msg.push(l.to_string());
        }
        // the message ends with a trailing newline; drop the final empty entry
        if msg.len() > 1 && msg.last().map(|s| s.is_empty()).unwrap_or(false) {
            msg.pop();
        }
        meta.message = msg.join("\n");
        Ok(meta)
    }

    pub fn serialize(&self) -> String {
