}

#[derive(Debug, Clone, Default)]
pub struct Stack {
    pub branch: String,
    /// oid of the current stack state commit (the one `refs/stacks/<branch>` points to)
    pub state: Oid,
    /// oid of the "state" commit (the first parent of `state`), if any
    pub state_commit: Option<Oid>,
    pub prev: Option<Oid>,
    pub head: Oid,
    pub applied: Vec<String>,
    pub unapplied: Vec<String>,
    pub hidden: Vec<String>,
    pub patches: BTreeMap<String, Oid>,
    pub meta: BTreeMap<String, PatchMeta>,
    pub stack_ref: String,
}

pub fn stack_ref_name(branch: &str) -> String {
    format!("refs/stacks/{branch}")
}

pub fn patch_ref_name(branch: &str, name: &str) -> String {
    format!("refs/patches/{branch}/{name}")
}

impl Stack {
    pub fn is_initialized(&self) -> bool {
        !self.state.is_zero()
    }

    pub fn empty(branch: &str, head: Oid) -> Stack {
        Stack {
            branch: branch.to_string(),
            state: Oid::zero(),
            state_commit: None,
            prev: None,
            head,
            applied: Vec::new(),
            unapplied: Vec::new(),
            hidden: Vec::new(),
            patches: BTreeMap::new(),
            meta: BTreeMap::new(),
            stack_ref: stack_ref_name(branch),
        }
    }

    pub fn load(ctx: &Ctx, branch: &str) -> Result<Stack> {
        let head = ctx.repo.refname_to_id(&format!("refs/heads/{branch}"))?;
        let refname = stack_ref_name(branch);
        let state = match ctx.repo.find_reference(&refname) {
            Ok(r) => r.target().unwrap_or(Oid::zero()),
            Err(_) => Oid::zero(),
        };
        if state.is_zero() {
            return Ok(Stack::empty(branch, head));
        }
        let obj = ctx
            .repo
            .find_object(state, Some(git2::ObjectType::Commit))
            .with_context(|| anyhow!("invalid StGit stack state `{}`", state))?;
        let commit = obj.as_commit().ok_or_else(|| anyhow!("not a commit"))?;
        let tree = commit.tree()?;
        let stack = Stack::from_tree(ctx, branch, &tree, head, state)?;
        Ok(stack)
    }

    fn from_tree(
        ctx: &Ctx,
        branch: &str,
        tree: &Tree,
        head: Oid,
        state: Oid,
    ) -> Result<Stack> {
        let json_blob = tree
            .get_path(Path::new("stack.json"))?
            .to_object(ctx.repo.raw())?;
        let obj = ctx.repo.find_object(json_blob.id(), None)?;
        let data = obj.as_blob().ok_or_else(|| anyhow!("stack.json is not a blob"))?;
        let json = std::str::from_utf8(data.data())?;
        let v: serde_json::Value = serde_json::from_str(json)
            .map_err(|e| anyhow!("invalid stack.json: {e}"))?;
        let mut stack = Stack::empty(branch, head);
        stack.state = state;
        stack.prev = v
            .get("prev")
            .and_then(|x| x.as_str())
            .and_then(|s| Oid::from_str(s).ok());
        if let Some(h) = v.get("head").and_then(|x| x.as_str()).and_then(|s| Oid::from_str(s).ok()) {
            stack.head = h;
        }
        stack.applied = strlist(v.get("applied"));
        stack.unapplied = strlist(v.get("unapplied"));
        stack.hidden = strlist(v.get("hidden"));
        if let Some(p) = v.get("patches").and_then(|x| x.as_object()) {
            for (name, entry) in p {
                let oid = entry
                    .get("oid")
                    .and_then(|x| x.as_str())
                    .and_then(|s| Oid::from_str(s).ok())
                    .unwrap_or_default();
                stack.patches.insert(name.clone(), oid);
            }
        }
        // read patch metadata
        for (name, oid) in &stack.patches {
            if oid.is_zero() {
                continue;
            }
            let path = PathBuf::from("patches").join(name);
            if let Ok(entry) = tree.get_path(&path) {
                if let Ok(bid) = entry.to_object(ctx.repo.raw()) {
                    if let Ok(bobj) = ctx.repo.find_object(bid, None) {
                        if let Some(b) = bobj.as_blob() {
                            if let Ok(m) = PatchMeta::parse(b.data()) {
                                stack.meta.insert(name.clone(), m);
                            }
                        }
                    }
                }
            }
        }
        Ok(stack)
    }

    fn serialize(&self) -> Vec<u8> {
        let mut v = serde_json::Map::new();
        v.insert("version".to_string(), serde_json::Value::from(STACK_VERSION));
        v.insert(
            "prev".to_string(),
            match self.prev {
                Some(o) => serde_json::Value::from(o.to_string()),
                None => serde_json::Value::Null,
            },
        );
        v.insert("head".to_string(), serde_json::Value::from(self.head.to_string()));
        v.insert("applied".to_string(), serde_json::Value::from(self.applied.clone()));
        v.insert("unapplied".to_string(), serde_json::Value::from(self.unapplied.clone()));
        v.insert("hidden".to_string(), serde_json::Value::from(self.hidden.clone()));
        let mut p = serde_json::Map::new();
        for (name, oid) in &self.patches {
            let mut e = serde_json::Map::new();
            e.insert("oid".to_string(), serde_json::Value::from(oid.to_string()));
            p.insert(name.clone(), serde_json::Value::Object(e));
        }
        v.insert("patches".to_string(), serde_json::Value::Object(p));
        let mut s = serde_json::to_string_pretty(&serde_json::Value::Object(v)).unwrap();
        while s.ends_with('\n') {
            s.pop();
        }
        s.into_bytes()
    }

    /// Write the stack metadata to the repository: create a state commit, a
    /// merge commit, update refs/stacks/<branch>, refs/patches/... and
    /// refs/heads/<branch>.
    pub fn save(&mut self, ctx: &Ctx, msg: &str) -> Result<()> {
        let sig = ctx.repo.committer_from_env()?;
        // build tree
        let odb = ctx.repo.odb()?;
        let mut tb = ctx.repo.treebuilder(None)?;
        let json = self.serialize();
        let joid = odb.write(ObjectType::Blob, &json)?;
        tb.insert("stack.json", joid, 0o100644)?;
        for (name, meta) in &self.meta {
            let data = meta.serialize();
            let oid = odb.write(ObjectType::Blob, data.as_bytes())?;
            let path = format!("patches/{name}");
            tb.insert(path, oid, 0o100644)?;
        }
        let tree_oid = tb.write()?;
        let tree = ctx.repo.find_object(tree_oid, Some(ObjectType::Tree))?;
        let tree = tree.as_tree().ok_or_else(|| anyhow!("not a tree"))?;

        // state commit: parent is the previous state commit
        let mut parents: Vec<&Commit> = Vec::new();
        let mut prev_state_commit: Option<Commit> = None;
        if let Some(sc) = self.state_commit {
            let obj = ctx.repo.find_object(sc, Some(ObjectType::Commit))?;
            prev_state_commit = obj.as_commit().cloned();
        }
        if let Some(c) = &prev_state_commit {
            parents.push(c);
        }
        let state_oid = ctx.repo.commit(None, &sig, &sig, msg, tree, &parents)?;

        // merge commit
        let mut mparents: Vec<&Commit> = Vec::new();
        let state_obj = ctx.repo.find_object(state_oid, Some(ObjectType::Commit))?;
        let state_commit = state_obj.as_commit().cloned().unwrap();
        mparents.push(&state_commit);
        let head_obj = ctx.repo.find_object(self.head, Some(ObjectType::Commit))?;
        let head_commit = head_obj.as_commit().cloned().unwrap();
        mparents.push(&head_commit);
        let mut old_commit: Option<Commit> = None;
        if !self.state.is_zero() {
            let obj = ctx.repo.find_object(self.state, Some(ObjectType::Commit))?;
            old_commit = obj.as_commit().cloned();
            if let Some(c) = &old_commit {
                mparents.push(c);
            }
        }
        let merge_oid = ctx.repo.commit(None, &sig, &sig, msg, tree, &mparents)?;

        let refname = stack_ref_name(&self.branch);
        if self.state.is_zero() {
            ctx.repo.reference(&refname, merge_oid, true, msg)?;
        } else {
            ctx.repo
                .reference(&refname, merge_oid, true, msg)?;
        }

        // update patch refs
        let mut wanted: BTreeSet<String> = self.patches.keys().cloned().collect();
        // delete refs for patches no longer present
        let existing: Vec<String> = ctx
            .repo
            .references(Some("refs/patches"), true)
            .flatten()
            .map(|(name, _)| name)
            .collect();
        let pfx = format!("refs/patches/{}/", self.branch);
        for name in existing {
            if let Some(stripped) = name.strip_prefix(&pfx) {
                if !wanted.contains(stripped) {
                    if let Ok(r) = ctx.repo.find_reference(&name) {
                        r.delete().ok();
                    }
                } else {
                    wanted.remove(stripped);
                }
            }
        }
        for name in wanted {
            let oid = self.patches[&name];
            ctx.repo
                .reference(&patch_ref_name(&self.branch, &name), oid, true, msg)?;
        }
        // update branch ref
        if !self.head.is_zero() {
            ctx.repo
                .reference(&format!("refs/heads/{}", self.branch), self.head, true, msg)?;
        }

        self.prev = Some(merge_oid);
        self.state = merge_oid;
        self.state_commit = Some(state_oid);
        Ok(())
    }

    pub fn name_of(&self, oid: &Oid) -> Option<&str> {
        self.patches
            .iter()
            .find(|(_, o)| o == oid)
            .map(|(n, _)| n.as_str())
    }

    /// All patch names in stack order (applied, unapplied, hidden)
    pub fn all_names(&self) -> Vec<&str> {
        self.applied
            .iter()
            .chain(self.unapplied.iter())
            .chain(self.hidden.iter())
            .map(|s| s.as_str())
            .collect()
    }

    pub fn lookup(&self, name: &str) -> Option<&Oid> {
        self.patches.get(name)
    }
}

use std::path::{Path, PathBuf};

fn strlist(v: Option<&serde_json::Value>) -> Vec<String> {
    v.and_then(|x| x.as_array())
        .map(|a| a.iter().filter_map(|y| y.as_str().map(|s| s.to_string())).collect())
        .unwrap_or_default()
}
