#[derive(Debug, Clone, Default)]
pub struct PatchMeta {
    pub bottom: Oid,
    pub top: Oid,
    pub author: String,
    pub date: String,
    pub message: String,
}

impl PatchMeta {
    pub fn parse(data: &[u8]) -> Result<PatchMeta> {
        let text = String::from_utf_lossy(data);
        let mut lines = text.split('\n');
        let mut meta = PatchMeta::default();
        let mut header = true;
        let mut msg: Vec<String> = Vec::new();
        while let Some(l) = lines.next() {
            if header {
                if l.is_empty() {
                    header = false;
                    continue;
                }
                if let Some(rest) = l.strip_prefix("Bottom: ") {
                    meta.bottom = Oid::from_str(rest.trim()).unwrap_or_default();
                    continue;
                }
                if let Some(rest) = l.strip_prefix("Top: ") {
                    meta.top = Oid::from_str(rest.trim()).unwrap_or_default();
                    continue;
                }
                if let Some(rest) = l.strip_prefix("Author: ") {
                    meta.author = rest.trim().to_string();
                    continue;
                }
                if let Some(rest) = l.strip_prefix("Date: ") {
                    meta.date = rest.trim().to_string();
                    continue;
                }
            }
            msg.push(l.to_string());
        }
        // the message ends with a trailing newline; drop the final empty entry
        if msg.len() > 1 && msg.last().map(|s| s.is_empty()).unwrap_or(false) {
            msg.pop();
        }
        meta.message = msg.join("\n");
        Ok(meta)
    }

    pub fn serialize(&self) -> String {
        format!(
            "Bottom: {}\nTop:    {}\nAuthor: {}\nDate:   {}\n\n{}\n",
            self.bottom,
            self.top,
            self.author,
            self.date,
            self.message
        )
    }
}

