mod cli;
mod color;
mod ctx;
mod stack;
mod cmds;
mod git;
mod util;

use clap::{Arg, Command};
use color::ColorWhen;
use std::path::PathBuf;

pub const APP_NAME: &str = "stg";
pub const VERSION: &str = "2.5.5";

fn group_cmds() -> Vec<(&'static str, Vec<&'static str>)> {
    vec![
        ("Patch inspection commands", vec!["diff", "files", "id", "log", "name", "show"]),
        ("Patch manipulation commands", vec!["edit", "fold", "new", "refresh", "rename", "spill", "sync"]),
        ("Stack inspection commands", vec!["email", "export", "next", "patches", "prev", "series", "top"]),
        ("Stack manipulation commands", vec![
            "branch", "clean", "commit", "delete", "float", "goto", "hide", "import", "init",
            "pick", "pop", "pull", "push", "rebase", "redo", "repair", "reset", "sink", "squash",
            "uncommit", "undo", "unhide",
        ]),
        ("Administration commands", vec!["completion", "version"]),
    ]
}

fn aliases() -> Vec<(&'static str, &'static str)> {
    vec![
        ("add", "git -C \"$GIT_PREFIX\" add"),
        ("mv", "git -C \"$GIT_PREFIX\" mv"),
        ("resolved", "git -C \"$GIT_PREFIX\" add"),
        ("rm", "git -C \"$GIT_PREFIX\" rm"),
        ("status", "git status -s"),
    ]
}

fn alias_cmd(name: &str) -> Command {
    Command::new(name)
        .hide(true)
        .disable_help_flag(true)
        .disable_help_subcommand(true)
        .about("")
        .arg(
            Arg::new("args")
                .num_args(0..)
                .allow_hyphen_values(true)
                .last(true)
                .trailing_var_arg(true),
        )
}

fn root_cmd() -> Command {
    let mut groups_text = String::new();
    let mut first = true;
    for (heading, names) in group_cmds() {
        let longest = names.iter().map(|n| n.len()).max().unwrap_or(0);
        if !first {
            groups_text.push('\n');
        }
        first = false;
        groups_text.push_str(&format!("{heading}:\n"));
        for n in &names {
            let about = cli::about_of(n);
            groups_text.push_str(&format!("  {n:<longest$}  {about}\n"));
        }
    }
    // aliases
    let alias_names: Vec<&str> = aliases().iter().map(|(n, _)| *n).collect();
    let longest = alias_names.iter().map(|n| n.len()).max().unwrap_or(0);
    groups_text.push_str("Aliases:\n");
    for (n, c) in aliases() {
        let about = format!("Alias for shell command `{c}`");
        groups_text.push_str(&format!("  {n:<longest$}  {about}\n"));
    }
    groups_text.push_str("Help:\n  help  Print this message or the help of the given subcommand(s)");

    let mut cmd = Command::new(APP_NAME)
        .about("Maintain a stack of patches on top of a Git branch.")
        .long_about("Maintain a stack of patches on top of a Git branch.")
        .max_term_width(88)
        .help_template("{about-with-newline}\n{usage-heading} {usage}{before-help}\n\n{options}{after-help}")
        .before_help(&groups_text)
        .before_long_help(&groups_text)
        .override_usage("stg [OPTIONS] <command> [...]\n       stg [OPTIONS] <-h|--help>\n       stg --version")
        .disable_version_flag(true)
        .subcommand_required(false)
        .allow_external_subcommands(false)
        .arg(
            Arg::new("version")
                .long("version")
                .help("Print version information")
                .long_help("Print version information"),
        )
        .arg(
            Arg::new("cd")
                .short('C')
                .num_args(1)
                .value_name("path")
                .action(clap::ArgAction::Append)
                .help("Run as if started in <path>")
                .long_help(concat!(
                    "Run as if stg was started in '<path>' instead of the current working\n",
                    "directory. When multiple `-C` options are given, each subsequent non-absolute\n",
                    "`-C <path>` is interpreted relative to the preceding `-C <path>`.\n\n",
                    "This option affects arguments that expect path names or path specs in that\n",
                    "their interpretations of the path names would be made relative to the working\n",
                    "directory caused by the `-C` option."
                )),
        );
    for (_, names) in group_cmds() {
        for n in names {
            let sub = cli::subcommand(n);
            cmd = cmd.subcommand(sub.hide(true));
        }
    }
    for (name, _) in aliases() {
        cmd = cmd.subcommand(alias_cmd(name));
    }
    cmd
}

fn main() {
    let root = root_cmd();
    let matches = match root.clone().try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            e.print().expect("clap can print its error message");
            std::process::exit(1);
        }
    };
    let code = cmds::dispatch(&root, &matches);
    std::process::exit(code);
}
