use anyhow::{anyhow, bail, Context as _, Result};
use git2::{Oid, ObjectType};
use std::collections::{BTreeMap, BTreeSet};
use std::io::Write;
use std::path::Path;

use crate::ctx::Ctx;

/// Write a blob into the object database and return its oid.
pub fn write_blob(ctx: &Ctx, data: &[u8]) -> Result<Oid> {
    let odb = ctx.repo.odb()?;
    odb.write(ObjectType::Blob, data)
}

/// Build a tree from a map of path -> (oid, mode).
pub fn build_tree(
    ctx: &Ctx,
    entries: &BTreeMap<String, (Oid, u32)>,
) -> Result<Oid> {
    let mut tb = ctx.repo.treebuilder(None)?;
    for (path, (oid, mode)) in entries {
        tb.insert(path.as_str(), *oid, *mode)?;
    }
    tb.write()
}

/// Read a blob from a tree.
pub fn tree_blob(ctx: &Ctx, tree: &git2::Tree, path: &str) -> Option<Vec<u8>> {
    let entry = tree.get_path(Path::new(path)).ok()?;
    let bid = entry.to_object(ctx.repo.raw()).ok()?;
    let obj = ctx.repo.find_object(bid, None).ok()?;
    let b = obj.as_blob()?;
    Some(b.data().to_vec())
}

/// Create a commit object.
pub fn create_commit(
    ctx: &Ctx,
    tree_oid: Oid,
    parents: &[Oid],
    message: &str,
    time_override: Option<i64>,
) -> Result<Oid> {
    let tree_obj = ctx.repo.find_object(tree_oid, Some(ObjectType::Tree))?;
    let tree = tree_obj
        .as_tree()
        .ok_or_else(|| anyhow!("expected tree object"))?;
    let sig_author = match time_override {
        Some(t) => {
            let name = committer_name(ctx)?;
            let email = committer_email(ctx)?;
            git2::build::Signature::new(&name, &email, &git2::Time::new(t, 0))?
        }
        None => ctx.repo.committer_from_env()?,
    };
    let sig_committer = match time_override {
        Some(t) => {
            let name = committer_name(ctx)?;
            let email = committer_email(ctx)?;
            git2::build::Signature::new(&name, &email, &git2::Time::new(t, 0))?
        }
        None => ctx.repo.committer_from_env()?,
    };
    let mut parent_objs = Vec::new();
    for p in parents {
        let o = ctx.repo.find_object(*p, Some(ObjectType::Commit))?;
        parent_objs.push(o.as_commit().cloned().unwrap());
    }
    let refs: Vec<&git2::Commit> = parent_objs.iter().collect();
    let oid = ctx
        .repo
        .commit(None, &sig_author, &sig_committer, message, tree, &refs)?;
    Ok(oid)
}

pub fn committer_name(ctx: &Ctx) -> Result<String> {
    match ctx.repo.config()?.get_string("user.name") {
        Ok(v) => Ok(v),
        Err(_) => bail!("committer name not set"),
    }
}

pub fn committer_email(ctx: &Ctx) -> Result<String> {
    match ctx.repo.config()?.get_string("user.email") {
        Ok(v) => Ok(v),
        Err(_) => bail!("committer email not set"),
    }
}

pub fn committer(ctx: &Ctx) -> Result<String> {
    let name = committer_name(ctx)?;
    let email = committer_email(ctx)?;
    Ok(format!("{name} <{email}>"))
}

/// Determine whether the index and the work tree are clean.
/// Returns (index_clean, worktree_clean).
pub fn cleanliness(ctx: &Ctx) -> Result<(bool, bool)> {
    let mut opts = git2::StatusOptions::new();
    opts.include_untracked(false)
        .recurse_untracked_dirs(false)
        .exclude_submodules(true)
        .include_ignored(false)
        .no(true)
        .update_index(false);
    let statuses = ctx.repo.statuses(Some(&mut opts))?;
    let mut index_dirty = false;
    let mut worktree_dirty = false;
    for e in statuses.iter() {
        if let Some(d) = e.head_to_index() {
            if !matches!(d.status(), git2::Delta::Unmodified) {
                index_dirty = true;
            }
        }
        if let Some(d) = e.index_to_worktree() {
            if !matches!(d.status(), git2::Delta::Unmodified) {
                worktree_dirty = true;
            }
        }
    }
    Ok((!index_dirty, !worktree_dirty))
}

/// Throw an error if the work tree is not clean.
pub fn check_worktree(ctx: &Ctx) -> Result<()> {
    let (_, w) = cleanliness(ctx)?;
    if !w {
        bail!("worktree not clean; use `refresh` or `reset --hard`");
    }
    Ok(())
}

/// Throw an error if the index is not clean.
pub fn check_index(ctx: &Ctx) -> Result<()> {
    let (i, w) = cleanliness(ctx)?;
    if !i {
        bail!("index not clean; use `refresh` or `reset --hard`");
    }
    if !w {
        bail!("worktree not clean; use `refresh` or `reset --hard`");
    }
    Ok(())
}

/// Update the index and work tree to match the given tree.
pub fn checkout_tree(ctx: &Ctx, tree_oid: Oid, remove_untracked: bool) -> Result<()> {
    let obj = ctx.repo.find_object(tree_oid, Some(ObjectType::Tree))?;
    let tree = obj
        .as_tree()
        .ok_or_else(|| anyhow!("expected tree object"))?;
    let mut opts = git2::build::CheckoutBuilder::new();
    opts.force()
        .update_index(true)
        .refresh(true)
        .remove_untracked(remove_untracked)
        .recreate_missing(true)
        .overwrite_ignored(true)
        .safe();
    ctx.repo.checkout_tree(tree, Some(&mut opts))?;
    Ok(())
}

/// The tree of the current index.
pub fn index_tree(ctx: &Ctx) -> Result<Oid> {
    let index = ctx.repo.index()?;
    index.write_tree()
}

/// Write the index tree to the odb and return it.
pub fn write_index_tree(ctx: &Ctx) -> Result<Oid> {
    let mut index = ctx.repo.index()?;
    let oid = index.write_tree_to(&ctx.repo)?;
    Ok(oid)
}

/// List the paths of a tree (recursive), sorted.
pub fn tree_paths(ctx: &Ctx, tree: &git2::Tree) -> Result<Vec<String>> {
    let mut out = Vec::new();
    let mut walk: Vec<(String, git2::Oid)> = Vec::new();
    collect_tree(ctx, tree, String::new(), &mut out, &mut walk)?;
    Ok(out)
}

fn collect_tree(
    ctx: &Ctx,
    tree: &git2::Tree,
    prefix: String,
    out: &mut Vec<String>,
    _walk: &mut Vec<(String, Oid)>,
) -> Result<()> {
    let mut names: Vec<(String, git2::ObjectType, Oid)> = Vec::new();
    for i in 0..tree.len() {
        let e = tree.get(i).ok_or_else(|| anyhow!("bad tree entry"))?;
        let name = e.name().to_string();
        let oid = e.id();
        let kind = e.kind();
        names.push((name, kind, oid));
    }
    for (name, kind, oid) in names {
        let full = if prefix.is_empty() {
            name.clone()
        } else {
            format!("{prefix}/{name}")
        };
        if kind == git2::ObjectType::Tree {
            let obj = ctx.repo.find_object(oid, Some(ObjectType::Tree))?;
            let sub = obj.as_tree().ok_or_else(|| anyhow!("expected tree"))?;
            collect_tree(ctx, sub, full, out, _walk)?;
        } else {
            out.push(full);
        }
    }
    Ok(())
}

/// Write data to stdout, handling broken pipes.
pub fn out_write(data: &[u8]) -> Result<()> {
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    lock.write_all(data).map_err(|e| {
        if e.kind() == std::io::ErrorKind::BrokenPipe {
            anyhow!("`git log`: broken pipe")
        } else {
            anyhow!("{e}")
        }
    })
}
