use anyhow::Result;
use std::io::Write;

/// Print to stdout.
pub fn out(s: &str) {
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(s.as_bytes());
}

pub fn outln(s: &str) {
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(s.as_bytes());
    let _ = lock.write_all(b"\n");
}

pub fn errln(s: &str) {
    let stderr = std::io::stderr();
    let mut lock = stderr.lock();
    let _ = lock.write_all(s.as_bytes());
    let _ = lock.write_all(b"\n");
}

/// Wrap text to the given width, preserving existing newlines.
pub fn wrap(text: &str, width: usize) -> String {
    let mut out = Vec::new();
    for line in text.split('\n') {
        if line.is_empty() {
            out.push(String::new());
            continue;
        }
        let words: Vec<&str> = line.split(' ').collect();
        let mut cur = String::new();
        for w in words {
            if cur.is_empty() {
                cur.push_str(w);
            } else if cur.len() + 1 + w.len() <= width {
                cur.push(' ');
                cur.push_str(w);
            } else {
                out.push(cur.clone());
                cur = w.to_string();
            }
        }
        out.push(cur);
    }
    out.join("\n")
}

/// Format a git time as `YYYY-MM-DD HH:MM:SS +ZZZZ`.
pub fn format_git_date(t: i64, offset_minutes: i32) -> String {
    let (date, tz) = civil_date(t, offset_minutes);
    format!("{date} {tz}")
}

pub fn civil_date(t: i64, offset_minutes: i32) -> (String, String) {
    let total = t + (offset_minutes as i64) * 60;
    let days = total.div_euclid(86400);
    let secs = total.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    let hh = secs / 3600;
    let mm = (secs % 3600) / 60;
    let ss = secs % 60;
    let sign = if offset_minutes < 0 { '-' } else { '+' };
    let aoff = offset_minutes.abs();
    let tz = format!("{sign}{:02}{:02}", aoff / 60, aoff % 60);
    (format!("{y:04}-{m:02}-{d:02} {hh:02}:{mm:02}:{ss:02}"), tz)
}

pub fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}
