    let entry = tree.get_path(Path::new(path)).ok()?;
    let bid = entry.to_object(ctx.repo.raw()).ok()?;
    let obj = ctx.repo.find_object(bid, None).ok()?;
    let b = obj.as_blob()?;
    Some(b.data().to_vec())
}

/// Create a commit object.
pub fn create_commit(
    ctx: &Ctx,
    tree_oid: Oid,
    parents: &[Oid],
    message: &str,
    time_override: Option<i64>,
) -> Result<Oid> {
    let tree_obj = ctx.repo.find_object(tree_oid, Some(ObjectType::Tree))?;
    let tree = tree_obj
        .as_tree()
        .ok_or_else(|| anyhow!("expected tree object"))?;
    let sig_author = match time_override {
        Some(t) => {
            let name = committer_name(ctx)?;
            let email = committer_email(ctx)?;
            git2::build::Signature::new(&name, &email, &git2::Time::new(t, 0))?
        }
        None => ctx.repo.committer_from_env()?,
    };
    let sig_committer = match time_override {
        Some(t) => {
            let name = committer_name(ctx)?;
            let email = committer_email(ctx)?;
            git2::build::Signature::new(&name, &email, &git2::Time::new(t, 0))?
        }
        None => ctx.repo.committer_from_env()?,
    };
