    for p in parents {
        let o = ctx.repo.find_object(*p, Some(ObjectType::Commit))?;
        parent_objs.push(o.as_commit().cloned().unwrap());
    }
    let refs: Vec<&git2::Commit> = parent_objs.iter().collect();
    let oid = ctx
        .repo
        .commit(None, &sig_author, &sig_committer, message, tree, &refs)?;
