}

/// Determine whether the index and the work tree are clean.
/// Returns (index_clean, worktree_clean).
pub fn cleanliness(ctx: &Ctx) -> Result<(bool, bool)> {
    let mut opts = git2::StatusOptions::new();
    opts.include_untracked(false)
        .recurse_untracked_dirs(false)
        .exclude_submodules(true)
        .include_ignored(false)
        .no(true)
        .update_index(false);
    let statuses = ctx.repo.statuses(Some(&mut opts))?;
    let mut index_dirty = false;
    let mut worktree_dirty = false;
    for e in statuses.iter() {
        if let Some(d) = e.head_to_index() {
            if !matches!(d.status(), git2::Delta::Unmodified) {
                index_dirty = true;
            }
        }
        if let Some(d) = e.index_to_worktree() {
            if !matches!(d.status(), git2::Delta::Unmodified) {
                worktree_dirty = true;
            }
        }
    }
    Ok((!index_dirty, !worktree_dirty))
}

