    let tree = obj
        .as_tree()
        .ok_or_else(|| anyhow!("expected tree object"))?;
    let mut opts = git2::build::CheckoutBuilder::new();
    opts.force()
        .update_index(true)
        .refresh(true)
        .remove_untracked(remove_untracked)
        .recreate_missing(true)
        .overwrite_ignored(true)
        .safe();
    ctx.repo.checkout_tree(tree, Some(&mut opts))?;
    Ok(())
}

/// The tree of the current index.
pub fn index_tree(ctx: &Ctx) -> Result<Oid> {
    let index = ctx.repo.index()?;
    index.write_tree()
}

/// Write the index tree to the odb and return it.
pub fn write_index_tree(ctx: &Ctx) -> Result<Oid> {
    let mut index = ctx.repo.index()?;
    let oid = index.write_tree_to(&ctx.repo)?;
    Ok(oid)
}

/// List the paths of a tree (recursive), sorted.
pub fn tree_paths(ctx: &Ctx, tree: &git2::Tree) -> Result<Vec<String>> {
    let mut out = Vec::new();
    let mut walk: Vec<(String, git2::Oid)> = Vec::new();
    collect_tree(ctx, tree, String::new(), &mut out, &mut walk)?;
    Ok(out)
}

fn collect_tree(
    ctx: &Ctx,
    tree: &git2::Tree,
    prefix: String,
    out: &mut Vec<String>,
    _walk: &mut Vec<(String, Oid)>,
) -> Result<()> {
    let mut names: Vec<(String, git2::ObjectType, Oid)> = Vec::new();
    for i in 0..tree.len() {
        let e = tree.get(i).ok_or_else(|| anyhow!("bad tree entry"))?;
        let name = e.name().to_string();
        let oid = e.id();
        let kind = e.kind();
        names.push((name, kind, oid));
    }
    for (name, kind, oid) in names {
        let full = if prefix.is_empty() {
            name.clone()
        } else {
            format!("{prefix}/{name}")
        };
        if kind == git2::ObjectType::Tree {
            let obj = ctx.repo.find_object(oid, Some(ObjectType::Tree))?;
            let sub = obj.as_tree().ok_or_else(|| anyhow!("expected tree"))?;
            collect_tree(ctx, sub, full, out, _walk)?;
        } else {
            out.push(full);
        }
    }
    Ok(())
}

/// Write data to stdout, handling broken pipes.
pub fn out_write(data: &[u8]) -> Result<()> {
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    lock.write_all(data).map_err(|e| {
        if e.kind() == std::io::ErrorKind::BrokenPipe {
            anyhow!("`git log`: broken pipe")
        } else {
            anyhow!("{e}")
        }
    })
}
