pub const EXIT_OK: i32 = 0;
pub const EXIT_ERROR: i32 = 2;
pub const EXIT_CONFLICT: i32 = 3;

pub fn dispatch(root: &Command, m: &ArgMatches) -> i32 {
    let color = color_of(m);
    let cd = cd_paths(m);
    if let Some(_) = m.get_flag("version") {
        return print_version(&color);
    }
    let sub = match m.subcommand_name() {
        Some(s) => s,
        None => return 1,
    };
    let sc = m.subcommand_matches(sub).unwrap();
    let res = run(root, sub, sc, cd, color);
    match res {
        Ok(code) => code,
        Err(e) => {
            errln(&format!("error: {e}"));
            if e.is_conflict() {
                EXIT_CONFLICT
            } else {
                EXIT_ERROR
            }
        }
    }
}

fn run(
    _root: &Command,
    sub: &str,
    m: &ArgMatches,
    cd: Vec<PathBuf>,
    color: ColorWhen,
) -> Result<i32> {
    if let Some(alias) = crate::cmds::aliases::lookup(sub) {
        return aliases::run_alias(alias, m, cd, color);
    }
    let mut ctx = Ctx::open(if cd.is_empty() { None } else { Some(cd) }, color)?;
    let code = match sub {
        "version" => version_cmd(&ctx, m),
        "init" => init(&ctx, m),
        "series" => series(&ctx, m),
        "top" => top(&ctx, m),
        "next" => next(&ctx, m),
        "prev" => prev(&ctx, m),
        "name" => name(&ctx, m),
        "id" => id(&ctx, m),
        "log" => log(&ctx, m),
        "show" => show(&ctx, m),
        "diff" => diff(&ctx, m),
        "files" => files(&ctx, m),
        "patches" => patches(&ctx, m),
        "branch" => branch(&ctx, m),
        "clean" => clean(&ctx, m),
        "new" => new(&ctx, m),
        "commit" => commit(&ctx, m),
        "uncommit" => uncommit(&ctx, m),
        "push" => push(&ctx, m),
        "pop" => pop(&ctx, m),
        "goto" => goto(&ctx, m),
        "float" => float(&ctx, m),
        "sink" => sink(&ctx, m),
        "hide" => hide(&ctx, m),
        "unhide" => unhide(&ctx, m),
        "delete" => delete(&ctx, m),
        "rename" => rename(&ctx, m),
        "reset" => reset(&ctx, m),
        "undo" => undo(&ctx, m),
        "redo" => redo(&ctx, m),
        "refresh" => refresh(&ctx, m),
        "edit" => edit(&ctx, m),
        "squash" => squash(&ctx, m),
        "spill" => spill(&ctx, m),
        "fold" => fold(&ctx, m),
        "import" => import(&ctx, m),
        "export" => export(&ctx, m),
