    code
}

fn color_of(m: &ArgMatches) -> ColorWhen {
    m.get_one::<String>("color")
        .and_then(|s| ColorWhen::parse(s))
        .unwrap_or(ColorWhen::Auto)
}

fn cd_paths(m: &ArgMatches) -> Vec<PathBuf> {
    m.get_many::<String>("cd")
        .map(|v| v.map(|s| PathBuf::from(s)).collect())
        .unwrap_or_default()
}

fn branch_of(ctx: &Ctx, m: &ArgMatches) -> Result<String> {
    match m.get_one::<String>("branch") {
        Some(b) => Ok(b.clone()),
        None => ctx.branch(),
    }
}

fn stack_of(ctx: &Ctx, m: &ArgMatches) -> Result<Stack> {
    let b = branch_of(ctx, m)?;
    Stack::load(ctx, &b)
}

fn print_version(color: &crate::color::Colorizer) -> i32 {
    let _ = color;
    out(&version_text(false));
    EXIT_OK
}

pub fn version_text(_short: bool) -> String {
    let gitver = crate::cmds::git_version();
    format!(
        "Stacked Git {VERSION}\nCopyright (C) 2005-2025 StGit authors\nThis is free software: you are free to change and redistribute it.\nThere is NO WARRANTY, to the extent permitted by law.\nSPDX-License-Identifier: GPL-2.0-only\ngit version {gitver}\n"
    )
}

fn version_cmd(ctx: &Ctx, m: &ArgMatches) -> i32 {
    if m.get_flag("short") {
        out(&format!(
            "Stacked Git {VERSION}\ngit version {}\n",
            crate::cmds::git_version()
        ));
    } else {
        out(&version_text(false));
    }
    EXIT_OK
}

fn help(root: &Command) -> i32 {
    let mut c = root.clone();
    let s = c.render_help();
    out(&s.to_string());
    EXIT_OK
}

// ---------------------------------------------------------------- series

fn series(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let stack = stack_of(ctx, m)?;
    let branch = stack.branch.clone();
    let mut sel = SeriesSel::default();
    sel.all = m.get_flag("all");
    sel.applied_only = m.get_flag("applied");
    sel.unapplied_only = m.get_flag("unapplied");
    sel.hidden_only = m.get_flag("hidden");
    sel.short = m.get_one::<String>("short").map(|s| s.clone());
    sel.showbranch = m.get_flag("showbranch");
    sel.no_prefix = m.get_flag("no-prefix");
    sel.empty = m.get_flag("empty");
    sel.indices = m.get_flag("indices");
    sel.offsets = m.get_flag("offsets");
    sel.oid = m.get_flag("commit-id");
    sel.oid_len = m.get_one::<String>("commit-id").cloned();
    sel.descr = m.get_flag("description");
    sel.author = m.get_flag("author");
    sel.reverse = m.get_flag("reverse");
    sel.count = m.get_flag("count");
    sel.names = m.get_many::<String>("patch").map(|v| v.cloned().collect()).unwrap_or_default();
    sel.missing = m.get_one::<String>("missing").cloned();
    let out_s = series_render(ctx, &stack, &sel)?;
    if sel.count {
        outln(&format!("{}", sel.count_out));
        return Ok(EXIT_OK);
    }
    out(&out_s);
    Ok(EXIT_OK)
}

#[derive(Default)]
pub struct SeriesSel {
    pub all: bool,
    pub applied_only: bool,
    pub unapplied_only: bool,
    pub hidden_only: bool,
    pub short: Option<String>,
    pub showbranch: bool,
    pub no_prefix: bool,
    pub empty: bool,
    pub indices: bool,
    pub offsets: bool,
    pub oid: bool,
    pub oid_len: Option<String>,
    pub descr: bool,
    pub author: bool,
