    pub names: Vec<String>,
    pub missing: Option<String>,
    pub count_out: usize,
}

/// A patch entry in the series display.
#[derive(Clone, Debug)]
pub struct SeriesEntry {
    pub name: String,
    pub oid: Oid,
    pub prefix: char,
    pub empty: bool,
}

pub fn series_select(stack: &Stack, sel: &SeriesSel) -> Result<Vec<SeriesEntry>> {
    let mut entries = Vec::new();
    let top = stack.applied.last().cloned();
    let n_applied = stack.applied.len();
    let mut idx = 0usize;
    for (i, name) in stack.applied.iter().enumerate() {
        let prefix = if Some(name) == top.as_ref() { '>' } else { '+' };
        let oid = stack.patches.get(name).copied().unwrap_or_default();
        let empty = is_empty_patch(stack, name, oid);
        entries.push(SeriesEntry { name: name.clone(), oid, prefix, empty });
        let _ = i;
        idx += 1;
        let _ = n_applied;
    }
    for name in stack.unapplied.iter() {
        let oid = stack.patches.get(name).copied().unwrap_or_default();
        entries.push(SeriesEntry { name: name.clone(), oid, prefix: '-', empty: is_empty_patch(stack, name, oid) });
        idx += 1;
    }
    if sel.all || sel.hidden_only {
        for name in stack.hidden.iter() {
            let oid = stack.patches.get(name).copied().unwrap_or_default();
            entries.push(SeriesEntry { name: name.clone(), oid, prefix: '!', empty: is_empty_patch(stack, name, oid) });
            idx += 1;
        }
    }
    let _ = idx;
    // filter
    let mut list = entries;
    if sel.applied_only {
        list.retain(|e| e.prefix == '+' || e.prefix == '>');
    } else if sel.unapplied_only {
        list.retain(|e| e.prefix == '-');
    } else if sel.hidden_only {
        list.retain(|e| e.prefix == '!');
    } else if !sel.all {
        list.retain(|e| e.prefix != '!');
    }
    if !sel.names.is_empty() {
        let ranges: Vec<(Option<String>, Option<String>)> = sel
            .names
            .iter()
            .map(|n| {
                if let Some(p) = n.find("..") {
                    let a = &n[..p];
                    let b = &n[p + 2..];
                    (
                        if a.is_empty() { None } else { Some(a.to_string()) },
                        if b.is_empty() { None } else { Some(b.to_string()) },
                    )
                } else {
                    (Some(n.clone()), Some(n.clone()))
                }
            })
            .collect();
        let orig = list.clone();
        list.retain(|e| {
            ranges.iter().any(|(a, b)| {
                let s = orig.iter().position(|x| x.name == e.name).unwrap_or(0);
                let mut ok = true;
                if let Some(a) = a {
                    if let Some(ai) = orig.iter().position(|x| &x.name == a) {
                        ok = ok && s >= ai;
                    }
                }
                if let Some(b) = b {
                    if let Some(bi) = orig.iter().position(|x| &x.name == b) {
                        ok = ok && s <= bi;
                    }
                }
                ok
            })
        });
    }
    if let Some(short) = &sel.short {
        let n: usize = short.parse().unwrap_or(5);
        // keep the last n+1 applied patches plus all unapplied
        let applied: Vec<SeriesEntry> = list.iter().filter(|e| e.prefix == '+' || e.prefix == '>').cloned().collect();
        let rest: Vec<SeriesEntry> = list.iter().filter(|e| e.prefix != '+' && e.prefix != '>').cloned().collect();
        let keep = applied.len().saturating_sub(n + 1);
        let kept: Vec<SeriesEntry> = applied[keep..].to_vec();
        list = kept.into_iter().chain(rest).collect();
    }
    if let Some(branch) = &sel.missing {
        let _ = branch;
    }
    Ok(list)
}

pub fn series_render(ctx: &Ctx, stack: &Stack, sel: &SeriesSel) -> Result<String> {
    let list = series_select(stack, sel)?;
    let n_applied = stack.applied.len();
    let mut lines = Vec::new();
    let mut count = list.len();
    let _ = &mut count;
    for (i, e) in list.iter().enumerate() {
        let idx = i;
        let offset = if e.prefix == '+' || e.prefix == '>' {
            idx as i64 - (n_applied as i64 - 1)
        } else {
            idx as i64 + 1
        };
        let mut line = String::new();
        if sel.empty {
            line.push(if e.empty { '*' } else { ' ' });
        }
        if !sel.no_prefix {
            line.push(e.prefix);
            line.push(' ');
        } else if !sel.empty {
            // no prefix and no empty column
        }
        if sel.indices {
            line.push_str(&format!("{idx} "));
        }
        if sel.offsets {
            line.push_str(&format!("{offset:+} "));
        }
        if sel.oid {
            let s = e.oid.to_string();
            let l = match &sel.oid_len {
                Some(v) => {
                    if let Ok(n) = v.parse::<usize>() {
                        if n == 0 {
                            s.len()
                        } else {
                            n
                        }
                    } else {
                        s.len()
                    }
                }
                None => s.len(),
            };
            line.push_str(&format!("{} ", &s[..l.min(s.len())]));
        }
        if sel.showbranch {
            line.push_str(&format!("{}:{}", stack.branch, e.name));
        } else {
            line.push_str(&e.name);
        }
        if sel.author {
            let a = stack
                .meta
                .get(&e.name)
                .map(|m| m.author.clone())
                .unwrap_or_default();
            line.push_str(&format!(" # {a}"));
        }
        if sel.descr {
            let d = stack
                .meta
                .get(&e.name)
                .map(|m| m.message.lines().next().unwrap_or("").to_string())
                .unwrap_or_default();
            line.push_str(&format!(" # {d}"));
        }
        lines.push(crate::color::series_line(ctx, &line, e.prefix, e.empty));
    }
    sel.count_out = lines.len();
    let mut s = lines.join("\n");
    if !lines.is_empty() {
        s.push('\n');
    }
    Ok(s)
}

pub fn is_empty_patch(stack: &Stack, name: &str, oid: Oid) -> bool {
    let meta = match stack.meta.get(name) {
        Some(m) => m,
        None => return true,
    };
    meta.bottom == meta.top
}

// ---------------------------------------------------------------- init

fn init(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let branch = branch_of(ctx, m)?;
    let head = match ctx.repo.refname_to_id(&format!("refs/heads/{branch}")) {
        Ok(h) => h,
        Err(_) => bail!("branch `{branch}` not found"),
    };
    let refname = crate::stack::stack_ref_name(&branch);
    if ctx.repo.find_reference(&refname).is_ok() {
        bail!("branch `{branch}` is already initialized");
    }
    let mut stack = Stack::empty(&branch, head);
    stack.save(ctx, "initialize")?;
    Ok(EXIT_OK)
}

// ---------------------------------------------------------------- top/next/prev

fn top(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let stack = stack_of(ctx, m)?;
    match stack.applied.last() {
        Some(n) => {
            outln(n);
            Ok(EXIT_OK)
        }
        None => bail!("no patches applied"),
    }
}

fn next(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let stack = stack_of(ctx, m)?;
    match stack.unapplied.first() {
        Some(n) => {
            outln(n);
            Ok(EXIT_OK)
        }
        None => bail!("no unapplied patches"),
    }
}

fn prev(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let stack = stack_of(ctx, m)?;
    if stack.applied.len() < 2 {
        bail!("not enough patches applied");
    }
    outln(&stack.applied[stack.applied.len() - 2]);
    Ok(EXIT_OK)
}

// ---------------------------------------------------------------- id / name

fn id(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let rev = m.get_one::<String>("revision").cloned().unwrap_or_else(|| "HEAD".to_string());
    let oid = resolve_revision(ctx, m, &rev)?;
    outln(&oid.to_string());
    Ok(EXIT_OK)
}

fn name(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let rev = m.get_one::<String>("revision").cloned().unwrap_or_else(|| "HEAD".to_string());
    let (oid, name) = resolve_revision_name(ctx, m, &rev)?;
    let _ = oid;
    let s = if m.get_flag("showbranch") {
        format!("{}:{}", branch_of(ctx, m)?, name)
    } else {
        name
    };
    outln(&s);
    Ok(EXIT_OK)
}

/// Resolve a StGit revision to a commit oid.
pub fn resolve_revision(ctx: &Ctx, m: &ArgMatches, rev: &str) -> Result<Oid> {
    let (oid, _) = resolve_revision_name(ctx, m, rev)?;
    Ok(oid)
}

/// Resolve a StGit revision, returning the oid and the patch name (if any).
pub fn resolve_revision_name(ctx: &Ctx, m: &ArgMatches, rev: &str) -> Result<(Oid, String)> {
    let spec = parse_revspec(rev)
        .ok_or_else(|| anyhow!("invalid StGit revision `{rev}`: {rev}\n{}", caret_line(rev, 0)))?;
    if let Some(pos) = spec.err_pos {
        return Err(anyhow!(
            "invalid StGit revision `{rev}`: {rev}\n{}",
            caret_line(rev, pos)
        ));
    }
    let branch = match &spec.branch {
        Some(b) => b.clone(),
        None => branch_of(ctx, m)?,
    };
    // resolve the committish
    let stack = Stack::load(ctx, &branch)?;
    let base_oid = match spec.committish {
        Committish::Base => {
            match stack.applied.first() {
                Some(first) => {
                    let oid = stack.patches.get(first).copied().unwrap_or_default();
                    let obj = ctx.repo.find_object(oid, Some(ObjectType::Commit))?;
                    let c = obj.as_commit().ok_or_else(|| anyhow!("not a commit"))?;
                    c.parent_ids().next().unwrap_or_default()
                }
                None => stack.head,
            }
        }
        Committish::Name(name) => match stack.patches.get(&name) {
            Some(oid) => *oid,
            None => {
                let mut names: Vec<&String> = stack.all_names().iter().map(|s| &s.to_string()).collect();
                let _ = &mut names;
                let sugg = crate::cmds::suggestions(&name, &stack.all_names().iter().map(|s| s.to_string()).collect::<Vec<_>>());
                if sugg.is_empty() {
                    bail!("patch `{name}` does not exist");
                } else {
                    let quoted: Vec<String> = sugg.iter().map(|s| format!("`{s}`")).collect();
                    bail!("patch `{name}` does not exist, but is similar to {}", crate::cmds::join_or(&quoted));
                }
            }
        },
    };
    // apply git revspec suffixes
    let mut spec_str = spec.oid_str;
    let resolved = match crate::cmds::substitute(&mut spec_str, &spec.committish, base_oid) {
        Ok(s) => s,
        Err(e) => bail!("invalid StGit revision `{}`: {e}", rev),
    };
    let obj = ctx
        .repo
        .revparse_single(&resolved)
        .with_context(|| format!("invalid StGit revision `{resolved}`"))?;
    let name = match &spec.committish {
        Committish::Name(n) => n.clone(),
        Committish::Base => format!("{{base}}"),
    };
    Ok((obj.id(), name))
}

pub fn caret_line(_rev: &str, pos: usize) -> String {
    format!("{}^", " ".repeat(pos))
}

#[derive(Debug, Clone)]
pub enum Committish {
    Base,
    Name(String),
}

#[derive(Debug, Clone)]
pub struct RevSpec {
    pub branch: Option<String>,
    pub committish: Committish,
    pub suffix: String,
    pub oid_str: String,
    pub err_pos: Option<usize>,
}

/// Parse a StGit revision spec: `[<branch>:]{base|<name>}[<suffix>]`.
pub fn parse_revspec(s: &str) -> Option<RevSpec> {
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    // Compute the longest valid prefix and the full parse.
    // Returns the parsed spec if the whole string is consumed.
    fn is_refname_char(c: char) -> bool {
        matches!(c,
            'a'..='z' | 'A'..='Z' | '0'..='9' | '_' | '-' | '.' | '/' | '@' | '!' | '"' | '#' |
            '$' | '%' | '&' | '\'' | '(' | ')' | '+' | ',' | ';' | '<' | '=' | '>' | ']' | '{' |
            '}' | '|' | '`' | '\\' | '"' | '~' | '^')
    }
    let _ = is_refname_char;
    // name chars: everything except ':', '*', '?', '[', '\\', ' ', '\t', '~', '^'
    let name_ok = |c: char| {
        !matches!(c, ':' | '*' | '?' | '[' | '\\' | ' ' | '\t' | '~' | '^')
    };
    // Parse a committish starting at position i, returning the end position and
    // the committish.
    fn parse_committish(chars: &[char], i: usize, name_ok: &dyn Fn(char) -> bool) -> Option<(usize, Committish)> {
        if i + 1 < chars.len() && chars[i] == '{' {
            // find closing brace
            let mut j = i + 1;
            let mut depth = 1;
            while j < chars.len() {
                if chars[j] == '{' {
                    depth += 1;
                }
                if chars[j] == '}' {
                    depth -= 1;
                    if depth == 0 {
                        break;
                    }
                }
                j += 1;
            }
            if j >= chars.len() {
                return None;
            }
            let inner: String = chars[i + 1..j].iter().collect();
            return Some((j + 1, Committish::Name(inner)));
        }
        // name
        let mut j = i;
        while j < chars.len() && name_ok(chars[j]) {
            j += 1;
        }
        if j == i {
            return None;
        }
        let mut name: String = chars[i..j].iter().collect();
        // trailing '.' or '/' is not allowed
        while name.ends_with('.') || name.ends_with('/') {
            if name.len() == 1 {
                return None;
            }
            // backtrack
            let mut k = j - 1;
            while k > i && !name_ok(chars[k]) {
                k -= 1;
            }
            if k == i {
                return None;
            }
            j = k;
            name = chars[i..j].iter().collect();
        }
        Some((j, Committish::Name(name)))
    }
    let name_ok_ref: &dyn Fn(char) -> bool = &name_ok;
    // parse suffixes
    fn parse_suffix(chars: &[char], mut i: usize) -> usize {
        while i < chars.len() && (chars[i] == '^' || chars[i] == '~') {
            let c = chars[i];
            i += 1;
            while i < chars.len() && chars[i].is_ascii_digit() {
                i += 1;
            }
            let _ = c;
        }
        i
    }
    // attempt: [branch ':'] committish suffixes
    let mut best_prefix = 0usize;
    // path 1: with branch
    if let Some(ci) = chars.iter().position(|c| *c == ':') {
        // branch name
        let mut bj = 0;
        while bj < ci && name_ok(chars[bj]) {
            bj += 1;
        }
        if bj == ci && ci + 1 <= n {
            // branch ok, parse committish after ':'
            if let Some((end, comm)) = parse_committish(&chars, ci + 1, name_ok_ref) {
                if end > ci + 1 {
                    let send = parse_suffix(&chars, end);
                    if send == n {
                        return Some(RevSpec {
                            branch: Some(chars[..ci].iter().collect()),
                            committish: comm.clone(),
                            suffix: chars[end..].iter().collect(),
                            oid_str: chars[..ci].iter().collect(),
                            err_pos: None,
                        });
                    }
                    best_prefix = best_prefix.max(send);
                }
            } else {
                best_prefix = best_prefix.max(ci + 1);
            }
        } else if bj < ci {
            // partial branch name
            let mut e = parse_suffix(&chars, bj);
            best_prefix = best_prefix.max(e);
            let _ = &mut e;
        }
    }
    // path 2: no branch
    if let Some((end, comm)) = parse_committish(&chars, 0, name_ok_ref) {
        let send = parse_suffix(&chars, end);
        if send == n {
            return Some(RevSpec {
                branch: None,
                committish: comm.clone(),
                suffix: chars[end..].iter().collect(),
                oid_str: String::new(),
                err_pos: None,
            });
        }
        best_prefix = best_prefix.max(send);
    }
    let _ = &mut best_prefix;
    Some(RevSpec {
        branch: None,
        committish: Committish::Name(String::new()),
        suffix: String::new(),
        oid_str: String::new(),
        err_pos: Some(best_prefix),
    })
}

// ---------------------------------------------------------------- log

fn log(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let stack = stack_of(ctx, m)?;
    if m.get_flag("clear") {
        crate::cmds::log_clear(ctx, &stack)?;
        return Ok(EXIT_OK);
    }
    let mut args: Vec<String> = vec!["log".into(), "--color=never".into()];
    if m.get_flag("diff") {
        args.push("-p".into());
    } else if m.get_flag("full") {
        args.push("--pretty=full".into());
    } else {
        args.push("--pretty=tformat:%C(auto)%h   %C(auto,blue)%aD   %C(auto)%s".into());
    }
    if let Some(n) = m.get_one::<String>("number") {
        args.push(format!("-{n}"));
    }
    let mut oids = Vec::new();
    let mut cur = Some(stack.state);
    let mut filter: Option<BTreeSet<String>> = None;
    let names: Vec<String> = m.get_many::<String>("patch").map(|v| v.cloned().collect()).unwrap_or_default();
    if !names.is_empty() {
        let mut set = BTreeSet::new();
        for n in names {
            set.insert(n);
        }
        filter = Some(set);
    }
    while let Some(o) = cur {
        oids.push(o);
        // find the parent stack state
        let obj = ctx.repo.find_object(o, Some(ObjectType::Commit))?;
        let c = obj.as_commit().ok_or_else(|| anyhow!("not a commit"))?;
        cur = match c.parent_ids().next() {
            Some(p) => Some(p),
            None => None,
        };
    }
    // reverse order (oldest first)
    oids.reverse();
    if let Some(n) = m.get_one::<String>("number") {
        let n: usize = n.parse().unwrap_or(0);
        if n > 0 {
            let start = oids.len().saturating_sub(n);
            oids = oids[start..].to_vec();
        }
    }
    let _ = filter;
    for o in oids {
        let mut a = args.clone();
        a.push(o.to_string());
        let _ = crate::cmds::git_run_stdout(ctx, &a)?;
    }
    Ok(EXIT_OK)
}

// ---------------------------------------------------------------- show

fn show(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let stack = stack_of(ctx, m)?;
    let color = if ctx.color.enabled { "always" } else { "never" };
    let mut revs: Vec<String> = Vec::new();
    if m.get_flag("applied") {
        for n in &stack.applied {
            if let Some(o) = stack.patches.get(n) {
                revs.push(o.to_string());
            }
        }
    }
    if m.get_flag("unapplied") {
        for n in &stack.unapplied {
            if let Some(o) = stack.patches.get(n) {
                revs.push(o.to_string());
            }
        }
    }
    if m.get_flag("hidden") {
        for n in &stack.hidden {
            if let Some(o) = stack.patches.get(n) {
                revs.push(o.to_string());
            }
        }
    }
    if let Some(v) = m.get_many::<String>("patch") {
        for p in v {
            let o = resolve_revision(ctx, m, p)?;
            revs.push(o.to_string());
        }
    }
    let names: Vec<String> = m
        .get_many::<String>("patch-or-rev")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let paths: Vec<String> = m.get_many::<String>("path").map(|v| v.cloned().collect()).unwrap_or_default();
    for p in &names {
        let o = resolve_revision(ctx, m, p)?;
        revs.push(o.to_string());
    }
    if revs.is_empty() {
        revs.push(stack.head.to_string());
    }
    for r in &revs {
        let mut args: Vec<String> = vec!["show".into()];
        if m.get_flag("stat") {
            args.push("--stat".into());
            args.push("--summary".into());
        } else {
            args.push("--patch".into());
        }
        args.push(format!("--color={color}"));
        args.push(r.clone());
        args.push("--".into());
        for p in &paths {
            args.push(p.clone());
        }
        crate::cmds::git_run_stdout(ctx, &args)?;
    }
    Ok(EXIT_OK)
}

// ---------------------------------------------------------------- diff

fn diff(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let color = if ctx.color.enabled { "always" } else { "never" };
    let mut args: Vec<String> = vec!["diff".into()];
    if m.get_flag("stat") {
        args.push("--stat".into());
        args.push("--summary".into());
    }
    args.push(format!("--color={color}"));
    if let Some(range) = m.get_one::<String>("range") {
        let (a, b) = crate::cmds::parse_range(range)?;
        let oa = resolve_revision(ctx, m, &a)?;
        let ob = resolve_revision(ctx, m, &b)?;
        args.push(format!("{oa}..{ob}"));
    } else {
        args.push("HEAD".into());
    }
    args.push("--".into());
    let paths: Vec<String> = m.get_many::<String>("path").map(|v| v.cloned().collect()).unwrap_or_default();
    for p in &paths {
        args.push(p.clone());
    }
    crate::cmds::git_run_stdout(ctx, &args)?;
    Ok(EXIT_OK)
}

// ---------------------------------------------------------------- files

fn files(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let stack = stack_of(ctx, m)?;
    let rev = m.get_one::<String>("revision").cloned();
    let name = match &rev {
        Some(r) => Some(crate::cmds::patch_name_for_rev(ctx, m, &stack, r)?),
        None => stack.applied.last().cloned(),
    };
    let name = match name {
        Some(n) => n,
        None => bail!("no patches applied"),
    };
    let oid = *stack.patches.get(&name).ok_or_else(|| anyhow!("patch `{name}` does not exist"))?;
    let meta = stack.meta.get(&name).cloned().unwrap_or_default();
    let paths = crate::cmds::diff_tree_paths(ctx, meta.bottom, meta.top)?;
    if m.get_flag("stat") {
        let d = crate::cmds::diff_tree(ctx, meta.bottom, meta.top)?;
        let stat = crate::cmds::diffstat(ctx, &d)?;
        out(&stat);
        return Ok(EXIT_OK);
    }
    let bare = m.get_flag("bare");
    for (p, s) in paths {
        if bare {
            outln(&p);
        } else {
            outln(&format!("{s} {p}"));
        }
    }
    let _ = oid;
    Ok(EXIT_OK)
}

// ---------------------------------------------------------------- patches

fn patches(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let stack = stack_of(ctx, m)?;
    let mut paths: Vec<String> = m
        .get_many::<String>("path")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    if paths.is_empty() {
        // use the files modified in the work tree
        paths = crate::cmds::worktree_modified(ctx)?;
    }
    for p in &paths {
        for name in &stack.applied {
            let meta = stack.meta.get(name).cloned().unwrap_or_default();
            let list = crate::cmds::diff_tree_paths(ctx, meta.bottom, meta.top)?;
            if list.iter().any(|(f, _)| f == p) {
                outln(name);
                if m.get_flag("diff") {
                    let d = crate::cmds::diff_tree(ctx, meta.bottom, meta.top)?;
                    let d2 = crate::cmds::filter_diff(&d, p);
                    out(&d2);
                }
            }
        }
    }
    Ok(EXIT_OK)
}

