fn jaro_winkler(a: &str, b: &str) -> f64 {
    let ac: Vec<char> = a.chars().collect();
    let bc: Vec<char> = b.chars().collect();
    if ac.is_empty() || bc.is_empty() {
        return 0.0;
    }
    let ad = ac.len() as isize;
    let bd = bc.len() as isize;
    let window = (ad.max(bd) / 2).saturating_sub(1).max(0);
    let mut amatch = vec![false; ad as usize];
    let mut bmatch = vec![false; bd as usize];
    let mut matches = 0i64;
    for i in 0..ad {
        let start = (i - window).max(0);
        let end = (i + window + 1).min(bd);
        for j in start..end {
            if !bmatch[j as usize] && ac[i as usize] == bc[j as usize] {
                amatch[i as usize] = true;
                bmatch[j as usize] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut t = 0i64;
    let mut k = 0i64;
    for i in 0..ad {
        if amatch[i as usize] {
            while !bmatch[k as usize] {
                k += 1;
            }
            if ac[i as usize] != bc[k as usize] {
                t += 1;
            }
            k += 1;
        }
    }
    let m = matches as f64;
    let jaro = (m / ad as f64 + m / bd as f64 + (m - t as f64 / 2.0) / m) / 3.0;
    let mut jw = jaro;
    if jaro > 0.7 {
        let mut l = 0;
        for i in 0..ac.len().min(bc.len()).min(4) {
            if ac[i] == bc[i] {
                l += 1;
            } else {
                break;
            }
        }
        jw += 0.1 * l as f64 * (1.0 - jaro);
    }
    jw
}

