use anyhow::{anyhow, bail, Result};
use git2::{Oid, ObjectType};
use std::collections::BTreeMap;

use crate::ctx::Ctx;

/// Run a git subprocess and forward its stdout to our stdout.
pub fn git_run_stdout(ctx: &Ctx, args: &[String]) -> Result<()> {
    use std::process::Command;
    let mut cmd = Command::new("git");
    cmd.args(args);
    cmd.env("GIT_DIR", ctx.gitdir_arg());
    cmd.env("GIT_WORK_TREE", ctx.workdir_arg());
    let out = cmd.output().map_err(|e| anyhow!("`git`: {e}"))?;
    std::io::stdout().write_all(&out.stdout).map_err(|e| anyhow!("`git {args:?}`: {e}"))?;
    std::io::stderr().write_all(&out.stderr).ok();
    if !out.status.success() {
        bail!("`git {}`", args.join(" "));
    }
    Ok(())
}

use std::io::Write;

/// Run git and return its stdout.
pub fn git_capture(ctx: &Ctx, args: &[String]) -> Result<String> {
    use std::process::Command;
    let mut cmd = Command::new("git");
    cmd.args(args);
    cmd.env("GIT_DIR", ctx.gitdir_arg());
    cmd.env("GIT_WORK_TREE", ctx.workdir_arg());
    let out = cmd.output().map_err(|e| anyhow!("`git`: {e}"))?;
    if !out.status.success() {
        bail!(
            "`git{}`: {}",
            crate::ctx::fmt_args(args),
            String::from_utf_lossy(&out.stderr).trim_end()
        );
    }
    Ok(String::from_utf_lossy(&out.stdout).into_owned())
}

pub fn write_blob(ctx: &Ctx, data: &[u8]) -> Result<Oid> {
    let odb = ctx.repo.odb()?;
    odb.write(ObjectType::Blob, data)
}

pub fn build_tree(ctx: &Ctx, entries: &BTreeMap<String, (Oid, u32)>) -> Result<Oid> {
    let mut tb = ctx.repo.treebuilder(None)?;
    for (path, (oid, mode)) in entries {
        tb.insert(path.as_str(), *oid, *mode)?;
    }
    tb.write()
}

pub fn tree_blob(ctx: &Ctx, tree: &git2::Tree, path: &str) -> Option<Vec<u8>> {
    let entry = tree.get_path(std::path::Path::new(path)).ok()?;
    let bid = entry.to_object(ctx.repo.raw()).ok()?;
    let obj = ctx.repo.find_object(bid, None).ok()?;
    let b = obj.as_blob()?;
    Some(b.data().to_vec())
}

pub fn commit_of(ctx: &Ctx, oid: Oid) -> Result<git2::Commit<'_>> {
    let obj = ctx.repo.find_object(oid, Some(ObjectType::Commit))?;
    obj.as_commit()
        .cloned()
        .ok_or_else(|| anyhow!("expected commit object"))
}

pub fn tree_of(ctx: &Ctx, oid: Oid) -> Result<git2::Tree<'_>> {
    let obj = ctx.repo.find_object(oid, Some(ObjectType::Tree))?;
    obj.as_tree()
        .cloned()
        .ok_or_else(|| anyhow!("expected tree object"))
}

pub fn create_commit(
    ctx: &Ctx,
    tree_oid: Oid,
    parents: &[Oid],
    message: &str,
    time_override: Option<i64>,
) -> Result<Oid> {
    let tree = tree_of(ctx, tree_oid)?;
    let sig_author = signature(ctx, time_override)?;
    let sig_committer = signature(ctx, time_override)?;
    let mut parent_objs = Vec::new();
    for p in parents {
        parent_objs.push(commit_of(ctx, *p)?);
    }
    let refs: Vec<&git2::Commit> = parent_objs.iter().collect();
    let oid = ctx
        .repo
        .commit(None, &sig_author, &sig_committer, message, &tree, &refs)?;
    Ok(oid)
}

pub fn signature(ctx: &Ctx, time: Option<i64>) -> Result<git2::build::Signature<'static>> {
    match time {
        Some(t) => {
            let name = crate::stack::committer_name(ctx)?;
            let email = crate::stack::committer_email(ctx)?;
            Ok(git2::build::Signature::new(&name, &email, &git2::Time::new(t, 0))?)
        }
        None => ctx.repo.committer_from_env(),
    }
}

/// (index_clean, worktree_clean)
pub fn cleanliness(ctx: &Ctx) -> Result<(bool, bool)> {
    let mut opts = git2::StatusOptions::new();
    opts.include_untracked(false)
        .recurse_untracked_dirs(false)
        .exclude_submodules(true)
        .include_ignored(false)
        .no(true)
        .update_index(false);
    let statuses = ctx.repo.statuses(Some(&mut opts))?;
    let mut index_dirty = false;
    let mut worktree_dirty = false;
    for e in statuses.iter() {
        if let Some(d) = e.head_to_index() {
            if !matches!(d.status(), git2::Delta::Unmodified) {
                index_dirty = true;
            }
        }
        if let Some(d) = e.index_to_worktree() {
            if !matches!(d.status(), git2::Delta::Unmodified) {
                worktree_dirty = true;
            }
        }
    }
    Ok((!index_dirty, !worktree_dirty))
}

pub fn check_worktree(ctx: &Ctx) -> Result<()> {
    let (_, w) = cleanliness(ctx)?;
    if !w {
        bail!("worktree not clean; use `refresh` or `reset --hard`");
    }
    Ok(())
}

pub fn check_index(ctx: &Ctx) -> Result<()> {
    let (i, w) = cleanliness(ctx)?;
    if !i {
        bail!("index not clean; use `refresh` or `reset --hard`");
    }
    if !w {
        bail!("worktree not clean; use `refresh` or `reset --hard`");
    }
    Ok(())
}

/// Update the index and work tree to match the given tree.
pub fn checkout_tree(ctx: &Ctx, tree_oid: Oid) -> Result<()> {
    let tree = tree_of(ctx, tree_oid)?;
    let mut opts = git2::build::CheckoutBuilder::new();
    opts.force()
        .update_index(true)
        .refresh(true)
        .recreate_missing(true)
        .overwrite_ignored(true)
        .remove_untracked(true);
    ctx.repo.checkout_tree(&tree, Some(&mut opts))?;
    Ok(())
}

pub fn index_tree(ctx: &Ctx) -> Result<Oid> {
    let mut index = ctx.repo.index()?;
    index.write_tree_to(&ctx.repo)
}

/// Recursive list of paths in a tree, sorted by path.
pub fn tree_paths(ctx: &Ctx, tree_oid: Oid) -> Result<Vec<String>> {
    let tree = tree_of(ctx, tree_oid)?;
    let mut out = Vec::new();
    collect(ctx, &tree, String::new(), &mut out)?;
    Ok(out)
}

fn collect(ctx: &Ctx, tree: &git2::Tree, prefix: String, out: &mut Vec<String>) -> Result<()> {
    let mut names: Vec<(String, git2::ObjectType, Oid)> = Vec::new();
    for i in 0..tree.len() {
        let e = tree.get(i).ok_or_else(|| anyhow!("bad tree entry"))?;
        names.push((e.name().to_string(), e.kind(), e.id()));
    }
    for (name, kind, oid) in names {
        let full = if prefix.is_empty() { name.clone() } else { format!("{prefix}/{name}") };
        if kind == git2::ObjectType::Tree {
            let sub = tree_of(ctx, oid)?;
            collect(ctx, &sub, full, out)?;
        } else {
            out.push(full);
        }
    }
    Ok(())
}

