pub fn diff_tree(ctx: &Ctx, a: Oid, b: Oid) -> Result<String> {
    let args = vec![
        "diff-tree".to_string(),
        "-p".to_string(),
        "--color=never".to_string(),
        "--binary".to_string(),
        a.to_string(),
        b.to_string(),
    ];
    let out = git_capture(ctx, &args)?;
    Ok(out)
}

/// `git apply --stat --summary` on the given diff text
pub fn diffstat(ctx: &Ctx, diff: &str) -> Result<String> {
    use std::io::Write;
    use std::process::{Command, Stdio};
    let mut child = Command::new("git")
        .args(["apply", "--stat", "--summary"])
        .env("GIT_DIR", ctx.gitdir_arg())
        .env("GIT_WORK_TREE", ctx.workdir_arg())
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| anyhow!("`git apply`: {e}"))?;
    let stdin = child.stdin.take().unwrap();
    let mut th = std::thread::spawn(move || {
        let mut w = stdin;
        let _ = w.write_all(diff.as_bytes());
    });
    let out = child.wait_with_output().map_err(|e| anyhow!("`git apply`: {e}"))?;
    let _ = th.join();
    Ok(String::from_utf_lossy(&out.stdout).into_owned())
}

