pub fn diff_tree_paths(ctx: &Ctx, a: Oid, b: Oid) -> Result<Vec<(String, char)>> {
    let d = diff_tree(ctx, a, b)?;
    let mut out = Vec::new();
    for line in d.lines() {
        if let Some(rest) = line.strip_prefix("diff --git a/") {
            let p = rest.split(' ').next().unwrap_or("");
            let p = p.strip_suffix(" b/").unwrap_or(p);
            out.push((p.to_string(), 'M'));
        }
    }
    Ok(out)
}

/// Which paths are modified in the work tree (relative to the index)?
pub fn worktree_modified(ctx: &Ctx) -> Result<Vec<String>> {
    let mut opts = git2::StatusOptions::new();
    opts.include_untracked(false)
        .recurse_untracked_dirs(false)
        .exclude_submodules(true)
        .include_ignored(false)
        .no(true)
        .update_index(false);
    let statuses = ctx.repo.statuses(Some(&mut opts))?;
    let mut out = Vec::new();
    for e in statuses.iter() {
        if e.head_to_index().is_some() || e.index_to_worktree().is_some() {
            if let Some(p) = e.path() {
                out.push(p.to_string());
            }
        }
    }
    Ok(out)
}

pub fn parse_range(s: &str) -> Result<(String, String)> {
    match s.find("..") {
        Some(p) => {
            let a = &s[..p];
            let b = &s[p + 2..];
            Ok((
                if a.is_empty() { "HEAD".to_string() } else { a.to_string() },
                if b.is_empty() { "HEAD".to_string() } else { b.to_string() },
