/// Simple "did you mean" suggestions, similar to clap's.
pub fn suggestions(input: &str, candidates: &[String]) -> Vec<String> {
    let mut out: Vec<(f64, String)> = Vec::new();
    for c in candidates {
        let score = jaro_winkler(input, c);
        if score > 0.7 {
            out.push((score, c.clone()));
        }
    }
    out.sort_by(|a, b| b.0.partial_cmp(&a.0).unwrap_or(std::cmp::Ordering::Equal));
