cat > src/rev.rs <<'EOF'
//! StGit revision spec parsing.
#[derive(Debug, Clone)]
pub enum Committish {
    Base,
    Name(String),
}

#[derive(Debug, Clone)]
pub struct Parsed {
    pub branch: Option<String>,
    pub committish: Committish,
    pub suffix: String,
    pub ok: bool,
    pub pos: usize,
}

/// The characters that may not appear in a patch name (they are used by the
/// revspec grammar or are invalid in git refnames).
fn bad_name_char(c: char) -> bool {
    matches!(c, ':' | '*' | '?' | '[' | '\\' | ' ' | '\t' | '~' | '^')
}

pub fn parse(s: &str) -> Parsed {
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let mut best = 0usize;

    // parse a committish (either "{...}" or a patch name) starting at i
    fn committish(chars: &[char], i: usize) -> Option<(usize, Committish)> {
        if chars.get(i) == Some(&'{') {
            let mut j = i + 1;
            while j < chars.len() {
                if chars[j] == '}' {
                    break;
                }
                j += 1;
            }
            if j >= chars.len() {
                return None;
            }
            let inner: String = chars[i + 1..j].iter().collect();
            return Some((j + 1, Committish::Name(inner)));
        }
        let mut j = i;
        while j < chars.len() && !bad_name_char(chars[j]) {
            j += 1;
        }
        if j == i {
            return None;
        }
        // a name may not end in '.' or '/'
        let mut end = j;
        while end > i {
            let c = chars[end - 1];
            if c == '.' || c == '/' {
                end -= 1;
            } else {
                break;
            }
        }
        if end == i {
            return None;
        }
        Some((end, Committish::Name(chars[i..end].iter().collect())))
    }

    fn suffix(chars: &[char], mut i: usize) -> usize {
        while i < chars.len() && (chars[i] == '^' || chars[i] == '~') {
            i += 1;
            while i < chars.len() && chars[i].is_ascii_digit() {
                i += 1;
            }
        }
        i
    }

    // try the branch form: <branch> ":" <committish>
    if let Some(ci) = chars.iter().position(|c| *c == ':') {
        let mut bj = 0;
        while bj < ci && !bad_name_char(chars[bj]) {
            bj += 1;
        }
        if bj == ci {
            // valid branch name
            if let Some((end, comm)) = committish(&chars, ci + 1) {
                if end > ci + 1 {
                    let send = suffix(&chars, end);
                    if send == n {
                        return Parsed {
                            branch: Some(chars[..ci].iter().collect()),
                            committish: comm,
                            suffix: chars[end..].iter().collect(),
                            ok: true,
                            pos: n,
                        };
                    }
                    best = best.max(send);
                }
            }
            best = best.max(suffix(&chars, bj));
        } else {
            best = best.max(suffix(&chars, bj));
        }
    }
    // try the plain form
    if let Some((end, comm)) = committish(&chars, 0) {
        let send = suffix(&chars, end);
        if send == n {
            return Parsed {
                branch: None,
                committish: comm,
                suffix: chars[end..].iter().collect(),
                ok: true,
                pos: n,
            };
        }
        best = best.max(send);
    }
    Parsed {
        branch: None,
        committish: Committish::Name(String::new()),
        suffix: String::new(),
        ok: false,
        pos: best,
    }
}

pub fn caret(pos: usize) -> String {
    format!("{}^", " ".repeat(pos))
}

/// Build the git revspec string with the patch name substituted by its oid.
pub fn resolved_spec(p: &Parsed, base: Oid) -> String {
    match (&p.branch, &p.committish) {
        (Some(b), Committish::Name(n)) => format!("{b}:{base}{p.suffix}"),
        (None, Committish::Name(_)) => format!("{base}{p.suffix}"),
        _ => format!("{base}{p.suffix}"),
    }
}

/// Extract the message that libgit2 produces for a revspec error.
pub fn git_error(e: &anyhow::Error) -> String {
    let mut cur: Option<&(dyn std::error::Error + 'static)> = e.root_cause().source();
    let _ = &mut cur;
    format!("{e}")
}
EOF
