pub mod aliases {
    use anyhow::{anyhow, bail, Result};
    use std::path::PathBuf;
    use crate::color::ColorWhen;
    use crate::util::{errln};

    pub struct Alias {
        pub name: &'static str,
        pub cmd: &'static str,
    }

    pub fn all() -> Vec<Alias> {
        vec![
            Alias { name: "add", cmd: "git -C \"$GIT_PREFIX\" add" },
            Alias { name: "mv", cmd: "git -C \"$GIT_PREFIX\" mv" },
            Alias { name: "resolved", cmd: "git -C \"$GIT_PREFIX\" add" },
            Alias { name: "rm", cmd: "git -C \"$GIT_PREFIX\" rm" },
            Alias { name: "status", cmd: "git status -s" },
        ]
    }

    pub fn lookup(name: &str) -> Option<Alias> {
        all().into_iter().find(|a| a.name == name)
    }

    pub fn run_alias(
        alias: Alias,
        m: &clap::ArgMatches,
        cd: Vec<PathBuf>,
        color: ColorWhen,
    ) -> Result<i32> {
        use std::process::Command;
        let _ = (cd, color);
        let args: Vec<String> =
            m.get_many::<String>("args").map(|v| v.cloned().collect()).unwrap_or_default();
        // split the alias command into words
        let words: Vec<&str> = alias.cmd.split_whitespace().collect();
        let mut argv: Vec<String> = Vec::new();
        let mut prefix: Option<String> = None;
        let mut it = words.into_iter();
        // first word must be "git"
        let _git = it.next();
        let mut use_prefix = false;
        for w in it {
            if w == "-C" {
                use_prefix = true;
                continue;
            }
            if w.starts_with('"') {
                continue;
            }
            if w == "$GIT_PREFIX\"" || w == "$GIT_PREFIX" {
                continue;
            }
            argv.push(w.to_string());
        }
        // compute GIT_PREFIX
        let cwd = std::env::current_dir().unwrap_or_default();
        let prefix = if prefix.is_some() { prefix.unwrap() } else { crate::ctx::prefix_of(&cd, &cwd) };
        if use_prefix {
            let mut v = vec!["-C".to_string(), prefix.clone()];
            v.append(&mut argv);
            argv = v;
        }
        if !args.is_empty() {
            if let Some(f) = args.first() {
                if f == "-h" || f == "--help" {
                    errln(&format!("'{}' is aliased to '!{}'", alias.name, alias.cmd));
                }
            }
        }
        let _ = &argv;
        let mut full: Vec<String> = argv.clone();
        full.extend(args.iter().cloned());
        let mut cmd = Command::new("git");
        cmd.args(&full);
        cmd.env("GIT_PREFIX", prefix);
        if let Some(p) = cd.last() {
            let _ = std::env::set_current_dir(p);
        }
        let st = cmd.status().map_err(|e| anyhow!("`git`: {e}"))?;
        if !st.success() {
            std::process::exit(st.code().unwrap_or(1));
        }
        Ok(crate::cmds::EXIT_OK)
    }
}
