use crate::ctx::Ctx;

/// Colorize a series line according to the patch status.
pub fn series_line(ctx: &Ctx, line: &str, prefix: char, _empty: bool) -> String {
    if !ctx.color.enabled {
        return line.to_string();
    }
    let (prefix_part, rest) = match prefix {
        '>' => line.split_at(2),
        _ => {
            if line.len() >= 2 {
                line.split_at(2)
            } else {
                (line, "")
            }
        }
    };
    match prefix {
        '>' => format!("{}{}", ctx.color.color("34", prefix_part), rest),
        '+' | '-' | '!' => format!(
            "{}{}",
            ctx.color.color("32", prefix_part),
            ctx.color.color("0", rest)
        ),
        _ => line.to_string(),
    }
}
