/// Run a git subprocess using absolute GIT_DIR (used by `stg log`).
pub fn git_run_stdout_abs(ctx: &Ctx, args: &[String]) -> Result<()> {
    use std::process::Command;
    let mut cmd = Command::new("git");
    cmd.args(args);
    cmd.env("GIT_DIR", ctx.gitdir.display().to_string());
    cmd.env("GIT_WORK_TREE", ".");
    let out = cmd.output().map_err(|e| anyhow!("`git`: {e}"))?;
    std::io::stdout()
        .write_all(&out.stdout)
        .map_err(|e| anyhow!("`git log`: {e}"))?;
    std::io::stderr().write_all(&out.stderr).ok();
    if !out.status.success() {
        bail!("`git{}`: {}", crate::ctx::fmt_args(args), String::from_utf_lossy(&out.stderr).trim_end());
    }
    Ok(())
}

pub fn filter_diff(d: &str, path: &str) -> String {
    let mut out = Vec::new();
    let mut keep = false;
    let mut depth = 0;
    for line in d.lines() {
        if line.starts_with("diff --git a/") {
            let p = line.strip_prefix("diff --git a/").unwrap_or("");
            let p = p.split(' ').next().unwrap_or("");
            let p = p.strip_suffix(" b/").unwrap_or(p);
            keep = p == path;
            depth = 0;
            continue;
        }
        if keep {
            out.push(line);
        }
    }
    let _ = depth;
    let mut s = format!("diff --git a/{path} b/{path}\n");
    s.push_str(&out.join("\n"));
    if !out.is_empty() {
        s.push('\n');
    }
    s
}
