pub const EXIT_OK: i32 = 0;
pub const EXIT_ERROR: i32 = 2;
pub const EXIT_CONFLICT: i32 = 3;

pub fn dispatch(root: &Command, m: &ArgMatches) -> i32 {
    if let Some(_) = m.get_flag("version") {
        out(&crate::cmds::version_text(false));
        return EXIT_OK;
    }
    let sub = match m.subcommand_name() {
        Some(s) => s.to_string(),
        None => return 1,
    };
    let sc = m.subcommand_matches(&sub).unwrap();
    if let Some(alias) = aliases::lookup(&sub) {
        let cd = cd_paths(m);
        let color = color_of(m);
        match aliases::run_alias(alias, sc, cd, color) {
            Ok(code) => return code,
            Err(e) => {
                errln(&format!("error: {e}"));
                return EXIT_ERROR;
            }
        }
    }
    let cd = cd_paths(m);
    let color = color_of(m);
    let mut ctx = match Ctx::open(if cd.is_empty() { None } else { Some(cd) }, color) {
        Ok(c) => c,
        Err(e) => {
            errln(&format!("error: {e}"));
            return EXIT_ERROR;
        }
    };
    let res = run(root, &sub, sc, &mut ctx);
    match res {
        Ok(code) => code,
        Err(e) => {
            errln(&format!("error: {e}"));
            if e.is_conflict() {
