// ---------------------------------------------------------------- series

pub struct SeriesSel {
    pub all: bool,
    pub applied_only: bool,
    pub unapplied_only: bool,
    pub hidden_only: bool,
    pub short: Option<String>,
    pub showbranch: bool,
    pub no_prefix: bool,
    pub empty: bool,
    pub indices: bool,
    pub offsets: bool,
    pub oid: bool,
    pub oid_len: Option<String>,
    pub descr: bool,
    pub author: bool,
    pub reverse: bool,
    pub count: bool,
    pub names: Vec<String>,
    pub missing: Option<String>,
}

#[derive(Clone, Debug)]
pub struct SeriesEntry {
    pub name: String,
    pub oid: Oid,
    pub prefix: char,
    pub empty: bool,
}

pub fn is_empty_patch(stack: &Stack, name: &str) -> bool {
    match stack.meta.get(name) {
        Some(m) => m.bottom == m.top,
        None => true,
    }
}

pub fn series_select(stack: &Stack, sel: &SeriesSel) -> Vec<SeriesEntry> {
    let mut entries = Vec::new();
    let top = stack.applied.last().cloned();
    for name in &stack.applied {
        let prefix = if Some(name) == top.as_ref() { '>' } else { '+' };
        let oid = *stack.patches.get(name).unwrap_or(&Oid::zero());
        entries.push(SeriesEntry { name: name.clone(), oid, prefix, empty: is_empty_patch(stack, name) });
    }
    for name in &stack.unapplied {
        let oid = *stack.patches.get(name).unwrap_or(&Oid::zero());
        entries.push(SeriesEntry { name: name.clone(), oid, prefix: '-', empty: is_empty_patch(stack, name) });
    }
    for name in &stack.hidden {
        let oid = *stack.patches.get(name).unwrap_or(&Oid::zero());
        entries.push(SeriesEntry { name: name.clone(), oid, prefix: '!', empty: is_empty_patch(stack, name) });
    }
    let mut list = entries;
    if sel.applied_only {
        list.retain(|e| e.prefix == '+' || e.prefix == '>');
    } else if sel.unapplied_only {
        list.retain(|e| e.prefix == '-');
    } else if sel.hidden_only {
        list.retain(|e| e.prefix == '!');
    } else if !sel.all {
        list.retain(|e| e.prefix != '!');
    }
    if !sel.names.is_empty() {
        let ranges: Vec<(Option<String>, Option<String>)> = sel
            .names
            .iter()
            .map(|n| {
                if let Some(p) = n.find("..") {
                    let a = &n[..p];
                    let b = &n[p + 2..];
                    (
                        if a.is_empty() { None } else { Some(a.to_string()) },
                        if b.is_empty() { None } else { Some(b.to_string()) },
                    )
                } else {
                    (Some(n.clone()), Some(n.clone()))
                }
            })
            .collect();
        let orig: Vec<String> = list.iter().map(|e| e.name.clone()).collect();
        list.retain(|e| {
            let s = orig.iter().position(|x| x == &e.name).unwrap_or(0);
            ranges.iter().any(|(a, b)| {
                let mut ok = true;
                if let Some(a) = a {
                    if let Some(ai) = orig.iter().position(|x| x == a) {
                        ok &= s >= ai;
                    } else {
                        ok &= e.name == *a;
                    }
                }
                if let Some(b) = b {
                    if let Some(bi) = orig.iter().position(|x| x == b) {
                        ok &= s <= bi;
                    } else {
                        ok &= e.name == *b;
                    }
                }
                ok
            })
        });
    }
    if let Some(short) = &sel.short {
        let n: usize = short.parse().unwrap_or(5);
        let applied: Vec<SeriesEntry> =
            list.iter().filter(|e| e.prefix == '+' || e.prefix == '>').cloned().collect();
        let rest: Vec<SeriesEntry> =
            list.iter().filter(|e| e.prefix != '+' && e.prefix != '>').cloned().collect();
        let keep = applied.len().saturating_sub(n + 1);
        list = applied[keep..].to_vec();
        list.extend(rest);
    }
    list
}

pub fn series_render(ctx: &Ctx, stack: &Stack, sel: &SeriesSel) -> Result<String> {
    let list = series_select(stack, sel);
    let n_applied = stack.applied.len();
    let mut lines = Vec::new();
    for (i, e) in list.iter().enumerate() {
        let idx = i;
        let offset = if e.prefix == '+' || e.prefix == '>' {
            idx as i64 - (n_applied as i64 - 1)
        } else {
            idx as i64 + 1
        };
        let mut line = String::new();
        if sel.empty {
            line.push(if e.empty { '*' } else { ' ' });
        }
        if !sel.no_prefix {
            line.push(e.prefix);
            line.push(' ');
        }
        if sel.indices {
            line.push_str(&format!("{idx} "));
        }
        if sel.offsets {
            line.push_str(&format!("{offset:+} "));
        }
        if sel.oid {
            let s = e.oid.to_string();
            let l = match &sel.oid_len {
                Some(v) => {
                    if let Ok(n) = v.parse::<usize>() {
                        if n < 4 {
                            s.len()
                        } else {
                            n
                        }
                    } else {
                        s.len()
                    }
                }
                None => s.len(),
            };
            line.push_str(&format!("{} ", &s[..l.min(s.len())]));
        }
        if sel.showbranch {
            line.push_str(&format!("{}:{}", stack.branch, e.name));
        } else {
            line.push_str(&e.name);
        }
        if sel.author {
            let a = stack.meta.get(&e.name).map(|m| m.author.clone()).unwrap_or_default();
            line.push_str(&format!(" # {a}"));
        }
        if sel.descr {
            let d = stack
                .meta
                .get(&e.name)
                .and_then(|m| m.message.lines().next())
                .unwrap_or("")
                .to_string();
            line.push_str(&format!(" # {d}"));
        }
        lines.push(crate::color::series_line(ctx, &line, e.prefix, e.empty));
    }
    let mut s = lines.join("\n");
    if !lines.is_empty() {
        s.push('\n');
    }
    Ok(s)
}

fn series(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let stack = stack_of(ctx, m)?;
    let sel = SeriesSel {
        all: m.get_flag("all"),
        applied_only: m.get_flag("applied"),
        unapplied_only: m.get_flag("unapplied"),
        hidden_only: m.get_flag("hidden"),
        short: m.get_one::<String>("short").cloned(),
        showbranch: m.get_flag("showbranch"),
        no_prefix: m.get_flag("no-prefix"),
        empty: m.get_flag("empty"),
        indices: m.get_flag("indices"),
        offsets: m.get_flag("offsets"),
        oid: m.contains_id("commit-id"),
        oid_len: m.get_one::<String>("commit-id").cloned(),
        descr: m.get_flag("description"),
        author: m.get_flag("author"),
        reverse: m.get_flag("reverse"),
        count: m.get_flag("count"),
        names: m.get_many::<String>("patch").map(|v| v.cloned().collect()).unwrap_or_default(),
        missing: m.get_one::<String>("missing").cloned(),
    };
    let mut sel = sel;
    if let Some(b) = &sel.missing {
        let other = Stack::load(ctx, b)?;
        let names: Vec<String> = other.all_names().iter().map(|s| s.to_string()).collect();
        let _ = names;
    }
    let mut s = series_render(ctx, &stack, &sel)?;
    if sel.count {
        let n = crate::series::count_selected(&stack, &sel);
        outln(&format!("{n}"));
        return Ok(EXIT_OK);
    }
    if sel.reverse {
        let lines: Vec<&str> = s.lines().collect();
        lines.reverse();
        s = lines.join("\n");
        if !lines.is_empty() {
            s.push('\n');
        }
    }
    out(&s);
    Ok(EXIT_OK)
}

// ---------------------------------------------------------------- init

fn init(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let branch = branch_of(ctx, m)?;
    let head = match ctx.repo.refname_to_id(&format!("refs/heads/{branch}")) {
        Ok(h) => h,
        Err(_) => bail!("branch `{branch}` not found"),
    };
    let refname = crate::stack::stack_ref_name(&branch);
    if ctx.repo.find_reference(&refname).is_ok() {
        bail!("branch `{branch}` is already initialized");
    }
    let mut stack = Stack::empty(&branch, head);
    stack.save(ctx, "initialize")?;
    Ok(EXIT_OK)
}

// ---------------------------------------------------------------- top/next/prev

fn top(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let stack = stack_of(ctx, m)?;
    match stack.applied.last() {
        Some(n) => {
            outln(n);
            Ok(EXIT_OK)
        }
        None => bail!("no patches applied"),
    }
}

fn next(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let stack = stack_of(ctx, m)?;
    match stack.unapplied.first() {
        Some(n) => {
            outln(n);
            Ok(EXIT_OK)
        }
        None => bail!("no unapplied patches"),
    }
}

fn prev(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let stack = stack_of(ctx, m)?;
    if stack.applied.len() < 2 {
        bail!("not enough patches applied");
    }
    outln(&stack.applied[stack.applied.len() - 2]);
    Ok(EXIT_OK)
}

// ---------------------------------------------------------------- id / name

fn id(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let rev = m
        .get_one::<String>("revision")
        .cloned()
        .unwrap_or_else(|| "HEAD".to_string());
    let oid = resolve_revision(ctx, m, &rev)?;
    outln(&oid.to_string());
    Ok(EXIT_OK)
}

fn name(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let rev = m
        .get_one::<String>("revision")
        .cloned()
        .unwrap_or_else(|| "HEAD".to_string());
    let (_, n) = resolve_revision_name(ctx, m, &rev)?;
    let s = if m.get_flag("showbranch") {
        format!("{}:{}", branch_of(ctx, m)?, n)
    } else {
        n
    };
    outln(&s);
    Ok(EXIT_OK)
}

pub fn resolve_revision(ctx: &Ctx, m: &ArgMatches, rev: &str) -> Result<Oid> {
    let (oid, _) = resolve_revision_name(ctx, m, rev)?;
    Ok(oid)
}

pub fn resolve_revision_name(ctx: &Ctx, m: &ArgMatches, rev: &str) -> Result<(Oid, String)> {
    let parsed = crate::rev::parse(rev);
    if !parsed.ok {
        bail!("invalid StGit revision `{rev}`: {rev}\n{}", crate::rev::caret(parsed.pos));
    }
    let branch = match &parsed.branch {
        Some(b) => b.clone(),
        None => branch_of(ctx, m)?,
    };
    let stack = Stack::load(ctx, &branch)?;
    let (base, name) = match &parsed.committish {
        crate::rev::Committish::Base => {
            let base = match stack.applied.first() {
                Some(first) => {
                    let oid = *stack.patches.get(first).unwrap_or(&Oid::zero());
                    let c = crate::git::commit_of(ctx, oid)?;
                    c.parent_ids().next().unwrap_or(stack.head)
                }
                None => stack.head,
            };
            (base, "{base}".to_string())
        }
        crate::rev::Committish::Name(n) => match stack.patches.get(n) {
            Some(o) => (*o, n.clone()),
            None => {
                let cands: Vec<String> = stack.all_names().iter().map(|s| s.to_string()).collect();
                let sugg = crate::git::suggestions(n, &cands);
                if sugg.is_empty() {
                    bail!("patch `{n}` does not exist");
                }
                let quoted: Vec<String> = sugg.iter().map(|s| format!("`{s}`")).collect();
                bail!(
                    "patch `{n}` does not exist, but is similar to {}",
                    crate::git::join_or(&quoted)
                );
            }
        },
    };
    let spec = crate::rev::resolved_spec(&parsed, base);
    let obj = ctx
        .repo
        .revparse_single(&spec)
        .map_err(|e| anyhow!("invalid StGit revision `{spec}`: {e}"))?;
    Ok((obj.id(), name))
}

// ---------------------------------------------------------------- log

fn log(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let stack = stack_of(ctx, m)?;
    if m.get_flag("clear") {
        crate::stackops::log_clear(ctx, &stack)?;
        return Ok(EXIT_OK);
    }
    let mut args: Vec<String> = vec!["log".into()];
    if m.get_flag("diff") {
        args.push("--color=never".into());
        args.push("-p".into());
    } else if m.get_flag("full") {
        args.push("--color=never".into());
        args.push("--pretty=full".into());
    } else {
        args.push("--color=never".into());
        args.push(
            "--pretty=tformat:%C(auto)%h   %C(auto,blue)%aD   %C(auto)%s".into(),
        );
    }
    if let Some(n) = m.get_one::<String>("number") {
        args.push(format!("-{n}"));
    }
    let mut oids = Vec::new();
    let mut cur = Some(stack.state);
    while let Some(o) = cur {
        oids.push(o);
        let c = crate::git::commit_of(ctx, o)?;
        cur = c.parent_ids().next();
    }
    oids.reverse();
    if let Some(n) = m.get_one::<String>("number") {
        let n: usize = n.parse().unwrap_or(0);
        if n > 0 {
            let start = oids.len().saturating_sub(n);
            oids = oids[start..].to_vec();
        }
    }
    let names: Vec<String> =
        m.get_many::<String>("patch").map(|v| v.cloned().collect()).unwrap_or_default();
    let _ = names;
    for o in &oids {
        let mut a = args.clone();
        a.push(o.to_string());
        crate::git::git_run_stdout_abs(ctx, &a)?;
    }
    Ok(EXIT_OK)
}

// ---------------------------------------------------------------- show

fn show(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let stack = stack_of(ctx, m)?;
    let color = if ctx.color.enabled { "always" } else { "never" };
    let mut revs: Vec<String> = Vec::new();
    if m.get_flag("applied") {
        for n in &stack.applied {
            if let Some(o) = stack.patches.get(n) {
                revs.push(o.to_string());
            }
        }
    }
    if m.get_flag("unapplied") {
        for n in &stack.unapplied {
            if let Some(o) = stack.patches.get(n) {
                revs.push(o.to_string());
            }
        }
    }
    if m.get_flag("hidden") {
        for n in &stack.hidden {
            if let Some(o) = stack.patches.get(n) {
                revs.push(o.to_string());
            }
        }
    }
    if let Some(v) = m.get_many::<String>("patch") {
        for p in v {
            revs.push(resolve_revision(ctx, m, p)?.to_string());
        }
    }
    let paths: Vec<String> =
        m.get_many::<String>("path").map(|v| v.cloned().collect()).unwrap_or_default();
    let names: Vec<String> = m
        .get_many::<String>("patch-or-rev")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    for p in &names {
        revs.push(resolve_revision(ctx, m, p)?.to_string());
    }
    if revs.is_empty() {
        revs.push(stack.head.to_string());
    }
    for r in &revs {
        let mut args: Vec<String> = vec!["show".into()];
        if m.get_flag("stat") {
            args.push("--stat".into());
            args.push("--summary".into());
        } else {
            args.push("--patch".into());
        }
        args.push(format!("--color={color}"));
        args.push(r.clone());
        args.push("--".into());
        for p in &paths {
            args.push(p.clone());
        }
        crate::git::git_run_stdout(ctx, &args)?;
    }
    Ok(EXIT_OK)
}

// ---------------------------------------------------------------- diff

fn diff(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let color = if ctx.color.enabled { "always" } else { "never" };
    let mut args: Vec<String> = vec!["diff".into()];
    if m.get_flag("stat") {
        args.push("--stat".into());
        args.push("--summary".into());
    }
    args.push(format!("--color={color}"));
    if let Some(range) = m.get_one::<String>("range") {
        let (a, b) = crate::git::parse_range(range)?;
        let oa = resolve_revision(ctx, m, &a)?;
        let ob = resolve_revision(ctx, m, &b)?;
        args.push(format!("{oa}..{ob}"));
    } else {
        args.push("HEAD".into());
    }
    args.push("--".into());
    let paths: Vec<String> =
        m.get_many::<String>("path").map(|v| v.cloned().collect()).unwrap_or_default();
    for p in &paths {
        args.push(p.clone());
    }
    crate::git::git_run_stdout(ctx, &args)?;
    Ok(EXIT_OK)
}

// ---------------------------------------------------------------- files

fn files(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let stack = stack_of(ctx, m)?;
    let rev = m.get_one::<String>("revision").cloned();
    let name = match &rev {
        Some(r) => Some(crate::stackops::patch_name_for_rev(ctx, m, &stack, r)?),
        None => stack.applied.last().cloned(),
    };
    let name = match name {
        Some(n) => n,
        None => bail!("no patches applied"),
    };
    let meta = match stack.meta.get(&name) {
        Some(m) => m.clone(),
        None => bail!("patch `{name}` does not exist"),
    };
    if m.get_flag("stat") {
        let d = crate::git::diff_tree(ctx, meta.bottom, meta.top)?;
        let stat = crate::git::diffstat(ctx, &d)?;
        out(&stat);
        return Ok(EXIT_OK);
    }
    let bare = m.get_flag("bare");
    let list = crate::git::diff_tree_paths(ctx, meta.bottom, meta.top)?;
    for (p, s) in list {
        if bare {
            outln(&p);
        } else {
            outln(&format!("{s} {p}"));
        }
    }
    Ok(EXIT_OK)
}

// ---------------------------------------------------------------- patches

fn patches(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let stack = stack_of(ctx, m)?;
    let mut paths: Vec<String> =
        m.get_many::<String>("path").map(|v| v.cloned().collect()).unwrap_or_default();
    if paths.is_empty() {
        paths = crate::git::worktree_modified(ctx)?;
    }
    for p in &paths {
        for name in &stack.applied {
            let meta = match stack.meta.get(name) {
                Some(mm) => mm.clone(),
                None => continue,
            };
            let list = crate::git::diff_tree_paths(ctx, meta.bottom, meta.top)?;
            if list.iter().any(|(f, _)| f == p) {
                outln(name);
                if m.get_flag("diff") {
                    let d = crate::git::diff_tree(ctx, meta.bottom, meta.top)?;
                    out(&crate::git::filter_diff(&d, p));
                }
            }
        }
    }
    Ok(EXIT_OK)
}

