{"command": "cd /tmp/tst && cat > src/main.rs <<'EOF'
use clap::{Command, Arg};
fn main() {
    let mut c = Command::new("prog")
        .arg_required_else_help(true)
        .subcommand_required(false)
        .arg(Arg::new("v").long("version").action(clap::ArgAction::SetTrue));
    let cfg = std::env::var("CFG").unwrap_or_default();
    if cfg.contains("d") { c = c.disable_version_flag(true); }
    if cfg.contains("o") { c = c.override_usage("prog [x]"); }
    if cfg.contains("t") { c = c.help_template("{about-with-newline}\n{usage-heading} {usage}\n\n{before-help}{all-args}{after-help}"); }
    if cfg.contains("b") { c = c.before_help("BEFORE\n").before_long_help("BEFORE\n"); }
    if cfg.contains("m") { c = c.max_term_width(88); }
    if cfg.contains("s") { c = c.subcommand(Command::new("sub").hide(true)); }
    match c.clone().try_get_matches() {
        Ok(m) => println!("ok, sub={:?}", m.subcommand_name()),
        Err(e) => { eprintln!("ERR kind={:?}", e.kind()); e.print().unwrap(); std::process::exit(1); }
    }
