//! Operation status report.

#[derive(Clone, Debug, PartialEq)]
pub enum Kind {
    Unapply,
    Apply,
    Hide,
    Unhide,
    Delete,
    Commit,
    Refresh,
    New,
    Head,
}

#[derive(Clone, Debug)]
pub struct Item {
    pub kind: Kind,
    pub names: Vec<String>,
    /// marks that this item set the branch head
    pub head: bool,
    pub suffix: Option<String>,
}

#[derive(Default)]
pub struct Report {
    pub items: Vec<Item>,
}

impl Report {
    pub fn new() -> Report {
        Report { items: Vec::new() }
    }

    pub fn push(&mut self, kind: Kind, names: Vec<String>, head: bool) {
        // merge with the previous item when possible
        let merge = match self.items.last() {
            Some(prev) => {
                prev.kind == kind
                    && ((kind == Kind::Unapply) || (kind == Kind::Commit) || (kind == Kind::Delete))
            }
            None => false,
        };
        if merge {
            let last = self.items.last_mut().unwrap();
            last.names.extend(names);
            if head {
                last.head = true;
            }
        } else {
            self.items.push(Item { kind, names, head, suffix: None });
        }
    }

    pub fn unapply(&mut self, names: Vec<String>) {
        self.push(Kind::Unapply, names, false);
    }
    pub fn apply(&mut self, names: Vec<String>, head: bool) {
        self.push(Kind::Apply, names, head);
    }
    pub fn hide(&mut self, names: Vec<String>) {
        self.push(Kind::Hide, names, false);
    }
    pub fn unhide(&mut self, names: Vec<String>) {
        self.push(Kind::Unhide, names, false);
    }
    pub fn delete(&mut self, names: Vec<String>) {
        self.push(Kind::Delete, names, false);
    }
    pub fn commit(&mut self, names: Vec<String>) {
        self.push(Kind::Commit, names, false);
    }
    pub fn refresh(&mut self, names: Vec<String>) {
        self.push(Kind::Refresh, names, false);
    }
    pub fn newpatch(&mut self, names: Vec<String>) {
        self.push(Kind::New, names, false);
    }
    pub fn head(&mut self, name: &str) {
        if let Some(last) = self.items.last_mut() {
            if last.kind == Kind::Apply && last.names.last().map(|n| n == name).unwrap_or(false) {
                last.head = true;
                return;
            }
            if last.kind == Kind::New && last.names.last().map(|n| n == name).unwrap_or(false) {
                return;
            }
        }
        self.push(Kind::Head, vec![name.to_string()], false);
    }

    /// Append the head item if the head is a patch and it was not already reported.
    pub fn finish(&mut self, head: Option<&str>) {
        if let Some(h) = head {
            let reported = self.items.iter().any(|i| {
                i.head && i.names.last().map(|n| n == h).unwrap_or(false)
            });
            if !reported {
                self.head(h);
            }
        }
    }

    pub fn render(&self) -> String {
        let mut out: Vec<String> = Vec::new();
        for item in &self.items {
            match item.kind {
                Kind::Unapply => {
                    out.push(range_line('-', &item.names));
                }
                Kind::Commit => {
                    out.push(range_line('$', &item.names));
                }
                Kind::Delete => {
                    for n in &item.names {
                        out.push(format!("# {n}"));
                    }
                }
                Kind::Hide => {
                    for n in &item.names {
                        out.push(format!("! {n}"));
                    }
                }
                Kind::Unhide => {
                    for n in &item.names {
                        out.push(format!("- {n}"));
                    }
                }
                Kind::Refresh => {
                    for n in &item.names {
                        out.push(format!("& {n}"));
                    }
                }
                Kind::New => {
                    for n in &item.names {
                        out.push(format!("> {n} (new)"));
                    }
                }
                Kind::Apply | Kind::Head => {
                    let n = item.names.len();
                    for (i, name) in item.names.iter().enumerate() {
                        let is_last = i + 1 == n;
                        let prefix = if is_last && item.head { '>' } else { '+' };
                        let suffix = match &item.suffix {
                            Some(s) if is_last => format!(" {s}"),
                            _ => String::new(),
                        };
                        out.push(format!("{prefix} {name}{suffix}"));
                    }
                }
            }
        }
        if out.is_empty() {
            String::new()
        } else {
            let mut s = out.join("\n");
            s.push('\n');
            s
        }
    }
}

fn range_line(prefix: char, names: &[String]) -> String {
    if names.len() > 1 {
        format!("{prefix} {}..{}", names[0], names[names.len() - 1])
    } else {
        format!("{prefix} {}", names[0])
    }
}
