    if !stack.unapplied.contains(&name.to_string()) {
        stack.unapplied.push(name.to_string());
    }
}

pub fn mark_hidden(stack: &mut Stack, name: &str) {
    stack.applied.retain(|n| n != name);
    stack.unapplied.retain(|n| n != name);
    if !stack.hidden.contains(&name.to_string()) {
        stack.hidden.push(name.to_string());
    }
}

/// Set the branch head to the given commit and update the index and work tree.
pub fn set_head(ctx: &Ctx, stack: &mut Stack, oid: Oid) -> Result<()> {
    let tree = crate::git::commit_of(ctx, oid)?.tree_id()?;
    stack.head = oid;
    crate::git::checkout_tree(ctx, tree)?;
    Ok(())
}

/// Pop (unapply) the topmost applied patch.
pub fn unapply(ctx: &Ctx, stack: &mut Stack, report: &mut Report, name: &str) -> Result<()> {
    let oid = *stack
        .patches
        .get(name)
        .ok_or_else(|| anyhow!("patch `{name}` does not exist"))?;
    let commit = crate::git::commit_of(ctx, oid)?;
    let parents: Vec<Oid> = commit.parent_ids().collect();
    let new_head = if parents.is_empty() {
        Oid::zero()
    } else {
        parents[0]
    };
    if new_head.is_zero() {
        bail!("cannot unapply patch `{name}`");
    }
    set_head(ctx, stack, new_head)?;
    mark_unapplied(stack, name);
    let _ = report;
    Ok(())
}

/// Compute the merged tree for applying `name` on top of the current head.
/// Returns (tree_oid, conflicts).
pub fn merge_patch(
    ctx: &Ctx,
    stack: &Stack,
    name: &str,
    set_tree: bool,
) -> Result<(Oid, Vec<String>)> {
    let meta = stack
        .meta
        .get(name)
        .cloned()
        .ok_or_else(|| anyhow!("patch `{name}` does not exist"))?;
    let our_tree = crate::git::commit_of(ctx, stack.head)?.tree_id()?;
    if set_tree {
        return Ok((meta.top, Vec::new()));
    }
    let base = crate::git::tree_of(ctx, meta.bottom)?;
    let ours = crate::git::tree_of(ctx, our_tree)?;
    let theirs = crate::git::tree_of(ctx, meta.top)?;
    let mut opts = git2::MergeOptions::new();
    let index = ctx.repo.merge_trees(&base, &ours, &theirs, Some(&mut opts))?;
    let conflicts: Vec<String> = index
        .conflicts()?
        .map(|c| {
            c.and_then(|x| {
                x.our
                    .or(x.their)
                    .map(|e| String::from_utf8_lossy(&e.path).into_owned())
            })
            .unwrap_or_default()
        })
        .collect();
    let tree_oid = index.write_tree_to(&ctx.repo)?;
    Ok((tree_oid, conflicts))
}

/// Apply (push) a patch onto the current head.
pub fn apply_patch(
    ctx: &Ctx,
    stack: &mut Stack,
    report: &mut Report,
    name: &str,
    opts: &PushOpts,
) -> Result<bool> {
    let meta = stack
        .meta
        .get(name)
        .cloned()
        .ok_or_else(|| anyhow!("patch `{name}` does not exist"))?;
    let head = stack.head;
    let (tree_oid, conflicts) = merge_patch(ctx, stack, name, opts.set_tree)?;
    if !conflicts.is_empty() {
        if !opts.conflicts_allow {
            bail!("merge conflicts; resolve conflicts manually then refresh or undo the operation with `stg undo --hard`.");
        }
        // resolve the conflicts using `git merge-file`
        write_conflicts(ctx, &conflicts, head)?;
    }
    let msg = meta.message.clone();
    let time = if opts.committer_date_is_author_date {
        Some(commit_time(ctx, stack.head)?)
    } else {
        None
    };
    let oid = crate::git::create_commit(ctx, tree_oid, &[head], &msg, time)?;
    // update the patch metadata
    let bottom = crate::git::commit_of(ctx, head)?.tree_id()?;
    let mut newmeta = meta.clone();
    newmeta.bottom = bottom;
    newmeta.top = tree_oid;
    if opts.committer_date_is_author_date {
        newmeta.date = crate::util::format_git_date(
            crate::git::commit_of(ctx, head)?.time().seconds(),
            crate::git::commit_of(ctx, head)?.time().offset_minutes(),
        );
    }
    stack.meta.insert(name.to_string(), newmeta);
    stack.patches.insert(name.to_string(), oid);
    set_head(ctx, stack, oid)?;
    mark_applied(stack, name);
    report.apply(vec![name.to_string()], true);
    Ok(!conflicts.is_empty())
}

/// Get the committer time of a commit.
pub fn commit_time(ctx: &Ctx, oid: Oid) -> Result<i64> {
    Ok(crate::git::commit_of(ctx, oid)?.time().seconds())
}

/// Write conflict markers for the given paths using `git merge-file`.
pub fn write_conflicts(ctx: &Ctx, paths: &[String], head: Oid) -> Result<()> {
    let mut status = ctx.repo.statuses(None)?;
    for p in paths {
        let path = std::path::PathBuf::from(p);
        // our content: from the index (the merged index has the conflict)
        let our = read_index_content(ctx, &path)?;
        let their = read_tree_content(ctx, crate::git::commit_of(ctx, head)?.tree_id()?, p)?;
        let base = read_base_content(ctx, p)?;
        let merged = merge_file(ctx, "current", &our, &base, &their)?;
        // write to the work tree
        let full = ctx.workdir.join(&path);
        if let Some(parent) = full.parent() {
            std::fs::create_dir_all(parent).ok();
        }
        std::fs::write(&full, &merged).map_err(|e| anyhow!("{e}"))?;
        // stage it
        crate::git::stage_file(ctx, &path, &merged)?;
        errln(&format!("UU {}", p));
        let _ = &mut status;
    }
    Ok(())
}

pub fn read_index_content(ctx: &Ctx, path: &Path) -> Result<Vec<u8>> {
    let mut index = ctx.repo.index()?;
    index.read(false)?;
    match index.get_path(path, 0) {
        Some(e) => {
            let oid = e.id;
            let obj = ctx.repo.find_object(oid, None)?;
            let b = obj.as_blob().ok_or_else(|| anyhow!("not a blob"))?;
            Ok(b.content().to_vec())
        }
        None => Ok(Vec::new()),
    }
}

pub fn read_tree_content(ctx: &Ctx, tree: Oid, path: &str) -> Result<Vec<u8>> {
    let t = crate::git::tree_of(ctx, tree)?;
    match crate::git::tree_blob(ctx, &t, path) {
        Some(d) => Ok(d),
        None => Ok(Vec::new()),
    }
}

pub fn read_base_content(ctx: &Ctx, path: &str) -> Result<Vec<u8>> {
    // the content of the file in the stack base (the parent of the head)
    let head = ctx.repo.head()?;
    let c = crate::git::commit_of(ctx, head.target().unwrap_or(Oid::zero()))?;
    let parents: Vec<Oid> = c.parent_ids().collect();
    if parents.is_empty() {
        return Ok(Vec::new());
    }
    read_tree_content(ctx, crate::git::commit_of(ctx, parents[0])?.tree_id()?, path)
}

/// Run `git merge-file -p current base patched` and return the merged content.
pub fn merge_file(
    ctx: &Ctx,
    label: &str,
    current: &[u8],
    base: &[u8],
    other: &[u8],
) -> Result<Vec<u8>> {
    let _ = label;
    let tmp = std::env::temp_dir().join(format!("stg-merge-{}", std::process::id()));
    let _ = std::fs::create_dir_all(&tmp);
    let cur = tmp.join("current");
    let bas = tmp.join("base");
    let oth = tmp.join("patched");
    std::fs::write(&cur, current).ok();
    std::fs::write(&bas, base).ok();
    std::fs::write(&oth, other).ok();
    let out = std::process::Command::new("git")
        .args(["merge-file", "-p"])
        .arg(&cur)
        .arg(&bas)
        .arg(&oth)
        .env("GIT_DIR", ctx.gitdir_arg())
        .env("GIT_WORK_TREE", ctx.workdir_arg())
        .output()
        .map_err(|e| anyhow!("`git merge-file`: {e}"))?;
    let _ = std::fs::remove_dir_all(&tmp);
    if !out.status.success() && out.status.code() != Some(1) {
        bail!(
            "`git merge-file`: {}",
            String::from_utf8_lossy(&out.stderr).trim_end()
        );
    }
    Ok(out.stdout)
}
