/// Stage a blob in the index (without touching the work tree).
pub fn stage_file(ctx: &Ctx, path: &Path, data: &[u8]) -> Result<()> {
    let mut index = ctx.repo.index()?;
    index.read(false)?;
    let odb = ctx.repo.odb()?;
    let oid = odb.write(ObjectType::Blob, data)?;
    let mut entry = git2::IndexEntry::new();
    entry.id = oid;
    entry.mode = 0o100644;
    entry.path = path.as_os_str().to_string_lossy().into_owned().into_bytes();
    entry.file_size = data.len() as u32;
    index.add(&entry)?;
    index.write()?;
    Ok(())
}

