pub mod stackops_extra {
    use anyhow::{bail, Result};
    use crate::ctx::Ctx;
    use crate::stack::Stack;
    use clap::ArgMatches;

    pub fn patch_name_for_rev(ctx: &Ctx, m: &ArgMatches, stack: &Stack, rev: &str) -> Result<String> {
        let parsed = crate::rev::parse(rev);
        if !parsed.ok {
            bail!("invalid StGit revision `{rev}`: {rev}\n{}", crate::rev::caret(parsed.pos));
        }
        match &parsed.committish {
            crate::rev::Committish::Name(n) => {
                if stack.patches.contains_key(n) {
                    Ok(n.clone())
                } else {
                    let cands: Vec<String> = stack.all_names().iter().map(|s| s.to_string()).collect();
                    let sugg = crate::git::suggestions(n, &cands);
                    if sugg.is_empty() {
                        bail!("patch `{n}` does not exist");
                    }
                    let quoted: Vec<String> = sugg.iter().map(|s| format!("`{s}`")).collect();
                    bail!(
                        "patch `{n}` does not exist, but is similar to {}",
                        crate::git::join_or(&quoted)
                    );
                }
            }
            crate::rev::Committish::Base => bail!("no patches applied"),
        }
    }

    pub fn log_clear(ctx: &Ctx, stack: &Stack) -> Result<()> {
        let mut s = stack.clone();
        s.prev = None;
        s.state_commit = None;
        s.save(ctx, "clear log")?;
        Ok(())
    }
}
