# Replace the pop/push/goto/float/sink/hide/unhide/delete/rename stubs with real implementations.
def repl(fnname, newcode):
    global s
    start = s.index(f"fn {fnname}(")
    end = s.index("fn ", start+10)
    s = s[:start] + newcode + s[end:]

new = '''fn pop(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let mut stack = stack_of(ctx, m)?;
    crate::git::check_index(ctx)?;
    let mut report = crate::report::Report::new();
    let applied = stack.applied.clone();
    if applied.is_empty() {
        bail!("no patches applied");
    }
    let targets: Vec<String> = if m.get_flag("all") {
        applied.clone()
    } else if let Some(n) = m.get_one::<String>("number") {
        let n: i64 = n.parse().unwrap_or(1);
        let cnt = if n < 0 {
            (applied.len() as i64 + n).max(0) as usize
        } else {
            n as usize
        };
        let cnt = cnt.min(applied.len());
        applied[applied.len() - cnt..].to_vec()
    } else {
        m.get_many::<String>("patch")
            .map(|v| v.cloned().collect())
            .unwrap_or_default()
    };
    if targets.is_empty() {
        // pop the topmost patch
        let name = applied.last().unwrap().clone();
        let rep = crate::report::Report::new();
        let mut rep = rep;
        crate::stackops::unapply(ctx, &mut stack, &mut rep, &name)?;
        report.unapply(vec![name]);
    } else {
        // pop the given patches: unapply everything above the highest target
        let mut to_pop: Vec<String> = Vec::new();
        let highest = targets
            .iter()
            .filter_map(|n| applied.iter().position(|x| x == n))
            .min();
        if let Some(h) = highest {
            to_pop = applied[h..].to_vec();
        }
        let keep: Vec<String> = to_pop
            .iter()
            .filter(|n| !targets.contains(n))
            .cloned()
            .collect();
        let popped: Vec<String> = to_pop.iter().cloned().collect();
        for name in popped.iter().rev() {
            crate::stackops::unapply(ctx, &mut stack, &mut report, name)?;
        }
        if !popped.is_empty() {
            report.unapply(popped.clone());
        }
        // push back the patches that should stay applied
        let opts = crate::stackops::PushOpts::default();
        for name in &keep {
            crate::stackops::apply_patch(ctx, &mut stack, &mut report, name, &opts)?;
        }
    }
    let head_name = stack.applied.last().cloned();
    report.finish(head_name.as_deref());
    let msg = if crate::util::is_conflict_str("") { "" } else { "pop" };
    stack.save(ctx, msg)?;
    out(&report.render());
    Ok(EXIT_OK)
}

fn push(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let mut stack = stack_of(ctx, m)?;
    crate::git::check_index(ctx)?;
    let unapplied = stack.unapplied.clone();
    if unapplied.is_empty() && !m.get_flag("noapply") {
        bail!("no unapplied patches");
    }
    let mut targets: Vec<String> = if m.get_flag("all") {
        unapplied.clone()
    } else if let Some(n) = m.get_one::<String>("number") {
        let n: i64 = n.parse().unwrap_or(1);
        let cnt = if n < 0 {
            (unapplied.len() as i64 + n).max(0) as usize
        } else {
            n as usize
        };
        let cnt = cnt.min(unapplied.len());
        unapplied[..cnt].to_vec()
    } else {
        m.get_many::<String>("patch")
            .map(|v| v.cloned().collect())
            .unwrap_or_default()
    };
    if targets.is_empty() {
        targets = vec![unapplied[0].clone()];
    }
    if m.get_flag("reverse") {
        targets.reverse();
    }
    let mut report = crate::report::Report::new();
    let opts = crate::stackops::PushOpts {
        committer_date_is_author_date: m.get_flag("committer-date-is-author-date"),
        conflicts_allow: crate::cmds::conflicts_allow(m),
        set_tree: m.get_flag("set-tree"),
        keep: m.get_flag("keep"),
    };
    let mut conflicted = false;
    for name in &targets {
        match crate::stackops::apply_patch(ctx, &mut stack, &mut report, name, &opts) {
            Ok(c) => {
                if c {
                    conflicted = true;
                    report.items.last_mut().unwrap().suffix = Some("(conflict)".to_string());
                }
            }
            Err(e) => {
                stack.save(ctx, "push (CONFLICT)")?;
                let head_name = stack.applied.last().cloned();
                report.finish(head_name.as_deref());
                out(&report.render());
                crate::cmds::show_conflict_files(ctx)?;
                return Err(e);
            }
        }
    }
    let head_name = stack.applied.last().cloned();
    report.finish(head_name.as_deref());
    let msg = if conflicted { "push (CONFLICT)" } else { "push" };
    stack.save(ctx, msg)?;
    out(&report.render());
    if conflicted {
        crate::cmds::show_conflict_files(ctx)?;
        bail!("merge conflicts; resolve conflicts manually then refresh or undo the operation with `stg undo --hard`.");
    }
    Ok(EXIT_OK)
}

fn goto(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let target = m
        .get_one::<String>("patch")
        .cloned()
        .ok_or_else(|| anyhow!("patch to go to is required"))?;
    let mut stack = stack_of(ctx, m)?;
    crate::git::check_index(ctx)?;
    let mut report = crate::report::Report::new();
    let opts = crate::stackops::PushOpts {
        committer_date_is_author_date: m.get_flag("committer-date-is-author-date"),
        conflicts_allow: crate::cmds::conflicts_allow(m),
        set_tree: false,
        keep: m.get_flag("keep"),
    };
    let names: Vec<String> = stack.all_names().iter().map(|s| s.to_string()).collect();
    if !names.contains(&target) {
        bail!("patch `{target}` does not exist");
    }
    if stack.applied.contains(&target) {
        // pop the patches above it
        let pos = stack.applied.iter().position(|x| x == &target).unwrap();
        let to_pop: Vec<String> = stack.applied[pos + 1..].to_vec();
        if !to_pop.is_empty() {
            for name in to_pop.iter().rev() {
                crate::stackops::unapply(ctx, &mut stack, &mut report, name)?;
            }
            report.unapply(to_pop.clone());
        }
    } else {
        // push the patches up to and including the target
        let upos = stack.unapplied.iter().position(|x| x == &target).unwrap();
        let to_push: Vec<String> = stack.unapplied[..=upos].to_vec();
        for name in &to_push {
            crate::stackops::apply_patch(ctx, &mut stack, &mut report, name, &opts)?;
        }
    }
    let head_name = stack.applied.last().cloned();
    report.finish(head_name.as_deref());
    stack.save(ctx, "goto")?;
    out(&report.render());
    Ok(EXIT_OK)
}

fn float(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let mut stack = stack_of(ctx, m)?;
    crate::git::check_index(ctx)?;
    let targets: Vec<String> = m
        .get_many::<String>("patch")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let mut report = crate::report::Report::new();
    let opts = crate::stackops::PushOpts {
        committer_date_is_author_date: m.get_flag("committer-date-is-author-date"),
        conflicts_allow: true,
        set_tree: false,
        keep: m.get_flag("keep"),
    };
    // pop everything, then push: the non-targets first, then the targets
    let applied = stack.applied.clone();
    for name in applied.iter().rev() {
        crate::stackops::unapply(ctx, &mut stack, &mut report, name)?;
    }
    if !applied.is_empty() {
        report.unapply(applied.clone());
    }
    let mut order: Vec<String> = Vec::new();
    for name in &stack.unapplied.clone() {
        if !targets.contains(name) {
            order.push(name.clone());
        }
    }
    for t in &targets {
        order.push(t.clone());
    }
    for name in &order {
        crate::stackops::apply_patch(ctx, &mut stack, &mut report, name, &opts)?;
    }
    let head_name = stack.applied.last().cloned();
    report.finish(head_name.as_deref());
    stack.save(ctx, "float")?;
    out(&report.render());
    Ok(EXIT_OK)
}

fn sink(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let mut stack = stack_of(ctx, m)?;
    crate::git::check_index(ctx)?;
    let targets: Vec<String> = m
        .get_many::<String>("patch")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let mut report = crate::report::Report::new();
    let opts = crate::stackops::PushOpts {
        committer_date_is_author_date: m.get_flag("committer-date-is-author-date"),
        conflicts_allow: true,
        set_tree: false,
        keep: m.get_flag("keep"),
    };
    let targets = if targets.is_empty() {
        vec![stack.applied.last().cloned().ok_or_else(|| anyhow!("no patches applied"))?]
    } else {
        targets
    };
    let applied = stack.applied.clone();
    for name in applied.iter().rev() {
        crate::stackops::unapply(ctx, &mut stack, &mut report, name)?;
    }
    if !applied.is_empty() {
        report.unapply(applied.clone());
    }
    let mut order: Vec<String> = Vec::new();
    // the patches to sink go first (to the bottom)
    for t in &targets {
        order.push(t.clone());
    }
    for name in &stack.unapplied.clone() {
        if !targets.contains(name) {
            order.push(name.clone());
        }
    }
    for name in &order {
        crate::stackops::apply_patch(ctx, &mut stack, &mut report, name, &opts)?;
    }
    let head_name = stack.applied.last().cloned();
    report.finish(head_name.as_deref());
    stack.save(ctx, "sink")?;
    out(&report.render());
    Ok(EXIT_OK)
}

fn hide(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let mut stack = stack_of(ctx, m)?;
    crate::git::check_index(ctx)?;
    let targets: Vec<String> = m
        .get_many::<String>("patch")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let mut report = crate::report::Report::new();
    for name in &targets {
        if stack.applied.contains(name) {
            // hide an applied patch: unapply it first
            let pos = stack.applied.iter().position(|x| x == name).unwrap();
            let to_pop: Vec<String> = stack.applied[pos..].to_vec();
            for n in to_pop.iter().rev() {
                crate::stackops::unapply(ctx, &mut stack, &mut report, n)?;
            }
            report.unapply(to_pop.clone());
            // push back the patches above it
            let opts = crate::stackops::PushOpts::default();
            for n in to_pop.iter().skip(1) {
                crate::stackops::apply_patch(ctx, &mut stack, &mut report, n, &opts)?;
            }
        }
        crate::stackops::mark_hidden(&mut stack, name);
        report.hide(vec![name.clone()]);
    }
    let head_name = stack.applied.last().cloned();
    report.finish(head_name.as_deref());
    stack.save(ctx, "hide")?;
    out(&report.render());
    Ok(EXIT_OK)
}

fn unhide(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let mut stack = stack_of(ctx, m)?;
    crate::git::check_index(ctx)?;
    let targets: Vec<String> = m
        .get_many::<String>("patch")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let mut report = crate::report::Report::new();
    for name in &targets {
        if !stack.hidden.contains(name) {
            bail!("patch `{name}` is not hidden");
        }
        crate::stackops::mark_unapplied(&mut stack, name);
        // keep the unapplied list ordered
        report.unhide(vec![name.clone()]);
    }
    let head_name = stack.applied.last().cloned();
    report.finish(head_name.as_deref());
    stack.save(ctx, "unhide")?;
    out(&report.render());
    Ok(EXIT_OK)
}

fn delete(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let mut stack = stack_of(ctx, m)?;
    crate::git::check_index(ctx)?;
    let applied = stack.applied.clone();
    let mut targets: Vec<String> = Vec::new();
    if m.get_flag("all") {
        targets.extend(stack.applied.clone());
        targets.extend(stack.unapplied.clone());
        targets.extend(stack.hidden.clone());
    } else {
        if m.get_flag("applied") {
            targets.extend(stack.applied.clone());
        }
        if m.get_flag("unapplied") {
            targets.extend(stack.unapplied.clone());
        }
        if m.get_flag("hidden") {
            targets.extend(stack.hidden.clone());
        }
        if m.get_flag("top") {
            if let Some(t) = stack.applied.last() {
                targets.push(t.clone());
            }
        }
        if let Some(v) = m.get_many::<String>("patch") {
            for p in v {
                targets.push(p.clone());
            }
        }
    }
    if targets.is_empty() {
        return Ok(EXIT_OK);
    }
    let mut report = crate::report::Report::new();
    let opts = crate::stackops::PushOpts::default();
    // pop the applied patches that are to be deleted, plus everything above them
    let mut to_pop: Vec<String> = Vec::new();
    let applied_targets: Vec<String> =
        targets.iter().filter(|n| stack.applied.contains(*n)).cloned().collect();
    if !applied_targets.is_empty() {
        let highest = applied_targets
            .iter()
            .filter_map(|n| stack.applied.iter().position(|x| x == n))
            .min()
            .unwrap();
        to_pop = stack.applied[highest..].to_vec();
    }
    let keep: Vec<String> = to_pop.iter().filter(|n| !targets.contains(n)).cloned().collect();
    for name in to_pop.iter().rev() {
        crate::stackops::unapply(ctx, &mut stack, &mut report, name)?;
    }
    if !to_pop.is_empty() {
        report.unapply(to_pop.clone());
    }
    // delete the patches
    let mut deleted: Vec<String> = Vec::new();
    for name in &targets {
        if !stack.patches.contains_key(name) {
            bail!("patch `{name}` does not exist");
        }
        stack.meta.remove(name);
        stack.patches.remove(name);
        stack.applied.retain(|n| n != name);
        stack.unapplied.retain(|n| n != name);
        stack.hidden.retain(|n| n != name);
        deleted.push(name.clone());
    }
    report.delete(deleted.clone());
    // push back the patches that remain
    let mut conflicted = false;
    for name in &keep {
        match crate::stackops::apply_patch(ctx, &mut stack, &mut report, name, &opts) {
            Ok(c) => {
                if c {
                    conflicted = true;
                    report.items.last_mut().unwrap().suffix = Some("(conflict)".to_string());
                }
            }
            Err(e) => {
                stack.save(ctx, "delete (CONFLICT)")?;
                let head_name = stack.applied.last().cloned();
                report.finish(head_name.as_deref());
                out(&report.render());
                crate::cmds::show_conflict_files(ctx)?;
                return Err(e);
            }
        }
    }
    let head_name = stack.applied.last().cloned();
    report.finish(head_name.as_deref());
    let msg = if conflicted { "delete (CONFLICT)" } else { "delete" };
    stack.save(ctx, msg)?;
    out(&report.render());
    if conflicted {
        crate::cmds::show_conflict_files(ctx)?;
        bail!("merge conflicts; resolve conflicts manually then refresh or undo the operation with `stg undo --hard`.");
    }
    let _ = applied;
    Ok(EXIT_OK)
}

fn rename(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let mut stack = stack_of(ctx, m)?;
    let args: Vec<String> = m
        .get_many::<String>("patches")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let (old, new) = match args.len() {
        0 => bail!("rename: old and new patch names required"),
        1 => (stack.applied.last().cloned().unwrap_or_default(), args[0].clone()),
        _ => (args[0].clone(), args[1].clone()),
    };
    if old.is_empty() {
