//! Core patch stack operations.
use anyhow::{anyhow, bail, Result};
use git2::{Oid, ObjectType};
use std::collections::BTreeMap;
use std::io::Write;
use std::path::{Path, PathBuf};

use crate::ctx::Ctx;
use crate::report::Report;
use crate::stack::Stack;
use crate::util::{errln, out, outln};

pub struct PushOpts {
    pub committer_date_is_author_date: bool,
    pub conflicts_allow: bool,
    pub set_tree: bool,
    pub keep: bool,
}

impl Default for PushOpts {
    fn default() -> Self {
        PushOpts {
            committer_date_is_author_date: false,
            conflicts_allow: true,
            set_tree: false,
            keep: false,
        }
    }
}

/// Run a git subprocess in the work tree with GIT_DIR / GIT_WORK_TREE set.
pub fn git(ctx: &Ctx, args: &[&str], env: Option<&[(&str, String)]>) -> Result<std::process::Output> {
    use std::process::Command;
    let mut cmd = Command::new("git");
    cmd.args(args);
    cmd.env("GIT_DIR", ctx.gitdir_arg());
    cmd.env("GIT_WORK_TREE", ctx.workdir_arg());
    if let Some(e) = env {
        for (k, v) in e {
            cmd.env(k, v);
        }
    }
    cmd.output().map_err(|e| anyhow!("`git`: {e}"))
}

pub fn git_ok(ctx: &Ctx, args: &[&str], env: Option<&[(&str, String)]>) -> Result<()> {
    let out = git(ctx, args, env)?;
    if !out.status.success() {
        bail!("`git{}`: {}", crate::ctx::fmt_args_str(args), String::from_utf8_lossy(&out.stderr).trim_end());
    }
    Ok(())
}

/// Run git and ignore the exit status, returning whether it succeeded.
pub fn git_try(ctx: &Ctx, args: &[&str], env: Option<&[(&str, String)]>) -> bool {
    match git(ctx, args, env) {
        Ok(o) => o.status.success(),
        Err(_) => false,
    }
}

pub fn mark_applied(stack: &mut Stack, name: &str) {
    stack.unapplied.retain(|n| n != name);
    stack.hidden.retain(|n| n != name);
    if !stack.applied.contains(&name.to_string()) {
        stack.applied.push(name.to_string());
    }
}

pub fn mark_unapplied(stack: &mut Stack, name: &str) {
    stack.applied.retain(|n| n != name);
    if !stack.unapplied.contains(&name.to_string()) {
        stack.unapplied.push(name.to_string());
    }
}

pub fn mark_hidden(stack: &mut Stack, name: &str) {
    stack.applied.retain(|n| n != name);
    stack.unapplied.retain(|n| n != name);
    if !stack.hidden.contains(&name.to_string()) {
        stack.hidden.push(name.to_string());
    }
}

/// Set the branch head and update the index and work tree.
pub fn set_head(ctx: &Ctx, stack: &mut Stack, oid: Oid) -> Result<()> {
    let tree = crate::git::commit_of(ctx, oid)?.tree_id();
    stack.head = oid;
    crate::git::checkout_tree(ctx, tree)?;
    Ok(())
}

/// Pop (unapply) the topmost applied patch.
pub fn unapply(ctx: &Ctx, stack: &mut Stack, name: &str) -> Result<()> {
    let oid = *stack
        .patches
        .get(name)
        .ok_or_else(|| anyhow!("patch `{name}` does not exist"))?;
    let commit = crate::git::commit_of(ctx, oid)?;
    let parents: Vec<Oid> = commit.parent_ids().collect();
    let new_head = if parents.is_empty() { Oid::zero() } else { parents[0] };
    if new_head.is_zero() {
        bail!("cannot unapply patch `{name}`");
    }
    set_head(ctx, stack, new_head)?;
    mark_unapplied(stack, name);
    Ok(())
}

/// The temp index path used by StGit when applying patches.
pub fn temp_index(ctx: &Ctx) -> PathBuf {
    ctx.gitdir.join(format!("index-temp-stg-{}", std::process::id()))
}

/// Apply (push) a patch onto the current head. Returns true if there were conflicts.
pub fn apply_patch(
    ctx: &Ctx,
    stack: &mut Stack,
    report: &mut Report,
    name: &str,
    opts: &PushOpts,
) -> Result<bool> {
    let meta = stack
        .meta
        .get(name)
        .cloned()
        .ok_or_else(|| anyhow!("patch `{name}` does not exist"))?;
    let head = stack.head;
    let head_tree = crate::git::commit_of(ctx, head)?.tree_id();
    let bottom = meta.bottom;
    let top = meta.top;
    if opts.set_tree {
        let tree_oid = top;
        return finish_apply(ctx, stack, report, name, head, tree_oid, opts, false);
    }
    // clear any unmerged index state, then try a simple tree merge
    let _ = git(ctx, &["update-index", "-q", "--unmerged", "--refresh"], None);
    let args: Vec<&str> = vec![
        "read-tree",
        "-m",
        "-u",
        "--exclude-per-directory=.gitignore",
        &bottom.to_string(),
        &top.to_string(),
    ];
    let simple_ok = git_try(ctx, &args, None);
    let tree_oid;
    if simple_ok {
        tree_oid = crate::git::index_tree(ctx)?;
    } else {
        // Complex path: build a temporary index, apply the patch to it and
        // then perform a three-way merge.
        let tmp = temp_index(ctx);
        let tstr = tmp.display().to_string();
        let envs = vec![
            ("GIT_DIR".to_string(), ctx.gitdir.display().to_string()),
            ("GIT_INDEX_FILE".to_string(), tstr.clone()),
            ("GIT_WORK_TREE".to_string(), ctx.workdir.display().to_string()),
        ];
        let env_refs: Vec<(&str, String)> = envs
            .iter()
            .map(|(k, v)| (k.as_str(), v.clone()))
            .collect();
        let tmp_rel = ctx
            .gitdir
            .file_name()
            .map(|f| format!("./{}/index-temp-stg-{}", f.to_string_lossy(), std::process::id()))
            .unwrap_or_default();
        let env_rel: Vec<(&str, String)> = vec![
            ("GIT_DIR", ctx.gitdir_arg()),
            ("GIT_INDEX_FILE", tmp_rel),
            ("GIT_WORK_TREE", ctx.workdir_arg()),
        ];
        let _ = git(ctx, &["read-tree", &head_tree.to_string()], Some(&env_refs))?;
        let diff = crate::git::git_capture_nocwd(ctx, &[
            "diff-tree",
            "--full-index",
            "--binary",
            "--patch",
            &bottom.to_string(),
            &top.to_string(),
            "--",
        ])?;
        let _ = git(ctx, &["version"], Some(&env_rel));
        let mut child = std::process::Command::new("git")
            .args(["apply", "--cached", "--3way"])
            .env("GIT_DIR", ctx.gitdir.display().to_string())
            .env("GIT_INDEX_FILE", &tstr)
            .env("GIT_WORK_TREE", ctx.workdir.display().to_string())
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .map_err(|e| anyhow!("`git apply`: {e}"))?;
        {
            let stdin = child.stdin.take().unwrap();
            let data = diff.clone();
            std::thread::spawn(move || {
                let mut w = stdin;
                let _ = w.write_all(data.as_bytes());
            });
        }
        let ap = child.wait_with_output().map_err(|e| anyhow!("`git apply`: {e}"))?;
        if !ap.status.success() && !opts.conflicts_allow {
            let _ = std::fs::remove_file(&tmp);
            bail!("merge conflicts; resolve conflicts manually then refresh or undo the operation with `stg undo --hard`.");
        }
        // merge the temporary index into the real one and resolve conflicts
        let margs: Vec<&str> = vec![
            "merge-recursive",
            &bottom.to_string(),
            "--",
            &head_tree.to_string(),
            &top.to_string(),
        ];
        let mo = git(ctx, &margs, None)?;
        let _ = std::fs::remove_file(&tmp);
        if !mo.status.success() {
            bail!(
                "`git merge-recursive`: {}",
                String::from_utf8_lossy(&mo.stderr).trim_end()
            );
        }
        tree_oid = tree_from_index(ctx)?;
    }
    finish_apply(ctx, stack, report, name, head, tree_oid, opts, !simple_ok)
}

fn finish_apply(
    ctx: &Ctx,
    stack: &mut Stack,
    report: &mut Report,
    name: &str,
    head: Oid,
    tree_oid: Oid,
    opts: &PushOpts,
    conflicted: bool,
) -> Result<bool> {
    let meta = stack.meta.get(name).cloned().unwrap_or_default();
    let bottom = crate::git::commit_of(ctx, head)?.tree_id();
    let msg = meta.message.clone();
    let time = if opts.committer_date_is_author_date {
        Some(crate::git::commit_of(ctx, head)?.time().seconds())
    } else {
        None
    };
    let oid = crate::git::create_commit(ctx, tree_oid, &[head], &msg, time)?;
    let mut newmeta = meta.clone();
    newmeta.bottom = bottom;
    newmeta.top = tree_oid;
    if opts.committer_date_is_author_date {
        let c = crate::git::commit_of(ctx, head)?;
        newmeta.date = crate::util::format_git_date(c.time().seconds(), c.time().offset_minutes());
    }
    stack.meta.insert(name.to_string(), newmeta);
    stack.patches.insert(name.to_string(), oid);
    stack.head = oid;
    mark_applied(stack, name);
    report.apply(vec![name.to_string()], true);
    if conflicted {
        if let Some(last) = report.items.last_mut() {
            last.suffix = Some("(conflict)".to_string());
        }
        show_unmerged(ctx)?;
    }
    Ok(conflicted)
}

/// Build a tree from the index, using the "our" stage for conflicted paths.
pub fn tree_from_index(ctx: &Ctx) -> Result<Oid> {
    let mut index = ctx.repo.index()?;
    index.read(false)?;
    let conflicted: Vec<String> = index
        .conflicts()?
        .filter_map(|c| {
            c.ok().and_then(|x| {
                x.our.or(x.their).map(|e| String::from_utf8_lossy(&e.path).into_owned())
            })
        })
        .collect();
    let mut entries: BTreeMap<String, (Oid, i32)> = BTreeMap::new();
    for i in 0..index.len() {
        let e = index.get(i).ok_or_else(|| anyhow!("bad index"))?;
        let p = String::from_utf8_lossy(&e.path).into_owned();
        entries.insert(p, (e.id, e.mode as i32));
    }
    for c in &conflicted {
        if let Some(e) = index.get_path(Path::new(c), 1) {
            entries.insert(c.clone(), (e.id, e.mode as i32));
        }
    }
    crate::git::build_tree(ctx, &entries)
}

/// Print the list of unmerged files (like `git status -s`).
pub fn show_unmerged(ctx: &Ctx) -> Result<()> {
    let files = crate::git::git_capture_nocwd(ctx, &["diff", "--name-only", "--diff-filter=U", "-z"])?;
    for f in files.split('\0') {
        if f.is_empty() {
            continue;
        }
        let args = ["status", "-s", "--", f];
        let o = crate::git::git_capture_nocwd(ctx, &args)?;
        out(&o);
    }
    Ok(())
}

/// Stage a blob in the index.
pub fn stage_file(ctx: &Ctx, path: &Path, data: &[u8]) -> Result<()> {
    let mut index = ctx.repo.index()?;
    index.read(false)?;
    let odb = ctx.repo.odb()?;
    let oid = odb.write(ObjectType::Blob, data)?;
    let mut entry: git2::IndexEntry = unsafe { std::mem::zeroed() };
    entry.id = oid;
    entry.mode = 0o100644;
    entry.path = path.as_os_str().to_string_lossy().into_owned().into_bytes();
    entry.file_size = data.len() as u32;
    index.add(&entry)?;
    index.write()?;
    Ok(())
}
