            let data = diff.clone();
            std::thread::spawn(move || {
                let mut w = stdin;
                let _ = w.write_all(data.as_bytes());
            });
        }
        let ap = child.wait_with_output().map_err(|e| anyhow!("`git apply`: {e}"))?;
        if !ap.status.success() && !opts.conflicts_allow {
            let _ = std::fs::remove_file(&tmp);
            bail!("merge conflicts; resolve conflicts manually then refresh or undo the operation with `stg undo --hard`.");
        }
        // merge the temporary index into the real one and resolve conflicts
        let margs: Vec<&str> = vec![
            "merge-recursive",
            &bottom.to_string(),
            "--",
            &head_tree.to_string(),
            &top.to_string(),
        ];
        let mo = git(ctx, &margs, None)?;
        let _ = std::fs::remove_file(&tmp);
        if !mo.status.success() {
            bail!(
                "`git merge-recursive`: {}",
                String::from_utf8_lossy(&mo.stderr).trim_end()
            );
        }
        tree_oid = tree_from_index(ctx)?;
    }
    finish_apply(ctx, stack, report, name, head, tree_oid, opts, !simple_ok)
}

fn finish_apply(
    ctx: &Ctx,
    stack: &mut Stack,
    report: &mut Report,
    name: &str,
    head: Oid,
    tree_oid: Oid,
    opts: &PushOpts,
    conflicted: bool,
) -> Result<bool> {
    let meta = stack.meta.get(name).cloned().unwrap_or_default();
    let bottom = crate::git::commit_of(ctx, head)?.tree_id();
    let msg = meta.message.clone();
    let time = if opts.committer_date_is_author_date {
        Some(crate::git::commit_of(ctx, head)?.time().seconds())
    } else {
        None
    };
    let oid = crate::git::create_commit(ctx, tree_oid, &[head], &msg, time)?;
    let mut newmeta = meta.clone();
    newmeta.bottom = bottom;
    newmeta.top = tree_oid;
    if opts.committer_date_is_author_date {
        let c = crate::git::commit_of(ctx, head)?;
        newmeta.date = crate::util::format_git_date(c.time().seconds(), c.time().offset_minutes());
    }
    stack.meta.insert(name.to_string(), newmeta);
    stack.patches.insert(name.to_string(), oid);
    stack.head = oid;
    mark_applied(stack, name);
    report.apply(vec![name.to_string()], true);
    if conflicted {
        if let Some(last) = report.items.last_mut() {
            last.suffix = Some("(conflict)".to_string());
        }
        show_unmerged(ctx)?;
    }
    Ok(conflicted)
}

/// Build a tree from the index, using the "our" stage for conflicted paths.
pub fn tree_from_index(ctx: &Ctx) -> Result<Oid> {
    let mut index = ctx.repo.index()?;
    index.read(false)?;
    let conflicted: Vec<String> = index
        .conflicts()?
        .filter_map(|c| {
            c.ok().and_then(|x| {
                x.our.or(x.their).map(|e| String::from_utf8_lossy(&e.path).into_owned())
            })
        })
        .collect();
    let mut entries: BTreeMap<String, (Oid, i32)> = BTreeMap::new();
    for i in 0..index.len() {
        let e = index.get(i).ok_or_else(|| anyhow!("bad index"))?;
        let p = String::from_utf8_lossy(&e.path).into_owned();
        entries.insert(p, (e.id, e.mode as i32));
    }
    for c in &conflicted {
        if let Some(e) = index.get_path(Path::new(c), 1) {
            entries.insert(c.clone(), (e.id, e.mode as i32));
        }
    }
    crate::git::build_tree(ctx, &entries)
}

/// Print the list of unmerged files (like `git status -s`).
pub fn show_unmerged(ctx: &Ctx) -> Result<()> {
    let files = crate::git::git_capture_nocwd(ctx, &["diff", "--name-only", "--diff-filter=U", "-z"])?;
    for f in files.split('\0') {
        if f.is_empty() {
            continue;
        }
        let args = ["status", "-s", "--", f];
        let o = crate::git::git_capture_nocwd(ctx, &args)?;
        out(&o);
    }
    Ok(())
}

/// Stage a blob in the index.
pub fn stage_file(ctx: &Ctx, path: &Path, data: &[u8]) -> Result<()> {
    let mut index = ctx.repo.index()?;
    index.read(false)?;
    let odb = ctx.repo.odb()?;
    let oid = odb.write(ObjectType::Blob, data)?;
    let mut entry: git2::IndexEntry = unsafe { std::mem::zeroed() };
    entry.id = oid;
    entry.mode = 0o100644;
    entry.path = path.as_os_str().to_string_lossy().into_owned().into_bytes();
    entry.file_size = data.len() as u32;
    index.add(&entry)?;
    index.write()?;
    Ok(())
}
