pub fn apply_patch(
    ctx: &Ctx,
    stack: &mut Stack,
    report: &mut Report,
    name: &str,
    opts: &PushOpts,
) -> Result<bool> {
    let meta = stack
        .meta
        .get(name)
        .cloned()
        .ok_or_else(|| anyhow!("patch `{name}` does not exist"))?;
    let head = stack.head;
    let head_tree = crate::git::commit_of(ctx, head)?.tree_id();
    let bottom = meta.bottom;
    let top = meta.top;
    let old_patch_oid = *stack.patches.get(name).unwrap_or(&Oid::zero());
    if opts.set_tree {
        return finish_apply(ctx, stack, report, name, head, top, opts, false, old_patch_oid);
    }
    let b = bottom.to_string();
    let t = top.to_string();
    let h = head_tree.to_string();
    if bottom == head_tree {
        // fast path: merge the patch tree directly into the index
        let args: Vec<&str> = vec![
            "read-tree",
            "-m",
            "-u",
            "--exclude-per-directory=.gitignore",
            &b,
            &t,
        ];
        if git_try(ctx, &args, None) {
            let tree_oid = crate::git::index_tree(ctx)?;
            return finish_apply(ctx, stack, report, name, head, tree_oid, opts, false, old_patch_oid);
        }
    }
    // slow path: build a temporary index and apply the patch to it
    let tmp = temp_index(ctx);
    let tstr = tmp.display().to_string();
    let tmp_rel = format!("{}/index-temp-stg-{}", ctx.gitdir_arg(), std::process::id());
    let env_abs: Vec<(&str, String)> = vec![
        ("GIT_DIR", ctx.gitdir.display().to_string()),
        ("GIT_INDEX_FILE", tstr.clone()),
        ("GIT_WORK_TREE", ctx.workdir.display().to_string()),
    ];
    let env_rel: Vec<(&str, String)> = vec![
        ("GIT_DIR", ctx.gitdir_arg()),
        ("GIT_INDEX_FILE", tmp_rel),
        ("GIT_WORK_TREE", ctx.workdir_arg()),
    ];
    let _ = git(ctx, &["read-tree", &h], Some(&env_abs))?;
    let diff = crate::git::git_capture_nocwd(ctx, &[
        "diff-tree",
        "--full-index",
        "--binary",
        "--patch",
        &b,
        &t,
        "--",
    ])?;
    let _ = git(ctx, &["version"], Some(&env_rel));
    let ap = git_stdin(ctx, &["apply", "--cached", "--3way"], &diff, Some(&env_abs))?;
    let tree_oid;
    let mut conflicted = false;
    if ap.status.success() {
        let wt = git(ctx, &["write-tree"], Some(&env_abs))?;
        let merged = String::from_utf8_lossy(&wt.stdout).trim().to_string();
        let _ = std::fs::remove_file(&tmp);
        let _ = git(ctx, &["update-index", "-q", "--unmerged", "--refresh"], None);
        let args: Vec<&str> = vec![
            "read-tree",
            "-m",
            "-u",
            "--exclude-per-directory=.gitignore",
            &h,
            &merged,
        ];
        git_ok(ctx, &args, None)?;
        tree_oid = crate::git::index_tree(ctx)?;
    } else {
        if !opts.conflicts_allow {
            let _ = std::fs::remove_file(&tmp);
            bail!("merge conflicts; resolve conflicts manually then refresh or undo the operation with `stg undo --hard`.");
        }
        let args: Vec<&str> = vec![
            "read-tree",
            "-m",
            "-u",
            "--exclude-per-directory=.gitignore",
            &h,
            &h,
        ];
        let _ = git(ctx, &args, None);
        let margs: Vec<&str> = vec!["merge-recursive", &b, "--", &h, &t];
