            bail!("merge conflicts; resolve conflicts manually then refresh or undo the operation with `stg undo --hard`.");
        }
        let args: Vec<&str> = vec![
            "read-tree",
            "-m",
            "-u",
            "--exclude-per-directory=.gitignore",
            &h,
            &h,
        ];
        let _ = git(ctx, &args, None);
        let margs: Vec<&str> = vec!["merge-recursive", &b, "--", &h, &t];
        let mo = git(ctx, &margs, None)?;
        let _ = std::fs::remove_file(&tmp);
        if !mo.status.success() && mo.status.code() != Some(1) {
            bail!(
                "`git merge-recursive`: {}",
                String::from_utf8_lossy(&mo.stderr).trim_end()
            );
        }
        tree_oid = tree_from_index(ctx)?;
        conflicted = true;
    }
    finish_apply(ctx, stack, report, name, head, tree_oid, opts, conflicted, old_patch_oid)
}

/// Run git with data on stdin.
pub fn git_stdin(
    ctx: &Ctx,
    args: &[&str],
    input: &str,
    env: Option<&[(&str, String)]>,
) -> Result<std::process::Output> {
    use std::process::{Command, Stdio};
    let mut cmd = Command::new("git");
    cmd.args(args);
    cmd.env("GIT_DIR", ctx.gitdir_arg());
    cmd.env("GIT_WORK_TREE", ctx.workdir_arg());
    if let Some(e) = env {
        for (k, v) in e {
            cmd.env(k, v);
        }
    }
    cmd.stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let mut child = cmd.spawn().map_err(|e| anyhow!("`git`: {e}"))?;
    {
        let stdin = child.stdin.take().unwrap();
        let data = input.to_string();
        std::thread::spawn(move || {
            let mut w = stdin;
            let _ = w.write_all(data.as_bytes());
        });
    }
    child.wait_with_output().map_err(|e| anyhow!("`git`: {e}"))
}

