fn commit(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let mut stack = stack_of(ctx, m)?;
    crate::git::check_conflicts(ctx)?;
    crate::git::check_index(ctx)?;
    let applied = stack.applied.clone();
    if applied.is_empty() {
        bail!("no patches applied");
    }
    let targets: Vec<String> = if m.get_flag("all") {
        applied.clone()
    } else if let Some(n) = m.get_one::<String>("number") {
        let n: usize = n.parse().unwrap_or(1);
        let n = n.min(applied.len());
        applied[..n].to_vec()
    } else {
        let v: Vec<String> = m
            .get_many::<String>("patch")
            .map(|x| x.cloned().collect())
            .unwrap_or_default();
        if v.is_empty() {
            vec![applied[0].clone()]
        } else {
            v
        }
    };
    for t in &targets {
        if !stack.patches.contains_key(t) {
            bail!("patch `{t}` does not exist");
        }
    }
    // rearrange so the targets are at the bottom
    let mut order: Vec<String> = Vec::new();
    for t in &targets {
        order.push(t.clone());
    }
    for a in &applied {
        if !targets.contains(a) {
            order.push(a.clone());
        }
    }
    if order != applied {
        crate::stackops::reorder_applied(ctx, &mut stack, &order)?;
    }
    let mut report = crate::report::Report::new();
    crate::stackops::commit_patches(ctx, &mut stack, &mut report, &order, m.get_flag("allow-empty"))?;
    stack.save(ctx, "commit")?;
    out(&report.render());
    Ok(EXIT_OK)
}

fn uncommit(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let mut stack = stack_of(ctx, m)?;
    crate::git::check_conflicts(ctx)?;
    crate::git::check_index(ctx)?;
    let mut report = crate::report::Report::new();
    let names: Vec<String> = m
        .get_many::<String>("patchname")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let count: Option<usize> = m.get_one::<String>("number").and_then(|s| s.parse().ok());
    let to: Option<String> = m.get_one::<String>("to").cloned();
    let exclusive = m.get_flag("exclusive");
    let mut commits: Vec<Oid> = Vec::new();
    let head = stack.head;
    if let Some(t) = &to {
        let oid = crate::cmds::resolve_revision(ctx, m, t)?;
        // walk from the head down to the target
        let mut cur = head;
        loop {
            if cur == oid {
                break;
            }
            let c = crate::git::commit_of(ctx, cur)?;
            match c.parent_ids().next() {
                Some(p) => cur = p,
                None => bail!("cannot uncommit to `{t}`"),
            }
            if !cur.is_zero() {
                commits.push(cur);
            }
            if cur == Oid::zero() {
                bail!("cannot uncommit to `{t}`");
            }
        }
        if exclusive && !commits.is_empty() {
            commits.pop();
        }
    } else if let Some(n) = count {
        let mut cur = head;
        for _ in 0..n {
            let c = crate::git::commit_of(ctx, cur)?;
            let parents: Vec<Oid> = c.parent_ids().collect();
            if parents.len() != 1 {
                bail!("cannot uncommit `{cur}` which does not have exactly one parent");
            }
            commits.push(parents[0]);
            cur = parents[0];
        }
    } else {
        // one commit per given patch name, starting from the newest
        let n = names.len().max(1);
        let mut cur = head;
        for _ in 0..n {
            let c = crate::git::commit_of(ctx, cur)?;
            let parents: Vec<Oid> = c.parent_ids().collect();
            if parents.len() != 1 {
                bail!("cannot uncommit `{cur}` which does not have exactly one parent");
            }
            commits.push(parents[0]);
            cur = parents[0];
        }
    }
    if commits.is_empty() {
        bail!("nothing to uncommit");
    }
    // the new base is the oldest uncommitted commit's parent
    let oldest = commits.last().unwrap();
    let oldest_commit = crate::git::commit_of(ctx, *oldest)?;
    let new_base = oldest_commit.parent_ids().next().unwrap_or(Oid::zero());
    if new_base.is_zero() {
        bail!("cannot uncommit to the root commit");
    }
    // build patches for each commit, from oldest to newest
    let mut new_patches: Vec<(String, Oid, crate::stack::PatchMeta)> = Vec::new();
    let mut names_iter = names.clone().into_iter();
    let mut used_prefix: Option<String> = None;
    if let Some(n) = count {
        if let Some(p) = names.first() {
            used_prefix = Some(p.clone());
        }
        let _ = n;
    }
    let total = commits.len();
    for (i, c) in commits.iter().rev().enumerate() {
        let commit = crate::git::commit_of(ctx, *c)?;
        let tree = commit.tree_id();
        let author = crate::patchdesc::commit_author(&commit);
        let date = crate::patchdesc::commit_date(&commit);
        let msg = commit.message().unwrap_or("").to_string();
        let name = if total == 1 {
            match names.first() {
                Some(n) => n.clone(),
                None => crate::patchdesc::generate_name(&msg, &stack)?,
            }
        } else if let Some(p) = &used_prefix {
            format!("{p}{}", total - i)
        } else if let Some(n) = names.get(total - 1 - i) {
            n.clone()
        } else {
            crate::patchdesc::generate_name(&msg, &stack)?
        };
        let mut meta = crate::stack::PatchMeta::default();
        meta.top = tree;
        meta.bottom = new_base_tree(ctx, new_base, i, &commits);
        meta.author = author;
        meta.date = date;
        meta.message = msg;
        new_patches.push((name, *c, meta));
    }
    // update the stack
    let mut ordered: Vec<(String, Oid, crate::stack::PatchMeta)> = Vec::new();
    for (name, oid, meta) in new_patches.into_iter().rev() {
        ordered.push((name, oid, meta));
    }
    for (name, oid, meta) in &ordered {
        if stack.patches.contains_key(name) {
            bail!("patch `{name}` already exists");
        }
        stack.patches.insert(name.clone(), *oid);
        stack.meta.insert(name.clone(), meta.clone());
        stack.unapplied.insert(0, name.clone());
    }
    stack.head = new_base;
    crate::git::checkout_tree(ctx, crate::git::commit_of(ctx, new_base)?.tree_id())?;
    let names: Vec<String> = ordered.iter().map(|(n, _, _)| n.clone()).collect();
    report.apply(names.clone(), false);
    let head_name = stack.applied.last().cloned();
    report.finish(head_name.as_deref());
    stack.save(ctx, "uncommit")?;
    out(&report.render());
    Ok(EXIT_OK)
}

fn new_base_tree(ctx: &Ctx, base: Oid, i: usize, commits: &[Oid]) -> Result<Oid> {
    if i == 0 {
        crate::git::commit_of(ctx, base)?.tree_id()
    } else {
        crate::git::commit_of(ctx, commits[commits.len() - i])?.tree_id()
    }
}

fn clean(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let mut stack = stack_of(ctx, m)?;
    crate::git::check_conflicts(ctx)?;
    crate::git::check_index(ctx)?;
    let mut report = crate::report::Report::new();
    let a = m.get_flag("applied");
    let u = m.get_flag("unapplied");
    let mut empty_applied: Vec<String> = Vec::new();
    for name in &stack.applied.clone() {
        if crate::cmds::is_empty_patch(&stack, name) {
            empty_applied.push(name.clone());
        }
    }
    let mut empty_unapplied: Vec<String> = Vec::new();
    for name in &stack.unapplied.clone() {
        if crate::cmds::is_empty_patch(&stack, name) {
            empty_unapplied.push(name.clone());
        }
    }
    let mut to_delete: Vec<String> = Vec::new();
    if !a && !u {
        to_delete.extend(empty_applied.clone());
        to_delete.extend(empty_unapplied.clone());
    } else {
        if a {
            to_delete.extend(empty_applied);
        }
        if u {
            to_delete.extend(empty_unapplied);
        }
    }
    for name in &to_delete {
        stack.meta.remove(name);
        stack.patches.remove(name);
        stack.applied.retain(|n| n != name);
        stack.unapplied.retain(|n| n != name);
        stack.hidden.retain(|n| n != name);
    }
    if !to_delete.is_empty() {
        report.delete(to_delete);
    }
    let head_name = stack.applied.last().cloned();
    report.finish(head_name.as_deref());
    if !to_delete.is_empty() {
        stack.save(ctx, "clean")?;
    }
    out(&report.render());
    Ok(EXIT_OK)
}

fn undo_redo(ctx: &mut Ctx, m: &ArgMatches, redo: bool) -> Result<i32> {
    let stack = stack_of(ctx, m)?;
    let n: usize = m
        .get_one::<String>("number")
        .and_then(|s| s.parse().ok())
        .unwrap_or(1);
    // build the chain of states
    let mut chain: Vec<Oid> = Vec::new();
    let mut cur = Some(stack.state);
    while let Some(c) = cur {
        chain.push(c);
        let commit = crate::git::commit_of(ctx, c)?;
        let p = crate::git::tree_prev(ctx, commit.tree_id())?;
        cur = p;
    }
    if redo {
        // the states 1..=n back must be undo states
        for i in 0..n {
            if i + 1 >= chain.len() {
                bail!("no more redo information available");
            }
            let msg = crate::git::commit_of(ctx, chain[i + 1])?.message().unwrap_or("");
            if !msg.starts_with("undo") {
                bail!("no more redo information available");
            }
        }
        if n + 1 >= chain.len() {
            bail!("no more redo information available");
        }
        restore_state(ctx, &stack, chain[n + 1], &format!("redo {n}"), m)?;
    } else {
        if n >= chain.len() {
            bail!("not enough undo information available");
        }
        restore_state(ctx, &stack, chain[n], &format!("undo {n}"), m)?;
    }
    let stack = Stack::load(ctx, &stack.branch)?;
    let head_name = stack.applied.last().cloned();
    let mut report = crate::report::Report::new();
    report.finish(head_name.as_deref());
    out(&report.render());
    Ok(EXIT_OK)
}

fn undo(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    if m.get_flag("hard") {
        // reset the index and worktree after the undo
    }
    undo_redo(ctx, m, false)
}

fn redo(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
