/// Update the index with the current work tree contents and return the tree.
pub fn worktree_tree(ctx: &Ctx) -> Result<Oid> {
    let paths = crate::git::worktree_changed_paths(ctx)?;
    let p = paths.join("\0");
    let env: Vec<(&str, String)> = vec![
        ("GIT_DIR", ctx.gitdir.display().to_string()),
        ("GIT_WORK_TREE", ctx.workdir.display().to_string()),
    ];
    let _ = git_stdin(
        ctx,
        &["update-index", "--remove", "--add", "--ignore-skip-worktree-entries", "-z", "--stdin"],
        &p,
        Some(&env),
    )?;
    let wt = git(ctx, &["write-tree"], Some(&env))?;
    Ok(crate::util::parse_oid(String::from_utf8_lossy(&wt.stdout).trim())
        .ok_or_else(|| anyhow!("failed to write tree"))?)
}

/// Reorder the applied patches by popping and pushing.
pub fn reorder_applied(
    ctx: &Ctx,
    stack: &mut Stack,
    order: &[String],
) -> Result<()> {
    let applied = stack.applied.clone();
    for name in applied.iter().rev() {
        unapply(ctx, stack, name)?;
    }
    let opts = PushOpts::default();
    let mut report = Report::new();
    for name in order {
        apply_patch(ctx, stack, &mut report, name, &opts)?;
    }
    Ok(())
}
