/// The tracked paths whose work tree contents differ from the index.
pub fn worktree_changed_paths(ctx: &Ctx) -> Result<Vec<String>> {
    let mut opts = git2::StatusOptions::new();
    opts.include_untracked(false)
        .recurse_untracked_dirs(false)
        .exclude_submodules(true)
        .include_ignored(false)
        .update_index(false);
    let statuses = ctx.repo.statuses(Some(&mut opts))?;
    let mut out = Vec::new();
    for e in statuses.iter() {
        if e.index_to_workdir().is_some() {
            if let Ok(p) = e.path() {
                out.push(p.to_string());
            }
        }
    }
    Ok(out)
}

/// Read the "prev" stack state oid from a tree's stack.json.
pub fn tree_prev(ctx: &Ctx, tree: Oid) -> Result<Option<Oid>> {
    let t = tree_of(ctx, tree)?;
    match tree_blob(ctx, &t, "stack.json") {
        Some(data) => {
            let v: serde_json::Value = serde_json::from_str(std::str::from_utf8(&data)?)?;
            Ok(v.get("prev")
                .and_then(|x| x.as_str())
                .and_then(crate::util::parse_oid))
        }
        None => Ok(None),
    }
}
