/// Validate a patch name (git refname rules, no '/').
pub fn check_patch_name(name: &str) -> Result<()> {
    if name.is_empty() {
        bail!("invalid patch name: empty");
    }
    if name.contains('/') {
        bail!("invalid patch name `{name}`: may not contain '/'");
    }
    for c in name.chars() {
        if c.is_control() || c == ' ' || c == '~' || c == '^' || c == ':' || c == '?' || c == '*' || c == '[' || c == '\\' {
            bail!("invalid patch name `{name}`");
        }
    }
    if name.starts_with('.') || name.ends_with(".lock") || name.ends_with('.') || name.ends_with('/') {
        bail!("invalid patch name `{name}`");
    }
    Ok(())
}
