//! Patch description editing.
use anyhow::{anyhow, bail, Result};
use std::io::Read;

use crate::ctx::Ctx;
use crate::stack::{PatchMeta, Stack};

pub struct PatchDesc {
    pub name: Option<String>,
    pub author: String,
    pub date: String,
    pub message: String,
}

impl PatchDesc {
    pub fn new(ctx: &Ctx, _stack: &Stack, name: Option<String>) -> Result<PatchDesc> {
        let author = match crate::stack::committer_name(ctx) {
            Ok(n) => match crate::stack::committer_email(ctx) {
                Ok(e) => format!("{n} <{e}>"),
                Err(_) => n,
            },
            Err(_) => String::new(),
        };
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0);
        let date = crate::util::format_git_date(now, local_offset());
        Ok(PatchDesc { name, author, date, message: String::new() })
    }

    pub fn template(&self) -> String {
        let mut s = String::new();
        s.push_str(&format!("Patch:  {}\n", self.name.clone().unwrap_or_default()));
        s.push_str(&format!("Author: {}\n", self.author));
        s.push_str(&format!("Date:   {}\n", self.date));
        s.push_str("\n\n\n");
        s.push_str("# Please enter the message for your patch. Lines starting with\n");
        s.push_str("# '#' will be ignored. An empty message aborts the new patch.\n");
        s.push_str("# The patch name and author information may also be modified.\n");
        s
    }

    pub fn from_text(text: &str) -> PatchDesc {
        let mut name = None;
        let mut author = String::new();
        let mut date = String::new();
        let mut msg: Vec<String> = Vec::new();
        for line in text.lines() {
            if let Some(r) = line.strip_prefix("Patch:") {
                let r = r.trim();
                if !r.is_empty() {
                    name = Some(r.to_string());
                }
                continue;
            }
            if let Some(r) = line.strip_prefix("Author:") {
                author = r.trim().to_string();
                continue;
            }
            if let Some(r) = line.strip_prefix("Date:") {
                date = r.trim().to_string();
                continue;
            }
            if line.starts_with('#') {
                continue;
            }
            msg.push(line.to_string());
        }
        while msg.first().map(|l| l.is_empty()).unwrap_or(false) {
            msg.remove(0);
        }
        PatchDesc { name, author, date, message: msg.join("\n") }
    }

    /// Run the editor on the template and return the resulting text.
    pub fn edit(&self, ctx: &Ctx, _m: &crate::clap_shim::ArgMatches, _is_new: bool) -> Result<String> {
        let text = self.template();
        let path = std::path::PathBuf::from(".stgit-edit.txt");
        std::fs::write(&path, &text).map_err(|e| anyhow!("{e}"))?;
        let editor = std::env::var("GIT_EDITOR")
            .or_else(|_| std::env::var("EDITOR"))
            .or_else(|_| std::env::var("VISUAL"))
            .unwrap_or_else(|_| "vi".to_string());
        crate::util::errln("hint: Waiting for your editor to close the file...");
        let st = std::process::Command::new(&editor)
            .arg(&path)
            .status()
            .map_err(|e| anyhow!("running editor: {editor}: {e}"))?;
        if !st.success() {
            let _ = std::fs::remove_file(&path);
            bail!("editor exited with {st}");
        }
        let s = std::fs::read_to_string(&path).map_err(|e| anyhow!("{e}"))?;
        let _ = std::fs::remove_file(&path);
        Ok(s)
    }
}

pub fn local_offset() -> i32 {
    // git uses the local timezone offset; StGit stores the committer offset
    let _ = &();
    0
}

/// Generate a patch name from the first line of a message.
pub fn generate_name(msg: &str, stack: &Stack) -> Result<String> {
    let first = msg.lines().next().unwrap_or("");
    let mut s = String::new();
    for c in first.chars() {
        if c.is_alphanumeric() || c == '_' || c == '.' {
            for l in c.to_lowercase() {
                s.push(l);
            }
        } else {
            s.push(' ');
        }
    }
    let words: Vec<&str> = s.split_whitespace().collect();
    if words.is_empty() {
        return Ok(unique_name(stack, "patch"));
    }
    let mut name = words[0].to_string();
    for w in &words[1..] {
        if name.len() + 1 + w.len() <= 30 {
            name.push('-');
            name.push_str(w);
        } else {
            break;
        }
    }
    Ok(unique_name(stack, &name))
}

pub fn unique_name(stack: &Stack, base: &str) -> String {
    if !stack.patches.contains_key(base) {
        return base.to_string();
    }
    for i in 1..10000 {
        let n = format!("{base}-{i}");
        if !stack.patches.contains_key(&n) {
            return n;
        }
    }
    format!("{base}-x")
}

/// Parse a patch description, applying trailers and author options.
pub fn apply_edit(
    ctx: &Ctx,
    stack: &Stack,
    text: &str,
    m: &crate::clap_shim::ArgMatches,
    existing: Option<&PatchMeta>,
) -> Result<String> {
    let d = PatchDesc::from_text(text);
    let mut msg = d.message.clone();
    let default_author = match existing {
        Some(e) => e.author.clone(),
        None => match crate::stack::committer_name(ctx) {
            Ok(n) => match crate::stack::committer_email(ctx) {
                Ok(e) => format!("{n} <{e}>"),
                Err(_) => n,
            },
            Err(_) => String::new(),
        },
    };
    if let Some(a) = m.try_get_one::<String>("author").ok().flatten() {
        msg = format!("{}\n\nAuthor: {a}", msg).replace("\n\nAuthor:", "\nAuthor:");
    }
    let _ = &default_author;
    // trailers
    let mut trailers: Vec<String> = Vec::new();
    if let Some(v) = m.try_get_many::<String>("signoff").ok().flatten() {
        for val in v {
            let val = if val.is_empty() { default_author.clone() } else { val.clone() };
            trailers.push(format!("Signed-off-by: {val}"));
        }
    }
    if let Some(v) = m.try_get_many::<String>("ack").ok().flatten() {
        for val in v {
            let val = if val.is_empty() { default_author.clone() } else { val.clone() };
            trailers.push(format!("Acked-by: {val}"));
        }
    }
    if let Some(v) = m.try_get_many::<String>("review").ok().flatten() {
        for val in v {
            let val = if val.is_empty() { default_author.clone() } else { val.clone() };
            trailers.push(format!("Reviewed-by: {val}"));
        }
    }
    for t in trailers {
        if !msg.contains(&t) {
            if !msg.is_empty() && !msg.ends_with('\n') {
                msg.push('\n');
            }
            msg.push_str(&t);
            msg.push('\n');
        }
    }
    Ok(msg)
}

pub fn make_meta(
    ctx: &Ctx,
    stack: &Stack,
    name: &str,
    msg: &str,
    d: &PatchDesc,
    m: &crate::clap_shim::ArgMatches,
) -> Result<PatchMeta> {
    let _ = (ctx, stack, name, m);
    let mut meta = PatchMeta::default();
    meta.author = if d.author.is_empty() {
        match crate::stack::committer_name(ctx) {
            Ok(n) => match crate::stack::committer_email(ctx) {
                Ok(e) => format!("{n} <{e}>"),
                Err(_) => n,
            },
            Err(_) => String::new(),
        }
    } else {
        d.author.clone()
    };
    meta.date = d.date.clone();
    meta.message = msg.to_string();
    Ok(meta)
}

pub fn commit_author(commit: &git2::Commit) -> String {
    let s = commit.author();
    format!("{} <{}>", s.name().unwrap_or(""), s.email().unwrap_or(""))
}

pub fn commit_date(commit: &git2::Commit) -> String {
    let t = commit.time();
    crate::util::format_git_date(t.seconds(), t.offset_minutes())
}
