/// Commit the given patches into the stack base.
pub fn commit_patches(
    ctx: &Ctx,
    stack: &mut Stack,
    report: &mut Report,
    names: &[String],
    allow_empty: bool,
) -> Result<()> {
    let _ = allow_empty;
    if names.is_empty() {
        return Ok(());
    }
    let last = names.last().unwrap();
    let top = *stack
        .patches
        .get(last)
        .ok_or_else(|| anyhow!("patch `{last}` does not exist"))?;
    let tree = crate::git::commit_of(ctx, top)?.tree_id();
    let base = crate::git::commit_of(ctx, stack.head)?;
    let parents: Vec<Oid> = base.parent_ids().collect();
    let meta = stack.meta.get(last).cloned().unwrap_or_default();
    let msg = meta.message.clone();
    let oid = crate::git::create_commit(ctx, tree, &parents, &msg, None)?;
    let mut new_stack = Stack::empty(&stack.branch, oid);
    new_stack.prev = stack.prev;
    new_stack.state = stack.state;
    new_stack.state_commit = stack.state_commit;
    new_stack.unapplied = stack
        .applied
        .iter()
        .filter(|n| !names.contains(n))
        .cloned()
        .collect();
    new_stack.hidden = stack.hidden.clone();
    new_stack.meta = stack.meta.clone();
    for n in names.iter() {
        new_stack.meta.remove(n);
        new_stack.patches.remove(n);
    }
    new_stack.unapplied.extend(stack.unapplied.iter().cloned());
    crate::git::checkout_tree(ctx, tree)?;
    *stack = new_stack;
    report.commit(names.to_vec());
    Ok(())
}
