# rewrite refresh
start = s.index("fn refresh(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {")
end = s.index("fn old_oid_str(")
new = '''fn refresh(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let mut stack = stack_of(ctx, m)?;
    crate::git::check_conflicts(ctx)?;
    let patch = match m.try_get_one::<String>("patch").ok().flatten() {
        Some(p) => p.clone(),
        None => stack
            .applied
            .last()
            .cloned()
            .ok_or_else(|| anyhow!("no patches applied"))?,
    };
    if !stack.applied.contains(&patch) {
        bail!("patch `{patch}` is not applied");
    }
    let index_refresh = m.get_flag("index");
    if !index_refresh && !m.get_flag("force") {
        let (i, _) = crate::git::cleanliness(ctx)?;
        if !i {
            bail!("index not clean; use `refresh` or `reset --hard`");
        }
    }
    let new_tree = if index_refresh {
        crate::git::index_tree(ctx)?
    } else {
        crate::stackops::worktree_tree(ctx)?
    };
    let old_head = stack.head;
    let old_tree = crate::git::commit_of(ctx, old_head)?.tree_id();
    let mut report = crate::report::Report::new();
    // create the temporary patch
    let temp_name = crate::patchdesc::generate_name("refresh-temp", &stack)?;
    let meta = crate::stack::PatchMeta {
        bottom: old_tree,
        top: new_tree,
        author: crate::git::committer(ctx)?,
        date: crate::patchdesc::commit_date(&crate::git::commit_of(ctx, old_head)?),
        message: format!("Refresh temporary patch for {patch}"),
    };
    let temp_oid = crate::git::create_commit(ctx, new_tree, &[old_head], &meta.message, None)?;
    stack.meta.insert(temp_name.clone(), meta);
    stack.patches.insert(temp_name.clone(), temp_oid);
    crate::stackops::mark_applied(&mut stack, &temp_name);
    stack.head = temp_oid;
    report.newpatch(vec![temp_name.clone()]);
    stack.save(ctx, &format!("refresh {temp_name} (create temporary patch)"))?;
    // unapply and delete the temporary patch
    crate::stackops::unapply(ctx, &mut stack, &temp_name)?;
    report.unapply(vec![temp_name.clone()]);
    stack.meta.remove(&temp_name);
    stack.patches.remove(&temp_name);
    report.delete(vec![temp_name.clone()]);
    // merge the temporary patch into the target patch
    let pmeta = stack.meta.get(&patch).cloned().unwrap_or_default();
    let mut newmeta = pmeta.clone();
    newmeta.top = new_tree;
    let oid = crate::git::create_commit(ctx, new_tree, &[stack.head], &pmeta.message.clone(), None)?;
    let o = stack.patches.get(&patch).map(|x| x.to_string()).unwrap_or_default();
    let n = oid.to_string();
    let _ = crate::stackops::git(ctx, &["notes", "copy", &o, &n], None);
    stack.meta.insert(patch.clone(), newmeta);
    stack.patches.insert(patch.clone(), oid);
    stack.head = oid;
    report.refresh(vec![patch.clone()]);
    let head_name = stack.applied.last().cloned();
    report.finish(head_name.as_deref());
    stack.save(ctx, &format!("refresh {patch}"))?;
    out(&report.render());
    Ok(EXIT_OK)
}

