pub fn commit_patches(
    ctx: &Ctx,
    stack: &mut Stack,
    report: &mut Report,
    names: &[String],
    _allow_empty: bool,
) -> Result<()> {
    if names.is_empty() {
        return Ok(());
    }
    // pop all the applied patches
    let applied = stack.applied.clone();
    for name in applied.iter().rev() {
        unapply(ctx, stack, name)?;
    }
    // create the new base commit
    let last = names.last().unwrap();
    let top = *stack
        .patches
        .get(last)
        .ok_or_else(|| anyhow!("patch `{last}` does not exist"))?;
    let tree = crate::git::commit_of(ctx, top)?.tree_id();
    let parents: Vec<Oid> = crate::git::commit_of(ctx, stack.head)?.parent_ids().collect();
    let meta = stack.meta.get(last).cloned().unwrap_or_default();
    let msg = meta.message.clone();
    let new_base = crate::git::create_commit(ctx, tree, &parents, &msg, None)?;
    stack.head = new_base;
    crate::git::checkout_tree(ctx, tree)?;
    // remove the committed patches from the stack
    for n in names.iter() {
        stack.meta.remove(n);
        stack.patches.remove(n);
        stack.unapplied.retain(|x| x != n);
    }
    report.commit(names.to_vec());
    // push back the remaining applied patches
    let remaining: Vec<String> = stack.unapplied.clone();
    let opts = PushOpts::default();
    for name in &remaining {
        if names.contains(name) {
            continue;
        }
        apply_patch(ctx, stack, &mut Report::new(), name, &opts)?;
        stack.unapplied.retain(|x| x != name);
    }
    Ok(())
}

'''
