{"command": "cd /workspace && python3 - <<'PYEOF'
s=open('src/cmds.rs').read()
start = s.index("fn commit(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {")
end = s.index("fn uncommit(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {")
new = '''fn commit(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let mut stack = stack_of(ctx, m)?;
    crate::git::check_conflicts(ctx)?;
    crate::git::check_index(ctx)?;
    let applied = stack.applied.clone();
    if applied.is_empty() {
        bail!("no patches applied");
    }
    let targets: Vec<String> = if m.get_flag("all") {
        applied.clone()
    } else if let Some(n) = m.get_one::<String>("number") {
        let n: usize = n.parse().unwrap_or(1);
        let n = n.min(applied.len());
        applied[..n].to_vec()
    } else {
        let v: Vec<String> = m
            .get_many::<String>("patch")
            .map(|x| x.cloned().collect())
            .unwrap_or_default();
        if v.is_empty() {
            vec![applied[0].clone()]
        } else {
            v
        }
    };
    for t in &targets {
        if !stack.patches.contains_key(t) {
            bail!("patch `{t}` does not exist");
        }
    }
    let mut report = crate::report::Report::new();
    let mut conflicted = false;
    // does the stack need rearranging?
    let mut needs_reorder = targets.len() != applied.len();
    if !needs_reorder {
        for (i, t) in targets.iter().enumerate() {
            if applied.get(i) != Some(t) {
                needs_reorder = true;
            }
        }
    }
    if needs_reorder {
        for name in applied.iter().rev() {
            crate::stackops::unapply(ctx, &mut stack, name)?;
        }
        report.unapply(applied.clone());
        let mut order: Vec<String> = targets.clone();
        for a in &applied {
            if !targets.contains(a) {
                order.push(a.clone());
            }
        }
        let opts = crate::stackops::PushOpts::default();
        for name in &order {
            let c = crate::stackops::apply_patch(ctx, &mut stack, &mut report, name, &opts)?;
            stack.unapplied.retain(|x| x != name);
            if c {
                conflicted = true;
                break;
            }
        }
    }
    if !conflicted {
        crate::stackops::commit_patches(ctx, &mut stack, &mut report, &targets, m.get_flag("allow-empty"))?;
    }
    let head_name = stack.applied.last().cloned();
    report.finish(head_name.as_deref());
    let msg = if conflicted { "commit (CONFLICT)" } else { "commit" };
    stack.save(ctx, msg)?;
    out(&report.render());
    if conflicted {
        bail!("merge conflicts; resolve conflicts manually then refresh or undo the operation with `stg undo --hard`.");
    }
    Ok(EXIT_OK)
}

'''
