/// Create a commit with an explicit author/committer identity.
pub fn create_commit_authored(
    ctx: &Ctx,
    tree_oid: Oid,
    parents: &[Oid],
    message: &str,
    author: &str,
    date: &str,
    m: &clap::ArgMatches,
) -> Result<Oid> {
    let tree = tree_of(ctx, tree_oid)?;
    let cdis = m.get_flag("committer-date-is-author-date");
    let time = crate::patchdesc::parse_date_to_time(date);
    let sig = git2::Signature::new(author, "", &git2::Time::new(time, 0))?;
    let sig2 = if cdis {
        git2::Signature::new(author, "", &git2::Time::new(time, 0))?
    } else {
        ctx.repo.committer_from_env()?
    };
    let mut parent_objs = Vec::new();
    for p in parents {
        parent_objs.push(commit_of(ctx, *p)?);
    }
    let refs: Vec<&git2::Commit> = parent_objs.iter().collect();
    let oid = ctx
        .repo
        .commit(None, &sig, &sig2, message, &tree, &refs)?;
    Ok(oid)
}
