/// Parse an --authdate value ("now" or an ISO-ish date) into a unix timestamp.
pub fn parse_authdate(_ctx: &Ctx, s: &str) -> Result<String> {
    if s == "now" {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0);
        return Ok(crate::util::format_git_date(now, 0));
    }
    Ok(s.to_string())
}

pub fn parse_date_to_time(s: &str) -> i64 {
    // "YYYY-MM-DD HH:MM:SS +ZZZZ"
    let parts: Vec<&str> = s.split_whitespace().collect();
    if parts.len() < 2 {
        return 0;
    }
    let d: Vec<&str> = parts[0].split('-').collect();
    let t: Vec<&str> = parts[1].split(':').collect();
    if d.len() < 3 || t.len() < 3 {
        return 0;
    }
    let y: i64 = d[0].parse().unwrap_or(1970);
    let mo: i64 = d[1].parse().unwrap_or(1);
    let dy: i64 = d[2].parse().unwrap_or(1);
    let hh: i64 = t[0].parse().unwrap_or(0);
    let mm: i64 = t[1].parse().unwrap_or(0);
    let ss: i64 = t[2].parse().unwrap_or(0);
    let days = crate::util::days_from_civil(y, mo, dy);
    days * 86400 + hh * 3600 + mm * 60 + ss
}
