    newmeta.top = tree;
    stack.meta.insert(name.clone(), newmeta);
    stack.patches.insert(name.clone(), oid_new);
    stack.head = oid_new;
    if stack.applied.last().map(|n| n == &name).unwrap_or(false) {
        crate::git::checkout_tree(ctx, tree)?;
    }
    stack.save(ctx, &format!("edit {name}"))?;
    Ok(EXIT_OK)
}
