new = '''fn hide(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let mut stack = stack_of(ctx, m)?;
    crate::git::check_conflicts(ctx)?;
    crate::git::check_index(ctx)?;
    let targets: Vec<String> = m
        .get_many::<String>("patch")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let mut report = crate::report::Report::new();
    let mut conflicted = false;
    let mut conflicted_name: Option<String> = None;
    for name in &targets {
        if stack.hidden.contains(name) {
            bail!("patch `{name}` is already hidden");
        }
        if stack.applied.contains(name) {
            // hide an applied patch: unapply it and the patches above it
            let pos = stack.applied.iter().position(|x| x == name).unwrap();
            let to_pop: Vec<String> = stack.applied[pos..].to_vec();
            for n in to_pop.iter().rev() {
                crate::stackops::unapply(ctx, &mut stack, n)?;
            }
            report.unapply(to_pop.clone());
            // push back the patches above it
            let opts = crate::stackops::PushOpts::default();
            for n in to_pop.iter().skip(1) {
                let c = crate::stackops::apply_patch(ctx, &mut stack, &mut report, n, &opts)?;
                stack.unapplied.retain(|x| x != n);
                if c {
                    conflicted = true;
                    conflicted_name = Some(format!(" {n}"));
                    break;
                }
            }
        }
        if conflicted {
            break;
        }
        crate::stackops::mark_hidden(&mut stack, name);
        report.hide(vec![name.clone()]);
    }
    if !conflicted {
        let head_name = stack.applied.last().cloned();
        report.finish(head_name.as_deref());
        // the head line comes before the hidden markers
        if let Some(idx) = report.items.iter().rposition(|i| i.kind == crate::report::Kind::Head) {
            let item = report.items.remove(idx);
            let hide_idx = report.items.iter().position(|i| i.kind == crate::report::Kind::Hide);
            if let Some(h) = hide_idx {
                report.items.insert(h, item);
            } else {
                report.items.push(item);
            }
        }
    }
    let msg = if conflicted { "hide (CONFLICT)" } else { "hide" };
    stack.save(ctx, msg)?;
    out(&report.render());
    if conflicted {
        if let Some(n) = conflicted_name {
            bail!("patch{n} does not apply cleanly");
        }
        bail!("merge conflicts; resolve conflicts manually then refresh or undo the operation with `stg undo --hard`.");
    }
    Ok(EXIT_OK)
}

