//! Resolution of git revspec suffixes (`^`, `~`) with StGit's error messages.
use anyhow::{anyhow, bail, Result};
use git2::Oid;

use crate::ctx::Ctx;

pub fn abbrev(oid: &Oid) -> String {
    let s = oid.to_string();
    s[..7.min(s.len())].to_string()
}

/// Apply a revspec suffix to a commit oid.
pub fn resolve(ctx: &Ctx, mut oid: Oid, suffix: &str) -> Result<Oid> {
    let chars: Vec<char> = suffix.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        i += 1;
        let mut num = String::new();
        while i < chars.len() && chars[i].is_ascii_digit() {
            num.push(chars[i]);
            i += 1;
        }
        let n: usize = if num.is_empty() { 1 } else { num.parse().unwrap_or(1) };
        if c == '^' {
            let parents: Vec<Oid> = crate::git::commit_of(ctx, oid)?.parent_ids().collect();
            if parents.len() < n {
                bail!(
                    "invalid StGit revision `{}{}`: Commit {} has {} parents and parent number {} is out of range",
                    oid, if num.is_empty() { String::new() } else { format!("^{}", n) },
                    abbrev(&oid),
                    parents.len(),
                    n
                );
            }
            oid = parents[n - 1];
        } else if c == '~' {
            let commit = crate::git::commit_of(ctx, oid)?;
            let has_parent = commit.parent_ids().next().is_some();
            if !has_parent {
                bail!(
                    "invalid StGit revision `{}{}`: Commit {} has 0 ancestors along the first parent and ancestor number {} is out of range",
                    oid,
                    if num.is_empty() { String::new() } else { format!("~{}", n) },
                    abbrev(&oid),
                    n
                );
            }
            let mut cur = oid;
            for _ in 0..n {
                let cm = crate::git::commit_of(ctx, cur)?;
                match cm.parent_ids().next() {
                    Some(p) => cur = p,
                    None => bail!("finding ancestor: repository does not have enough commit depth"),
                }
            }
            oid = cur;
        } else {
            bail!("invalid revision suffix");
        }
    }
    Ok(oid)
}

pub fn wrap_err(spec: &str, e: anyhow::Error) -> anyhow::Error {
    let s = format!("{e}");
    if s.starts_with("finding ancestor") {
        e
    } else {
        anyhow!("invalid StGit revision `{spec}`: {s}")
    }
}
