fn branch(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let cur = ctx.branch()?;
    // operations
    if m.get_flag("list") {
        return branch_list(ctx, &cur);
    }
    if let Some(d) = m.get_one::<String>("describe") {
        let b = m.try_get_one::<String>("branch").ok().flatten().cloned().unwrap_or(cur.clone());
        set_config(ctx, &format!("branch.{b}.description"), d)?;
        return Ok(EXIT_OK);
    }
    if m.get_flag("protect") || m.get_flag("unprotect") {
        let b = m.try_get_one::<String>("branch").ok().flatten().cloned().unwrap_or(cur.clone());
        let val = if m.get_flag("protect") { "true" } else { "false" };
        set_config(ctx, &format!("branch.{b}.stgit.protect"), val)?;
        return Ok(EXIT_OK);
    }
    if m.get_flag("cleanup") {
        let b = m.try_get_one::<String>("branch").ok().flatten().cloned().unwrap_or(cur.clone());
        branch_cleanup(ctx, &b)?;
        return Ok(EXIT_OK);
    }
    if m.get_flag("delete") {
        let b = m.try_get_one::<String>("branch").ok().flatten().cloned().unwrap_or(cur.clone());
        branch_delete(ctx, &b, m.get_flag("force"), &cur)?;
        return Ok(EXIT_OK);
    }
    if let Some(new) = m.get_one::<String>("rename") {
        let old = m
            .try_get_one::<String>("branch")
            .ok()
            .flatten()
            .cloned()
            .unwrap_or_else(|| cur.clone());
        branch_rename(ctx, &old, new, &cur)?;
        return Ok(EXIT_OK);
    }
    if let Some(new) = m.get_one::<String>("create") {
        let committish = m.try_get_one::<String>("committish").ok().flatten().cloned();
        branch_create(ctx, new, committish)?;
        return Ok(EXIT_OK);
    }
    if let Some(new) = m.get_one::<String>("clone") {
        branch_clone(ctx, new, &cur)?;
        return Ok(EXIT_OK);
    }
    if let Some(b) = m.get_one::<String>("branch") {
        // switch
        if b == &cur {
            return Ok(EXIT_OK);
        }
        let target = if b == "-" || b.starts_with("@{-") {
            b.clone()
        } else {
            b.clone()
        };
        let args: Vec<String> = if target == "-" {
            vec!["checkout".into(), "@{-1}".into()]
        } else if target.starts_with("@{-") {
            vec!["checkout".into(), target.clone()]
        } else {
            vec!["checkout".into(), target.clone()]
        };
        let out = crate::git::git_capture(ctx, &args).map_err(|e| anyhow!("branch `{}` not found", target))?;
        out(&out);
        return Ok(EXIT_OK);
    }
    outln(&cur);
    Ok(EXIT_OK)
}

fn set_config(ctx: &Ctx, key: &str, val: &str) -> Result<()> {
    let mut cfg = ctx.repo.config()?;
    cfg.set_str(key, val)?;
    Ok(())
}

fn branch_list(ctx: &Ctx, cur: &str) -> Result<i32> {
    let mut names: Vec<String> = Vec::new();
    for r in ctx.repo.branches(Some(git2::BranchType::Local)) {
        if let Ok(b) = r {
            if let Ok(n) = b.name() {
                names.push(n.to_string());
            }
        }
    }
    names.sort();
    let maxlen = names.iter().map(|n| n.len()).max().unwrap_or(0);
    let mut lines = Vec::new();
    for n in &names {
        let initialized = ctx.repo.find_reference(&crate::stack::stack_ref_name(n)).is_ok();
        let flags = if initialized { "s" } else { "" };
        let marker = if n == cur { "> " } else { "  " };
        let descr = ctx
            .repo
            .config()
            .ok()
            .and_then(|c| c.get_string(&format!("branch.{n}.description")).ok())
            .unwrap_or_default();
        let pad = " ".repeat(maxlen - n.len() + 2);
        lines.push(format!("{}{} \t{}{}|{}", marker, flags, n, pad, descr));
    }
    outln(&lines.join("\n"));
    Ok(EXIT_OK)
}

fn branch_cleanup(ctx: &Ctx, b: &str) -> Result<()> {
    if ctx.repo.find_reference(&crate::stack::stack_ref_name(b)).is_err() {
        bail!("branch `{b}` has no StGit stack to clean up");
    }
    if let Ok(mut r) = ctx.repo.find_reference(&crate::stack::stack_ref_name(b)) {
        r.delete()?;
    }
    let glob = format!("refs/patches/{}/*", b);
    if let Ok(it) = ctx.repo.references_glob(&glob) {
        for r in it {
            if let Ok(r) = r {
                r.delete().ok();
            }
        }
    }
    Ok(())
}

fn branch_delete(ctx: &Ctx, b: &str, force: bool, cur: &str) -> Result<()> {
    let _ = force;
    if b == cur {
        bail!("cannot delete the current branch");
    }
    let args = vec!["branch".to_string(), "-D".to_string(), b.to_string()];
    let out = crate::git::git_capture(ctx, &args).map_err(|e| anyhow!("branch `{b}` not found"))?;
    out(&out);
    branch_cleanup(ctx, b)?;
    Ok(())
}

fn branch_rename(ctx: &Ctx, old: &str, new: &str, cur: &str) -> Result<()> {
    if ctx.repo.find_branch(old, git2::BranchType::Local).is_err() {
        bail!("branch `{old}` not found");
    }
    if ctx.repo.find_branch(new, git2::BranchType::Local).is_ok() {
        bail!("branch `{new}` already exists");
    }
    let args = vec!["branch".to_string(), "-m".to_string(), old.to_string(), new.to_string()];
    crate::git::git_capture(ctx, &args)?;
    // move the stack ref and the patch refs
    if let Ok(r) = ctx.repo.find_reference(&crate::stack::stack_ref_name(old)) {
        let oid = r.target().unwrap_or(Oid::zero());
        r.delete().ok();
        if !oid.is_zero() {
            ctx.repo
                .reference(&crate::stack::stack_ref_name(new), oid, true, "rename")?;
        }
    }
    let glob = format!("refs/patches/{}/*", old);
    if let Ok(it) = ctx.repo.references_glob(&glob) {
        for r in it.flatten() {
            let name = r.name().unwrap_or("").to_string();
            let oid = r.target().unwrap_or(Oid::zero());
            r.delete().ok();
            if let Some(stripped) = name.strip_prefix(&format!("refs/patches/{old}/")) {
                if !oid.is_zero() {
                    ctx.repo.reference(
                        &crate::stack::patch_ref_name(new, stripped),
                        oid,
                        true,
                        "rename",
                    )?;
                }
            }
        }
    }
    if cur == old {
        let args = vec!["checkout".to_string(), new.to_string()];
        crate::git::git_capture(ctx, &args)?;
    }
    Ok(())
}

fn branch_create(ctx: &mut Ctx, new: &str, committish: Option<String>) -> Result<()> {
    if ctx.repo.find_branch(new, git2::BranchType::Local).is_ok() {
        bail!("branch `{new}` already exists");
    }
    let start = match &committish {
        Some(c) => crate::cmds::resolve_revision(ctx, m_dummy(), c)?,
        None => ctx.repo.head()?.target().unwrap_or(Oid::zero()),
    };
    if start.is_zero() {
        bail!("branch `{new}` not created");
    }
    errln("info: Recording as a local branch");
    ctx.repo.reference(&format!("refs/heads/{new}"), start, true, "branch: Created from HEAD")?;
    // initialize the stack
    let head = start;
    let refname = crate::stack::stack_ref_name(new);
    if ctx.repo.find_reference(&refname).is_err() {
        let mut stack = Stack::empty(new, head);
        stack.save(ctx, "initialize")?;
    }
    let args = vec!["checkout".to_string(), new.to_string()];
    crate::git::git_capture(ctx, &args)?;
    Ok(EXIT_OK)
}

fn branch_clone(ctx: &mut Ctx, new: &str, cur: &str) -> Result<i32> {
    let name = if new.is_empty() { format!("{cur}-clone") } else { new.to_string() };
    if ctx.repo.find_branch(&name, git2::BranchType::Local).is_ok() {
        bail!("branch `{name}` already exists");
    }
    let head = ctx.repo.refname_to_id(&format!("refs/heads/{cur}"))?;
    ctx.repo
        .reference(&format!("refs/heads/{name}"), head, true, "branch: Created from HEAD")?;
    // clone the stack state
    if let Ok(r) = ctx.repo.find_reference(&crate::stack::stack_ref_name(cur)) {
        let oid = r.target().unwrap_or(Oid::zero());
        if !oid.is_zero() {
            ctx.repo
                .reference(&crate::stack::stack_ref_name(&name), oid, true, "clone")?;
        }
    }
    let glob = format!("refs/patches/{cur}/*");
    if let Ok(it) = ctx.repo.references_glob(&glob) {
        for r in it.flatten() {
            let pname = r.name().unwrap_or("").to_string();
            let oid = r.target().unwrap_or(Oid::zero());
            if let Some(stripped) = pname.strip_prefix(&format!("refs/patches/{cur}/")) {
                if !oid.is_zero() {
                    ctx.repo.reference(
                        &crate::stack::patch_ref_name(&name, stripped),
                        oid,
                        true,
                        "clone",
                    )?;
                }
            }
        }
    }
    errln(&format!("info: Recording as a local branch"));
    let args = vec!["checkout".to_string(), name.clone()];
    crate::git::git_capture(ctx, &args)?;
    Ok(EXIT_OK)
}
