fn spill(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let mut stack = stack_of(ctx, m)?;
    crate::git::check_conflicts(ctx)?;
    let name = stack
        .applied
        .last()
        .cloned()
        .ok_or_else(|| anyhow!("no patches applied"))?;
    let meta = stack.meta.get(&name).cloned().unwrap_or_default();
    let paths: Vec<String> =
        m.get_many::<String>("path").map(|v| v.cloned().collect()).unwrap_or_default();
    // the new patch tree: the bottom tree with the given paths reverted
    let mut new_tree = meta.bottom;
    if !paths.is_empty() {
        // start from the current top and revert the given paths to the bottom
        let cur = crate::git::tree_of(ctx, meta.top)?;
        let bot = crate::git::tree_of(ctx, meta.bottom)?;
        let mut entries: BTreeMap<String, (Oid, i32)> = BTreeMap::new();
        crate::stackops::tree_entries(ctx, &cur, String::new(), &mut entries)?;
        let mut bot_entries: BTreeMap<String, (Oid, i32)> = BTreeMap::new();
        crate::stackops::tree_entries(ctx, &bot, String::new(), &mut bot_entries)?;
        for p in &paths {
            match bot_entries.get(p) {
                Some(e) => {
                    entries.insert(p.clone(), *e);
                }
                None => {
                    entries.remove(p);
                }
            }
        }
        new_tree = crate::git::build_tree(ctx, &entries)?;
    }
    let oid = crate::git::create_commit(ctx, new_tree, &[stack.head], &meta.message.clone(), None)?;
    let o = stack.patches.get(&name).map(|x| x.to_string()).unwrap_or_default();
    let n = oid.to_string();
    let _ = crate::stackops::git(ctx, &["notes", "copy", &o, &n], None);
    let mut newmeta = meta.clone();
    newmeta.top = new_tree;
    if let Some(note) = m.try_get_one::<String>("annotate").ok().flatten() {
        newmeta.message = format!("{}\n\nNote: {note}", newmeta.message);
    }
    stack.meta.insert(name.clone(), newmeta);
    stack.patches.insert(name.clone(), oid);
    stack.head = oid;
    let mut report = crate::report::Report::new();
    report.refresh(vec![name.clone()]);
    let head_name = stack.applied.last().cloned();
    report.finish(head_name.as_deref());
    stack.save(ctx, &format!("spill {name}"))?;
    out(&report.render());
    Ok(EXIT_OK)
}

fn squash(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let mut stack = stack_of(ctx, m)?;
    crate::git::check_conflicts(ctx)?;
    crate::git::check_index(ctx)?;
    let targets: Vec<String> = m
        .get_many::<String>("patch")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    if targets.is_empty() {
        bail!("the following required arguments were not provided:\n  <patch>...");
    }
    let applied = stack.applied.clone();
    let lowest = targets
        .iter()
        .filter_map(|n| applied.iter().position(|x| x == n))
        .min()
        .ok_or_else(|| anyhow!("patch `{}` does not exist", targets[0]))?;
    let to_pop: Vec<String> = applied[lowest..].to_vec();
    let mut report = crate::report::Report::new();
    for name in to_pop.iter().rev() {
        crate::stackops::unapply(ctx, &mut stack, name)?;
    }
    report.unapply(to_pop.clone());
    // push the given patches in the order given
    let opts = crate::stackops::PushOpts::default();
    let mut last: Option<String> = None;
    for name in &targets {
        let c = crate::stackops::apply_patch(ctx, &mut stack, &mut report, name, &opts)?;
        stack.unapplied.retain(|x| x != name);
        if c {
            conflicted_save(ctx, &mut stack, &mut report, "squash")?;
            bail!("merge conflicts; resolve conflicts manually then refresh or undo the operation with `stg undo --hard`.");
        }
        last = Some(name.clone());
    }
    // delete all but the last of the given patches
    let top = last.ok_or_else(|| anyhow!("nothing to squash"))?;
    let new_name = m
        .try_get_one::<String>("name")
        .ok()
        .flatten()
        .cloned()
        .unwrap_or_else(|| top.clone());
    let mut deleted: Vec<String> = Vec::new();
    for name in &targets {
        if name != &top {
            stack.meta.remove(name);
            stack.patches.remove(name);
            stack.applied.retain(|x| x != name);
            stack.unapplied.retain(|x| x != name);
            deleted.push(name.clone());
        }
    }
    if !deleted.is_empty() {
        report.delete(deleted.clone());
    }
    // rename the squashed patch
    if new_name != top {
        if stack.patches.contains_key(&new_name) {
            bail!("patch `{new_name}` already exists");
        }
        if let Some(mt) = stack.meta.remove(&top) {
            stack.meta.insert(new_name.clone(), mt);
        }
        let oid = stack.patches.remove(&top).unwrap_or(Oid::zero());
        stack.patches.insert(new_name.clone(), oid);
        for l in [&mut stack.applied, &mut stack.unapplied, &mut stack.hidden] {
            for n in l.iter_mut() {
                if *n == top {
                    *n = new_name.clone();
                }
            }
        }
    }
    let head_name = stack.applied.last().cloned();
    report.finish(head_name.as_deref());
    stack.save(ctx, "squash")?;
    out(&report.render());
    Ok(EXIT_OK)
}

fn conflicted_save(ctx: &Ctx, stack: &mut Stack, report: &mut Report, msg: &str) -> Result<()> {
    let head_name = stack.applied.last().cloned();
    report.finish(head_name.as_deref());
    stack.save(ctx, &format!("{msg} (CONFLICT)"))?;
    out(&report.render());
    Ok(())
}
