/// Recursively collect the entries of a tree into a map of path -> (oid, mode).
pub fn tree_entries(
    ctx: &Ctx,
    tree: &git2::Tree,
    prefix: String,
    out: &mut BTreeMap<String, (Oid, i32)>,
) -> Result<()> {
    for i in 0..tree.len() {
        let e = tree.get(i).ok_or_else(|| anyhow!("bad tree entry"))?;
        let name = e.name().to_string();
        let full = if prefix.is_empty() { name.clone() } else { format!("{prefix}/{name}") };
        match e.kind() {
            Some(ObjectType::Tree) => {
                let sub = crate::git::tree_of(ctx, e.id())?;
                tree_entries(ctx, &sub, full, out)?;
            }
            _ => {
                out.insert(full, (e.id(), e.mode() as i32));
            }
        }
    }
    Ok(())
}
