fn pick(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let mut stack = stack_of(ctx, m)?;
    crate::git::check_conflicts(ctx)?;
    crate::git::check_index(ctx)?;
    let sources: Vec<String> = m
        .get_many::<String>("source")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    if sources.is_empty() {
        bail!("the following required arguments were not provided:\n  <source>...");
    }
    let ref_branch = m.try_get_one::<String>("ref-branch").ok().flatten().cloned();
    let mut report = crate::report::Report::new();
    let opts = crate::stackops::PushOpts {
        committer_date_is_author_date: m.get_flag("committer-date-is-author-date"),
        conflicts_allow: true,
        set_tree: false,
        keep: false,
    };
    for src in &sources {
        let (oid, name) = match &ref_branch {
            Some(b) => {
                let other = Stack::load(ctx, b)?;
                let oid = *other
                    .patches
                    .get(src)
                    .ok_or_else(|| anyhow!("patch `{src}` does not exist in branch `{b}`"))?;
                let nm = m
                    .try_get_one::<String>("name")
                    .ok()
                    .flatten()
                    .cloned()
                    .unwrap_or_else(|| src.clone());
                (oid, nm)
            }
            None => {
                let oid = crate::cmds::resolve_revision(ctx, m, src)?;
                let nm = m
                    .try_get_one::<String>("name")
                    .ok()
                    .flatten()
                    .cloned()
                    .unwrap_or_else(|| {
                        crate::git::commit_message(ctx, oid)
                            .ok()
                            .and_then(|msg| crate::patchdesc::generate_name(&msg, &stack).ok())
                            .unwrap_or_else(|| src.clone())
                    });
                (oid, nm)
            }
        };
        if stack.patches.contains_key(&name) {
            bail!("patch `{name}` already exists");
        }
        let commit = crate::git::commit_of(ctx, oid)?;
        let tree = commit.tree_id();
        let parent = commit.parent_ids().next().unwrap_or(Oid::zero());
        let bottom = if parent.is_zero() {
            tree
        } else {
            crate::git::commit_of(ctx, parent)?.tree_id()
        };
        let meta = crate::stack::PatchMeta {
            bottom,
            top: tree,
            author: crate::patchdesc::commit_author(&commit),
            date: crate::patchdesc::commit_date(&commit),
            message: commit.message().unwrap_or("").to_string(),
        };
        // the new patch commit, rebased onto the current head
        let new_oid = crate::git::create_commit(ctx, tree, &[stack.head], &meta.message.clone(), None)?;
        let mut newmeta = meta.clone();
        newmeta.bottom = crate::git::commit_of(ctx, stack.head)?.tree_id();
        newmeta.top = tree;
        stack.meta.insert(name.clone(), newmeta);
        stack.patches.insert(name.clone(), new_oid);
        if m.get_flag("noapply") {
            stack.unapplied.push(name.clone());
        } else {
            let c = crate::stackops::apply_patch(ctx, &mut stack, &mut report, &name, &opts)?;
            if c {
                conflicted_save(ctx, &mut stack, &mut report, "pick")?;
                bail!("merge conflicts; resolve conflicts manually then refresh or undo the operation with `stg undo --hard`.");
            }
        }
    }
    let head_name = stack.applied.last().cloned();
    report.finish(head_name.as_deref());
    stack.save(ctx, "pick")?;
    out(&report.render());
    Ok(EXIT_OK)
}
