fn completion(ctx: &mut Ctx, m: &ArgMatches) -> Result<i32> {
    let sub = match m.subcommand_name() {
        Some(s) => s.to_string(),
        None => bail!("'stg completion' requires a subcommand but one was not provided"),
    };
    let out_path = m.try_get_one::<String>("output").ok().flatten().cloned();
    let content: String = match sub.as_str() {
        "bash" => include_str!("completions/bash.txt").to_string(),
        "fish" => include_str!("completions/fish.txt").to_string(),
        "zsh" => include_str!("completions/zsh.txt").to_string(),
        "man" => {
            // write asciidoc man pages to the output directory
            let dir = out_path.unwrap_or_else(|| ".".to_string());
            crate::cmds::completion_man(ctx, &dir)?;
            return Ok(EXIT_OK);
        }
        "list" => {
            return completion_list(ctx, m);
        }
        _ => bail!("unknown completion subcommand {sub}"),
    };
    match out_path {
        Some(p) => std::fs::write(p, &content).map_err(|e| anyhow!("{e}"))?,
        None => out(&content),
    }
    Ok(EXIT_OK)
}

fn completion_list(ctx: &Ctx, m: &ArgMatches) -> Result<i32> {
    let sub = match m.subcommand_name() {
        Some(s) => s.to_string(),
        None => bail!("'stg completion list' requires a subcommand but one was not provided"),
    };
    let style = m
        .try_get_one::<String>("style")
        .ok()
        .flatten()
        .cloned()
        .unwrap_or_else(|| "name-only".to_string());
    let mut names: Vec<String> = Vec::new();
    match sub.as_str() {
        "commands" => {
            for (h, ns) in crate::cmds::top_level_groups() {
                let _ = h;
                for n in ns {
                    names.push(n.to_string());
                }
            }
            names.push("help".to_string());
        }
        "aliases" => {
            for (n, _) in crate::cmds::alias_list() {
                names.push(n.to_string());
            }
        }
        "commands-and-aliases" => {
            for (h, ns) in crate::cmds::top_level_groups() {
                let _ = h;
                for n in ns {
                    names.push(n.to_string());
                }
            }
            for (n, _) in crate::cmds::alias_list() {
                names.push(n.to_string());
            }
            names.push("help".to_string());
        }
        _ => bail!("unknown completion list subcommand {sub}"),
    }
    let text = match style.as_str() {
        "name-only" => names.join("\n") + "\n",
        _ => names.join("\n") + "\n",
    };
    let path = m.try_get_one::<String>("output").ok().flatten().cloned();
    match path {
        Some(p) => std::fs::write(p, &text).map_err(|e| anyhow!("{e}"))?,
        None => out(&text),
    }
    Ok(EXIT_OK)
}
