        let o = crate::git::git_capture(ctx, &args)?;
        out(&o);
        return Ok(EXIT_OK);
    }
    if sources.is_empty() {
        bail!("the following required arguments were not provided:\n  <file|directory>...");
    }
    let mut args: Vec<String> = vec!["send-email".into()];
    args.extend(sources);
    let o = crate::git::git_capture(ctx, &args)?;
    out(&o);
    Ok(EXIT_OK)
}
